INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C1','math',6,2,'u4',2,'비의 성질 — 비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 같은 수로 나누어도 비율은 같음을 알고(같은 수를 더하는 것은 성질이 아님), 전항·후항·비율을 바르게 읽기',ARRAY['6수02-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C2','math',6,2,'u4',3,'자연수의 비를 간단한 자연수의 비로 나타내기 — 두 항의 공약수로 더 나눌 수 없을 때까지(최대공약수로) 나누기',ARRAY['6수02-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C3','math',6,2,'u4',3,'소수의 비를 간단한 자연수의 비로 나타내기 — 두 항이 모두 자연수가 되도록 10·100을 곱한 뒤 공약수로 나누기',ARRAY['6수02-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C4','math',6,2,'u4',3,'분수의 비와 소수·분수가 섞인 비를 간단한 자연수의 비로 나타내기 — 두 분모의 공배수를 곱하거나, 한쪽을 소수(분수)로 바꾸어 같은 꼴로 만든 뒤 나타내기',ARRAY['6수02-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C5','math',6,2,'u4',4,'비례식과 외항·내항 — 비율이 같은 두 비를 등호로 이은 식을 비례식이라 하고, 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라 하며, 비례식인지는 수의 모양이 아니라 비율로 판단하기',ARRAY['6수02-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C6','math',6,2,'u4',5,'비례식의 성질 — 비례식에서 외항의 곱과 내항의 곱이 같음을 알고, 이를 이용하여 □가 있는 비례식을 풀거나 비례식인지 확인하기',ARRAY['6수02-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C7','math',6,2,'u4',6,'비례식을 세워 생활 문제 해결하기 — 함께 같은 비율로 변하는 두 양에서 구하려는 것을 □로 두고 대응이 맞게 비례식을 세운 뒤 비례식의 성질이나 비의 성질로 풀기',ARRAY['6수02-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C8','math',6,2,'u4',7,'비례배분 — 전체를 가：나로 배분할 때 전체를 (가+나)칸으로 갈라 전체 × (가 ÷ (가+나)), 전체 × (나 ÷ (가+나))로 구하기',ARRAY['6수02-05']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C9','math',6,2,'u4',8,'비례배분 활용 — 먼저 전체에서 우리 몫을 비례배분한 뒤 그 몫을 다시 정한 기준(낸 금액·만든 수 등)의 비로 나누고, 기준에 따라 몫이 달라짐을 알기',ARRAY['6수02-05']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X01','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C5']::text[],'전항과 후항에 같은 수를 더하거나 빼도 비율이 같다고 본다(2：3에 2를 더해 4：5)','더하기는 비의 성질이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X02','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'전항과 후항 가운데 한 항에만 곱하거나 한 항만 나눈다','두 항을 똑같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X03','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5']::text[],'전항과 후항(비교하는 양과 기준량)을 바꾸어 쓰거나 비율의 기준량을 잘못 잡는다','「무엇에 대한」 쪽이 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X04','math',6,'u4',ARRAY['M6-2-u4-C1']::text[],'전항과 후항에 0을 곱하거나 0으로 나누어도 된다고 본다','0이 아닌 같은 수만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X05','math',6,'u4',ARRAY['M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'공약수로 끝까지 나누지 않아 가장 간단한 자연수의 비가 아닌 채로 멈춘다','더 나눌 공약수가 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X06','math',6,'u4',ARRAY['M6-2-u4-C3','M6-2-u4-C4']::text[],'소수의 비에서 곱하는 수를 잘못 정해(한 자리 수에만 맞춰 10만 곱하는 등) 자연수가 되지 않거나 비가 달라진다','두 항이 모두 자연수가 되도록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X07','math',6,'u4',ARRAY['M6-2-u4-C4']::text[],'분수의 비에서 분모끼리 또는 분자끼리만 떼어 비로 쓴다(⟨1/5⟩：⟨1/7⟩을 5：7이나 1：1로)','두 분모의 공배수를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X08','math',6,'u4',ARRAY['M6-2-u4-C4']::text[],'분수의 비에서 두 분모의 공배수가 아닌 수(한 분모)만 곱해 한 항이 자연수가 되지 않는다','공배수라야 둘 다 자연수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X09','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'두 비의 수 모양만 보고(같은 수가 들어 있으면) 비례식이라고 판단한다(7：4 = 4：7)','비율을 견주어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X10','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'외항과 내항을 바꾸어 안다(안쪽 두 수를 외항으로)','바깥 둘이 외항') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X11','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱한다','바깥끼리, 안쪽끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X12','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항의 곱과 내항의 곱을 같게 놓은 뒤 □를 구하지 않고 곱한 값을 답으로 쓰거나 나눗셈을 잘못한다','곱 ÷ 아는 수 = □') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X13','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'비례식을 세울 때 대응을 어긋나게 놓는다(2：8000 = 40000：★처럼 무게와 값의 자리를 바꿈)','같은 종류끼리 같은 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X14','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'두 양이 같은 비율로 변하는지 보지 않고 차이(더하기·빼기)로 늘린다','몇 배가 되었는지 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X15','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 전체를 비의 한 항(가 또는 나)으로 나눈다(1200을 2：3으로 → 1200 ÷ 2)','한 묶음은 (가+나)칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X16','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 (가 ÷ (가+나)) 대신 (가 ÷ 나)를 곱하거나 한 칸의 양을 답으로 쓴다','분모는 가+나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X17','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분한 두 몫 가운데 다른 쪽의 몫을 답으로 쓴다','누구의 몫을 묻나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X18','math',6,'u4',ARRAY['M6-2-u4-C9']::text[],'두 번 나누어야 할 때 첫 단계(전체에서 우리 몫)를 건너뛰고 전체를 바로 나눈다','먼저 우리 몫부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X19','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'묻는 말을 거꾸로 읽는다 — 알맞은↔알맞지 않은, 외항↔내항, 큰↔작은','물음의 「않은·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X20','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'곱셈·나눗셈·약분 계산을 잘못한다','거꾸로 곱해서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X21','math',6,'u4',ARRAY['M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'간단한 자연수의 비가 나타낸 방법(소수로 바꾸기·분수로 바꾸기)이나 나눈 공약수에 따라 비율이 달라진다고 여긴다 — 14：12와 7：6처럼 비율이 같은 비를 서로 다른 답으로 보거나, 가장 간단한 비가 아니면 틀린 비라고 본다','어느 방법으로 나타내도 비율은 같아요 — 가장 간단한 비가 아니어도 비율이 같으면 같은 비') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X22','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C7']::text[],'비례식의 꼴은 하나뿐이라고 여긴다 — 두 비의 자리를 바꾼 식(⟨1/9⟩：⟨1/12⟩ = 4：3)이나 같은 종류끼리 비를 만든 식(2：★ = 8000：40000)을 틀렸다고 본다','두 비의 비율이 같고 대응이 맞으면 어느 꼴로 세워도 비례식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X23','math',6,'u4',ARRAY['M6-2-u4-C9']::text[],'공정한 배분 기준은 하나뿐이라고 여긴다 — 낸 금액·만든 수처럼 다른 기준으로 나눈 친구의 방법을 까닭을 듣지 않고 틀렸다고 본다','기준에 따라 몫이 달라져요 — 까닭을 들어 정한 기준이면 함께 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#1','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','바구니에 토마토 4개, 당근 3개를 담았어요. 담은 당근 수와 토마토 수의 비는 어느 것인가요?',ARRAY['M6-2-u4-X03']::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"바구니에 토마토 4개, 당근 3개를 담았어요. 담은 당근 수와 토마토 수의 비는 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"4：3","mis":"M6-2-u4-X03"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：4","mis":"M6-2-u4-X03"}],"explanation":["비 「■ 대 ▲」는 ■：▲로 써요.","당근 수가 앞(비교하는 양), 토마토 수가 뒤(기준량)예요.","그래서 3：4예요."],"variant_rule":{"alt":[{"stem":"7에 대한 6의 비는 어느 것인가요?","options":[{"t":"6：7","correct":true},{"t":"7：6","mis":"M6-2-u4-X03"},{"t":"6：13","mis":"M6-2-u4-X03"},{"t":"13：7","mis":"M6-2-u4-X03"}],"explanation":["비 「■ 대 ▲」는 ■：▲로 써요.","「7에 대한」의 7이 기준량이라 뒤에 와요.","그래서 6：7이에요."]},{"stem":"10과 3의 비는 어느 것인가요?","options":[{"t":"10：3","correct":true},{"t":"3：10","mis":"M6-2-u4-X03"},{"t":"10：13","mis":"M6-2-u4-X03"},{"t":"13：3","mis":"M6-2-u4-X03"}],"explanation":["비 「■ 대 ▲」는 ■：▲로 써요.","「10과 3의 비」는 앞에 말한 10이 전항이에요.","그래서 10：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#2','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','학생 7명 가운데 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X19']::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"학생 7명 가운데 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨7/2⟩","mis":"M6-2-u4-X03"},{"t":"⟨2/9⟩","mis":"M6-2-u4-X03"},{"t":"⟨5/7⟩","mis":"M6-2-u4-X19"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","전체 학생 수 7명이 기준량, 안경을 쓴 학생 수 2명이 비교하는 양이에요.","비율은 2 ÷ 7 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"9：20의 비율을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨9/20⟩","correct":true},{"t":"⟨20/9⟩","mis":"M6-2-u4-X03"},{"t":"⟨9/29⟩","mis":"M6-2-u4-X03"},{"t":"⟨11/20⟩","mis":"M6-2-u4-X19"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","9：20에서 비교하는 양은 9, 기준량은 20이에요.","비율은 9 ÷ 20 = ⟨9/20⟩예요."]},{"stem":"27：15의 비율을 기약분수로 나타내면 얼마인가요?","options":[{"t":"⟨9/5⟩","correct":true},{"t":"⟨5/9⟩","mis":"M6-2-u4-X03"},{"t":"⟨9/14⟩","mis":"M6-2-u4-X03"},{"t":"⟨14/5⟩","mis":"M6-2-u4-X19"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","27：15에서 비교하는 양은 27, 기준량은 15예요.","비율은 27 ÷ 15 = ⟨9/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#3','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 2개를 만들 때 초록 색종이가 4장이면 빨간 색종이는 몇 장이 필요한가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 2개를 만들 때 초록 색종이가 4장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["6"],"explanation":["꽃다발 1개는 초록 2장, 빨강 3장 — 2：3이에요.","꽃다발 2개면 두 항이 모두 2배라 4：6이에요.","빨간 색종이는 3 × 2 = 6(장)이에요."],"variant_rule":{"alt":[{"stem":"교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 3개를 만들 때 초록 색종이가 6장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["9"],"explanation":["꽃다발 1개는 초록 2장, 빨강 3장 — 2：3이에요.","꽃다발 3개면 두 항이 모두 3배라 6：9예요.","빨간 색종이는 3 × 3 = 9(장)이에요."]},{"stem":"순달이는 비눗방울 용액 2컵과 물 1컵을 섞어 비눗방울 놀이를 해요. 용액을 4컵 넣어 양을 늘리면 물은 몇 컵을 넣어야 하나요?","answer":["2"],"explanation":["용액과 물의 비는 2：1이에요.","용액이 2컵에서 4컵으로 2배가 되었어요.","물도 1 × 2 = 2(컵) — 4：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#4','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','2：3의 전항과 후항에 똑같이 □를 곱하면 4：6이 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"2：3의 전항과 후항에 똑같이 □를 곱하면 4：6이 돼요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항을 견주면 2 × 2 = 4예요.","후항도 3 × 2 = 6 — □는 2예요."],"variant_rule":{"alt":[{"stem":"6：9의 전항과 후항을 똑같이 □로 나누면 2：3이 돼요. □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항을 견주면 6 ÷ 3 = 2예요.","후항도 9 ÷ 3 = 3 — □는 3이에요."]},{"stem":"12：20의 전항과 후항을 똑같이 □로 나누면 3：5가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항을 견주면 12 ÷ 4 = 3이에요.","후항도 20 ÷ 4 = 5 — □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#5','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'sa','auto','7：2의 전항과 후항에 똑같이 5를 곱하면 35：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"7：2의 전항과 후항에 똑같이 5를 곱하면 35：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항은 7 × 5 = 35예요.","후항도 2 × 5 = 10 — 35：10이에요."],"variant_rule":{"alt":[{"stem":"12：20의 전항과 후항을 똑같이 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 나누어도 비율은 같아요.","전항은 12 ÷ 4 = 3이에요.","후항도 20 ÷ 4 = 5 — 3：5예요."]},{"stem":"3：11의 전항과 후항에 똑같이 3을 곱하면 9：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["33"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항은 3 × 3 = 9예요.","후항도 11 × 3 = 33 — 9：33이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#6','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":6,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 2를 더해 8：6을 구한다","correct":true},{"t":"전항과 후항에 2를 곱해 12：8을 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항을 2로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"비율이 ⟨3/2⟩인 비를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 0이 아닌 같은 수를 곱하거나 나누어 만들어요.","12：8과 3：2는 모두 비율이 ⟨3/2⟩이에요.","8：6은 비율이 ⟨4/3⟩ — 같은 수를 더하는 것은 비의 성질이 아니에요."],"variant_rule":{"alt":[{"stem":"2：5와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 4를 더해 6：9를 구한다","correct":true},{"t":"전항과 후항에 2를 곱해 4：10을 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 3을 곱해 6：15를 구한다","mis":"M6-2-u4-X19"},{"t":"비율이 ⟨2/5⟩인 비를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 0이 아닌 같은 수를 곱하거나 나누어 만들어요.","4：10과 6：15는 모두 비율이 ⟨2/5⟩예요.","6：9는 비율이 ⟨2/3⟩ — 같은 수를 더하는 것은 비의 성질이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#7','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','45：18과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":7,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"45：18과 비율이 같은 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"42：15","mis":"M6-2-u4-X01"},{"t":"18：45","mis":"M6-2-u4-X03"},{"t":"45：9","mis":"M6-2-u4-X02"}],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 나누어도 비율은 같아요.","45：18의 두 항을 9로 나누면 5：2예요.","같은 수를 더하거나 빼거나 한 항만 바꾸면 비율이 달라져요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 45：18과 비율이 같은 비는 어느 것인가요?","options":[{"t":"90：36","correct":true},{"t":"48：21","mis":"M6-2-u4-X01"},{"t":"36：90","mis":"M6-2-u4-X03"},{"t":"90：18","mis":"M6-2-u4-X02"}],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 나누어도 비율은 같아요.","45：18의 두 항에 2를 곱하면 90：36이에요.","같은 수를 더하거나 빼거나 한 항만 바꾸면 비율이 달라져요."]},{"stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"6：9","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"9：6","mis":"M6-2-u4-X03"},{"t":"6：3","mis":"M6-2-u4-X02"}],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 나누어도 비율은 같아요.","2：3의 두 항에 3을 곱하면 6：9예요.","같은 수를 더하거나 빼거나 한 항만 바꾸면 비율이 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#8','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'ox','auto','2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 같아요.',ARRAY['M6-2-u4-X04']::text[],true,'{"seq":8,"concept":"M6-2-u4-C1","difficulty":2,"kind":"ox","stem":"2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 같아요.","answer":"X","reason_options":[{"t":"0을 곱하면 0：0이 되어 비율을 말할 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"mis":"M6-2-u4-X04","explanation":["비의 성질은 0이 아닌 같은 수를 곱할 때만 써요.","2：3에 0을 곱하면 0：0이 돼요.","0：0은 비율을 나타낼 수 없어서 0을 곱할 수 없어요."],"variant_rule":{"alt":[{"stem":"6：9의 전항과 후항을 똑같이 0으로 나누어도 비율은 같아요.","answer":"X","reason_options":[{"t":"어떤 수도 0으로는 나눌 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"explanation":["비의 성질은 0이 아닌 같은 수로 나눌 때만 써요.","0으로 나누는 계산은 할 수 없어요.","그래서 6：9의 두 항을 0으로 나눌 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#9','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','일반적으로 쓰는 화면의 가로와 세로의 비는 16：9예요. 가로와 세로의 비가 16：9와 비율이 같은 화면은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"일반적으로 쓰는 화면의 가로와 세로의 비는 16：9예요. 가로와 세로의 비가 16：9와 비율이 같은 화면은 어느 것인가요?","options":[{"t":"다 (가로 32 cm, 세로 18 cm)","correct":true},{"t":"가 (가로 4 cm, 세로 3 cm)","mis":"M6-2-u4-X09"},{"t":"나 (가로 20 cm, 세로 15 cm)","mis":"M6-2-u4-X01"},{"t":"가로와 세로의 비가 16：10인 화면","mis":"M6-2-u4-X02"}],"explanation":["가는 4：3, 나는 20：15, 다는 32：18이에요.","16：9의 전항과 후항에 2를 곱하면 32：18이에요.","그래서 다 화면이 16：9와 비율이 같아요 — 크기가 달라도 모양이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_basic#10','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',3,'sa','auto','45：18과 비율이 같은 비 가운데 전항이 5인 비가 있어요. 그 비의 후항은 얼마인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u4-C1","difficulty":3,"kind":"sa","stem":"45：18과 비율이 같은 비 가운데 전항이 5인 비가 있어요. 그 비의 후항은 얼마인가요?","answer":["2"],"explanation":["45를 5로 만들려면 9로 나누어야 해요.","후항도 똑같이 9로 나누면 18 ÷ 9 = 2예요.","그래서 45：18 = 5：2 — 후항은 2예요."],"variant_rule":{"alt":[{"stem":"45：18과 비율이 같은 비 가운데 전항이 90인 비가 있어요. 그 비의 후항은 얼마인가요?","answer":["36"],"explanation":["45를 90으로 만들려면 2를 곱해야 해요.","후항에도 똑같이 2를 곱하면 18 × 2 = 36이에요.","그래서 90：36 — 후항은 36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#1','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'mc','auto','교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 2개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X02','M6-2-u4-X03']::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 2개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"4：3","mis":"M6-2-u4-X02"},{"t":"6：4","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 2개면 초록 색종이도 빨간 색종이도 2배가 돼요.","초록 4장, 빨강 6장 — 4：6이에요.","비율은 그대로 ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 3개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"6：9","correct":true},{"t":"5：6","mis":"M6-2-u4-X01"},{"t":"6：3","mis":"M6-2-u4-X02"},{"t":"9：6","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 3개면 초록 색종이도 빨간 색종이도 3배가 돼요.","초록 6장, 빨강 9장 — 6：9예요.","비율은 그대로 ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#2','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'match','auto','비율이 같은 비끼리 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":2,"kind":"match","stem":"비율이 같은 비끼리 이으세요.","pairs":[{"l":"7：2","r":"35：10"},{"l":"12：20","r":"3：5"},{"l":"45：18","r":"5：2"}],"mis":"M6-2-u4-X01","explanation":["7：2의 두 항에 5를 곱하면 35：10이에요.","12：20의 두 항을 4로 나누면 3：5예요.","45：18의 두 항을 9로 나누면 5：2예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율이 같은 비끼리 이으세요.","pairs":[{"l":"16：9","r":"32：18"},{"l":"6：4","r":"3：2"},{"l":"2：3","r":"4：6"}],"explanation":["16：9의 두 항에 2를 곱하면 32：18이에요.","6：4의 두 항을 2로 나누면 3：2예요.","2：3의 두 항에 2를 곱하면 4：6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#3','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'error','auto','6：4와 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X19']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":3,"kind":"error","stem":"6：4와 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유진 — 「두 항에 2를 더한 8：6도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"지호 — 「두 항에 2를 곱한 12：8은 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"희우 — 「두 항을 2로 나눈 3：2도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"준기 — 「세 비의 비율은 모두 ⟨3/2⟩야.」","mis":"M6-2-u4-X19"}],"explanation":["12：8과 3：2는 두 항에 같은 수를 곱하거나 나눈 비라 비율이 ⟨3/2⟩이에요.","8：6은 비율이 ⟨4/3⟩로 달라요.","같은 수를 더하는 것은 비의 성질이 아니에요 — 유진이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"2：5와 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「두 항에 4를 더한 6：9도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"다운 — 「두 항에 3을 곱한 6：15는 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"정후 — 「두 항에 2를 곱한 4：10도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"연아 — 「비율이 같은 비는 비율이 모두 ⟨2/5⟩야.」","mis":"M6-2-u4-X19"}],"explanation":["6：15와 4：10은 비율이 ⟨2/5⟩예요.","6：9는 비율이 ⟨2/3⟩로 달라요.","두 항에 4를 더한 것은 덧셈으로 생각한 오류예요 — 민지가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#4','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'ox','auto','꽃다발 2개를 만들 때의 4：6과 꽃다발 3개를 만들 때의 6：9는 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"꽃다발 2개를 만들 때의 4：6과 꽃다발 3개를 만들 때의 6：9는 비율이 같아요.","answer":"O","reason_options":[{"t":"두 비 모두 2：3의 두 항에 같은 수를 곱한 비라서","correct":true},{"t":"4：6의 두 항에 2와 3을 더한 비가 6：9라서","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["4：6을 2로 나누면 2：3이에요.","6：9를 3으로 나누면 2：3이에요.","그래서 비율은 모두 ⟨2/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"2：5와 6：9는 비율이 같아요.","answer":"X","reason_options":[{"t":"6：9는 2：5의 두 항에 4를 더한 비라 비율이 달라서","correct":true},{"t":"두 항에 똑같이 4를 더했으니 비율이 같아서","mis":"M6-2-u4-X01"}],"explanation":["2：5의 비율은 ⟨2/5⟩예요.","6：9의 비율은 ⟨2/3⟩예요.","같은 수를 더하면 비율이 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#5','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'sa','auto','화면의 가로와 세로의 비가 16：9예요. 이 화면과 모양이 같은 화면의 가로가 32 cm라면 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C1","difficulty":3,"kind":"sa","stem":"화면의 가로와 세로의 비가 16：9예요. 이 화면과 모양이 같은 화면의 가로가 32 cm라면 세로는 몇 cm인가요?","answer":["18"],"explanation":["16을 32로 만들려면 2를 곱해야 해요.","세로도 9 × 2 = 18(cm)예요.","32：18은 16：9와 비율이 같아요."],"variant_rule":{"alt":[{"stem":"가로와 세로의 비가 5：3인 직사각형을 그렸어요. 가로가 15 cm일 때 세로는 몇 cm인가요?","answer":["9"],"explanation":["5를 15로 만들려면 3을 곱해야 해요.","세로도 3 × 3 = 9(cm)예요.","15：9는 5：3과 비율이 같아요."]},{"stem":"철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 확대한 사진의 가로가 16 cm일 때 세로는 몇 cm인가요?","answer":["10"],"explanation":["가로 8 cm가 16 cm로 2배가 되었어요.","세로도 5 × 2 = 10(cm)예요.","16：10은 8：5와 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#6','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'mc','auto','비의 전항과 후항을 0으로 나눌 수 없는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u4-X04','M6-2-u4-X02','M6-2-u4-X03']::text[],false,'{"seq":6,"concept":"M6-2-u4-C1","difficulty":3,"kind":"mc","stem":"비의 전항과 후항을 0으로 나눌 수 없는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"0으로 나누는 계산은 할 수 없어서","correct":true},{"t":"0으로 나누면 비율이 2배가 되어서","mis":"M6-2-u4-X04"},{"t":"전항만 0이 되어서","mis":"M6-2-u4-X02"},{"t":"0으로 나누면 전항과 후항이 바뀌어서","mis":"M6-2-u4-X03"}],"explanation":["비의 성질은 0이 아닌 같은 수로 나눌 때만 써요.","어떤 수를 0으로 나누는 계산은 할 수 없어요.","그래서 「0이 아닌」 같은 수로 나눈다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#7','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'mc','auto','45：18과 비율이 같은 비가 아닌 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":7,"concept":"M6-2-u4-C1","difficulty":3,"kind":"mc","stem":"45：18과 비율이 같은 비가 아닌 것은 어느 것인가요?","options":[{"t":"48：21","correct":true},{"t":"5：2","mis":"M6-2-u4-X19"},{"t":"90：36","mis":"M6-2-u4-X19"},{"t":"15：6","mis":"M6-2-u4-X19"}],"explanation":["5：2, 90：36, 15：6은 45：18의 두 항을 9로 나누거나 2를 곱하거나 3으로 나눈 비예요.","48：21은 두 항에 3을 더한 비예요.","48：21의 비율은 ⟨16/7⟩ — 비율이 같은 비가 아니에요."],"variant_rule":{"alt":[{"stem":"6：4와 비율이 같은 비가 아닌 것은 어느 것인가요?","options":[{"t":"8：6","correct":true},{"t":"12：8","mis":"M6-2-u4-X19"},{"t":"3：2","mis":"M6-2-u4-X19"},{"t":"18：12","mis":"M6-2-u4-X19"}],"explanation":["12：8, 3：2, 18：12는 6：4의 두 항에 같은 수를 곱하거나 나눈 비예요.","8：6은 두 항에 2를 더한 비예요.","8：6의 비율은 ⟨4/3⟩ — 비율이 같은 비가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#8','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'mc','auto','45：18과 비율이 같은 비는 몇 개 만들 수 있나요?',ARRAY['M6-2-u4-X05','M6-2-u4-X19','M6-2-u4-X20']::text[],false,'{"seq":8,"concept":"M6-2-u4-C1","difficulty":4,"kind":"mc","stem":"45：18과 비율이 같은 비는 몇 개 만들 수 있나요?","options":[{"t":"셀 수 없이 많이 만들 수 있다","correct":true},{"t":"5：2 하나뿐이다","mis":"M6-2-u4-X05"},{"t":"5：2와 90：36 두 개뿐이다","mis":"M6-2-u4-X19"},{"t":"45와 18의 공약수 개수만큼이다","mis":"M6-2-u4-X20"}],"explanation":["두 항에 0이 아닌 같은 수를 곱하면 비율이 같은 비가 생겨요.","2배, 3배, 4배, …처럼 곱할 수 있는 수는 끝이 없어요.","그래서 비율이 같은 비는 셀 수 없이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#9','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'essay','teacher','순달이는 비눗방울 용액 2컵과 물 1컵을 섞어 비눗방울 놀이를 해요. 양을 늘리려고 용액을 4컵 넣었어요. 물은 몇 컵을 넣어야 하는지 구하고, 그렇게 섞어도 처음과 같은 비눗방울 용액이 되는 까닭을 비의 성질로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":4,"kind":"essay","stem":"순달이는 비눗방울 용액 2컵과 물 1컵을 섞어 비눗방울 놀이를 해요. 양을 늘리려고 용액을 4컵 넣었어요. 물은 몇 컵을 넣어야 하는지 구하고, 그렇게 섞어도 처음과 같은 비눗방울 용액이 되는 까닭을 비의 성질로 설명해 보세요.","answer_guide":{"answer":"예: 용액이 2컵에서 4컵으로 2배가 되었으므로 물도 1컵의 2배인 2컵을 넣는다. 2：1의 전항과 후항에 똑같이 2를 곱해 4：2가 되었고, 비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같으므로 처음과 같다.","scoring_points":["물 2컵을 구했는가","두 항에 똑같이 2를 곱했음을 밝혔는가","같은 수를 곱하면 비율이 같다는 까닭을 썼는가"]},"explanation":["용액 4컵은 2컵의 2배예요.","물도 1컵의 2배 — 2컵이에요.","4：2는 2：1과 비율이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L02_challenge#10','math',6,2,'u4','L02','tb_g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'essay','teacher','6：4와 비율이 같은 비를 두 개 만들고, 전항과 후항에 2를 더한 8：6이 6：4와 비율이 같지 않은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C1","difficulty":4,"kind":"essay","stem":"6：4와 비율이 같은 비를 두 개 만들고, 전항과 후항에 2를 더한 8：6이 6：4와 비율이 같지 않은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 6：4의 두 항에 2를 곱하면 12：8, 2로 나누면 3：2이다. 8：6은 두 항에 2를 더한 것인데 같은 수를 더하는 것은 비의 성질이 아니므로 비율이 ⟨4/3⟩가 되어 ⟨3/2⟩과 다르다.","scoring_points":["비율이 같은 비 두 개를 바르게 만들었는가","8：6은 같은 수를 더한 것임을 밝혔는가","두 비의 비율을 견주어 다름을 보였는가"]},"explanation":["12：8과 3：2는 비율이 ⟨3/2⟩이에요.","8：6은 2를 더한 비예요.","8：6의 비율은 ⟨4/3⟩ — 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#1','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',1,'sa','auto','2.1：5.6의 전항과 후항에 똑같이 10을 곱하면 21：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"2.1：5.6의 전항과 후항에 똑같이 10을 곱하면 21：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["56"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항은 2.1 × 10 = 21이에요.","후항도 5.6 × 10 = 56 — 21：56이에요."],"variant_rule":{"alt":[{"stem":"0.8：0.4의 전항과 후항에 똑같이 10을 곱하면 8：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항은 0.8 × 10 = 8이에요.","후항도 0.4 × 10 = 4 — 8：4예요."]},{"stem":"2.5：3의 전항과 후항에 똑같이 10을 곱하면 25：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["30"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항은 2.5 × 10 = 25예요.","후항도 3 × 10 = 30 — 25：30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#2','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',1,'sa','auto','21：56의 전항과 후항을 똑같이 7로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C2","difficulty":1,"kind":"sa","stem":"21：56의 전항과 후항을 똑같이 7로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 나누어도 비율은 같아요.","전항은 21 ÷ 7 = 3이에요.","후항도 56 ÷ 7 = 8 — 3：8이에요."],"variant_rule":{"alt":[{"stem":"28：63의 전항과 후항을 똑같이 7로 나누면 4：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 나누어도 비율은 같아요.","전항은 28 ÷ 7 = 4예요.","후항도 63 ÷ 7 = 9 — 4：9예요."]},{"stem":"14：12의 전항과 후항을 똑같이 2로 나누면 7：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 나누어도 비율은 같아요.","전항은 14 ÷ 2 = 7이에요.","후항도 12 ÷ 2 = 6 — 7：6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#3','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',1,'mc','auto','해바라기씨 간식의 영양 성분은 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이에요. 단백질량과 지방량의 비 2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":3,"concept":"M6-2-u4-C3","difficulty":1,"kind":"mc","stem":"해바라기씨 간식의 영양 성분은 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이에요. 단백질량과 지방량의 비 2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"4：8","mis":"M6-2-u4-X20"},{"t":"3：9","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 21：56이에요.","21과 56의 공약수 7로 나누면 3：8이에요.","그래서 단백질량과 지방량의 비는 3：8이에요."],"variant_rule":{"alt":[{"stem":"0.8：0.4를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X20"},{"t":"2：2","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 8：4예요.","8과 4의 공약수 4로 나누면 2：1이에요.","그래서 0.8：0.4 = 2：1의 비율 2와 같아요."]},{"stem":"2.5：3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：6","correct":true},{"t":"6：5","mis":"M6-2-u4-X03"},{"t":"25：3","mis":"M6-2-u4-X02"},{"t":"6：6","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 25：30이에요.","25와 30의 공약수 5로 나누면 5：6이에요.","그래서 간단한 자연수의 비는 5：6이에요."]},{"stem":"3.5：4.9를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：7","correct":true},{"t":"7：5","mis":"M6-2-u4-X03"},{"t":"6：7","mis":"M6-2-u4-X20"},{"t":"5：8","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 35：49예요.","35와 49의 공약수 7로 나누면 5：7이에요.","그래서 간단한 자연수의 비는 5：7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#4','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',1,'mc','auto','⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07']::text[],true,'{"seq":4,"concept":"M6-2-u4-C4","difficulty":1,"kind":"mc","stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"}],"explanation":["두 분모 6과 4의 공배수 12를 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 간단한 자연수의 비는 2：3이에요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"9：14","mis":"M6-2-u4-X03"},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"}],"explanation":["두 분모 3과 7의 공배수 21을 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 간단한 자연수의 비는 14：9예요."]},{"stem":"⟨1/3⟩：⟨3/11⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"11：9","correct":true},{"t":"9：11","mis":"M6-2-u4-X03"},{"t":"3：11","mis":"M6-2-u4-X07"},{"t":"1：3","mis":"M6-2-u4-X07"}],"explanation":["두 분모 3과 11의 공배수 33을 곱해요.","⟨1/3⟩ × 33 = 11, ⟨3/11⟩ × 33 = 9예요.","그래서 간단한 자연수의 비는 11：9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#5','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',2,'mc','auto','28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"5：9","mis":"M6-2-u4-X20"},{"t":"4：10","mis":"M6-2-u4-X20"}],"explanation":["28과 63의 공약수는 1과 7이에요.","두 항을 7로 나누면 4：9예요.","4와 9는 1 말고 공약수가 없어 더 간단히 할 수 없어요."],"variant_rule":{"alt":[{"stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X20"},{"t":"2：2","mis":"M6-2-u4-X20"}],"explanation":["54와 27의 최대공약수는 27이에요.","두 항을 27로 나누면 2：1이에요.","그래서 간단한 자연수의 비는 2：1이에요."]},{"stem":"45：18을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-2-u4-X03"},{"t":"6：2","mis":"M6-2-u4-X20"},{"t":"5：3","mis":"M6-2-u4-X20"}],"explanation":["45와 18의 최대공약수는 9예요.","두 항을 9로 나누면 5：2예요.","그래서 간단한 자연수의 비는 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#6','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":6,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"8：4","mis":"M6-2-u4-X20"},{"t":"7：5","mis":"M6-2-u4-X20"}],"explanation":["후항 ⟨2/5⟩를 소수로 바꾸면 0.4예요.","0.7：0.4의 두 항에 10을 곱하면 7：4예요.","전항을 분수 ⟨7/10⟩로 바꾸어 10을 곱해도 7：4로 같아요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"16：16","mis":"M6-2-u4-X20"},{"t":"15：17","mis":"M6-2-u4-X20"}],"explanation":["전항 ⟨3/4⟩을 소수로 바꾸면 0.75예요.","0.75：0.8의 두 항에 100을 곱하면 75：80이에요.","두 항을 5로 나누면 15：16이에요."]},{"stem":"0.5：⟨15/8⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：15","correct":true},{"t":"15：4","mis":"M6-2-u4-X03"},{"t":"5：15","mis":"M6-2-u4-X20"},{"t":"4：16","mis":"M6-2-u4-X20"}],"explanation":["전항 0.5를 분수 ⟨1/2⟩로 바꾸면 ⟨1/2⟩：⟨15/8⟩예요.","두 분모 2와 8의 공배수 8을 곱하면 4：15예요.","그래서 간단한 자연수의 비는 4：15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#7','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','⟨1/6⟩：⟨1/4⟩을 자연수의 비로 나타내려고 해요. 전항과 후항에 곱할 수로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X08']::text[],true,'{"seq":7,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨1/6⟩：⟨1/4⟩을 자연수의 비로 나타내려고 해요. 전항과 후항에 곱할 수로 알맞은 것은 어느 것인가요?","options":[{"t":"12","correct":true},{"t":"10","mis":"M6-2-u4-X01"},{"t":"6","mis":"M6-2-u4-X08"},{"t":"4","mis":"M6-2-u4-X08"}],"explanation":["두 항이 모두 자연수가 되는 수를 똑같이 곱해요.","분모 6과 4의 공배수(12, 24, 36, …)를 곱하면 두 항이 모두 자연수가 돼요.","그래서 12를 곱해요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩：⟨3/7⟩을 자연수의 비로 나타내려고 해요. 전항과 후항에 곱할 수로 알맞은 것은 어느 것인가요?","options":[{"t":"21","correct":true},{"t":"3","mis":"M6-2-u4-X08"},{"t":"7","mis":"M6-2-u4-X08"},{"t":"10","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되는 수를 똑같이 곱해요.","분모 3과 7의 공배수(21, 42, …)를 곱하면 두 항이 모두 자연수가 돼요.","그래서 21을 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#8','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',2,'mc','auto','2.1：5.6을 자연수의 비로 나타내려고 해요. 전항과 후항에 곱할 수로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X06']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"2.1：5.6을 자연수의 비로 나타내려고 해요. 전항과 후항에 곱할 수로 알맞은 것은 어느 것인가요?","options":[{"t":"10","correct":true},{"t":"7","mis":"M6-2-u4-X05"},{"t":"100","mis":"M6-2-u4-X06"},{"t":"2","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되는 수를 똑같이 곱해요.","소수 한 자리 수는 10을 곱하면 자연수가 돼요.","그래서 10을 곱해요."],"variant_rule":{"alt":[{"stem":"0.75：0.8을 자연수의 비로 나타내려고 해요. 전항과 후항에 곱할 수로 알맞은 것은 어느 것인가요?","options":[{"t":"100","correct":true},{"t":"10","mis":"M6-2-u4-X06"},{"t":"5","mis":"M6-2-u4-X05"},{"t":"8","mis":"M6-2-u4-X08"}],"explanation":["두 항이 모두 자연수가 되는 수를 똑같이 곱해요.","0.75는 소수 두 자리 수라 100을 곱해야 자연수가 돼요.","그래서 100을 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#9','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'sa','auto','준기는 꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 넣은 꿀의 양과 만든 꿀물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"sa","stem":"준기는 꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 넣은 꿀의 양과 만든 꿀물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["8"],"explanation":["넣은 꿀의 양과 만든 꿀물의 양의 비는 ⟨3/40⟩：⟨3/5⟩이에요.","⟨3/40⟩：⟨3/5⟩의 비율은 ⟨1/8⟩이에요.","그래서 간단한 자연수의 비로 1：8 — □는 8이에요."],"variant_rule":{"alt":[{"stem":"희우는 꿀 0.1컵을 넣어 꿀물 0.8컵을 만들었어요. 넣은 꿀의 양과 만든 꿀물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["8"],"explanation":["넣은 꿀의 양과 만든 꿀물의 양의 비는 0.1：0.8이에요.","0.1：0.8의 비율은 ⟨1/8⟩이에요.","그래서 간단한 자연수의 비로 1：8 — □는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_basic#10','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',3,'mc','auto','희우는 꿀 0.1컵을 넣어 꿀물 0.8컵을, 준기는 꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 두 꿀물의 진하기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X21']::text[],false,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"희우는 꿀 0.1컵을 넣어 꿀물 0.8컵을, 준기는 꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 두 꿀물의 진하기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"두 꿀물의 진하기는 같다","correct":true},{"t":"희우의 꿀물이 더 진하다","mis":"M6-2-u4-X09"},{"t":"준기의 꿀물이 더 진하다","mis":"M6-2-u4-X09"},{"t":"넣은 꿀의 양이 달라 비교할 수 없다","mis":"M6-2-u4-X21"}],"explanation":["희우: 0.1：0.8에 10을 곱하면 1：8이에요.","준기: ⟨3/40⟩：⟨3/5⟩에 40을 곱하면 3：24, 3으로 나누면 1：8이에요.","꿀의 양과 꿀물의 양의 비가 같으니 진하기가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#1','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',2,'mc','auto','1.4：⟨1 1/5⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"1.4：⟨1 1/5⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"8：6","mis":"M6-2-u4-X20"},{"t":"7：7","mis":"M6-2-u4-X20"}],"explanation":["후항 ⟨1 1/5⟩을 소수로 바꾸면 1.2예요.","1.4：1.2의 두 항에 10을 곱하면 14：12예요.","14：12의 두 항을 2로 나누면 7：6이에요."],"variant_rule":{"alt":[{"stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"8：4","mis":"M6-2-u4-X20"},{"t":"7：5","mis":"M6-2-u4-X20"}],"explanation":["전항 0.7을 분수 ⟨7/10⟩로 바꾸면 ⟨7/10⟩：⟨2/5⟩예요.","두 항에 10을 곱하면 7：4예요.","후항을 소수로 바꾸어 나타내도 7：4로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#2','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',2,'ox','auto','1.4：⟨1 1/5⟩을 14：12로 나타낸 친구도 비율이 같은 자연수의 비로 바르게 나타냈어요.',ARRAY['M6-2-u4-X21']::text[],true,'{"seq":2,"concept":"M6-2-u4-C4","difficulty":2,"kind":"ox","stem":"1.4：⟨1 1/5⟩을 14：12로 나타낸 친구도 비율이 같은 자연수의 비로 바르게 나타냈어요.","answer":"O","reason_options":[{"t":"14：12와 7：6은 비율이 ⟨7/6⟩로 같아서","correct":true},{"t":"가장 간단한 비가 아니면 비율이 달라져서","mis":"M6-2-u4-X21"}],"mis":"M6-2-u4-X21","explanation":["14：12의 비율은 ⟨7/6⟩이에요.","7：6의 비율도 ⟨7/6⟩이에요.","가장 간단한 비가 아니어도 비율이 같으면 바른 자연수의 비예요(지도서 273 채점)."],"variant_rule":{"alt":[{"stem":"2.1：5.6을 21：56으로 나타낸 친구도 비율이 같은 자연수의 비로 나타냈어요.","answer":"O","reason_options":[{"t":"21：56과 3：8은 비율이 ⟨3/8⟩으로 같아서","correct":true},{"t":"7로 더 나누지 않으면 비율이 달라져서","mis":"M6-2-u4-X21"}],"explanation":["21：56의 비율은 ⟨3/8⟩이에요.","3：8의 비율도 ⟨3/8⟩이에요.","21：56도 비율이 같은 자연수의 비예요 — 7로 나누면 더 간단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#3','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',3,'error','auto','2.5：3을 간단한 자연수의 비로 나타낸 풀이를 보았어요. 잘못 푼 친구는 누구인가요?',ARRAY['M6-2-u4-X02','M6-2-u4-X19','M6-2-u4-X21']::text[],true,'{"seq":3,"concept":"M6-2-u4-C3","difficulty":3,"kind":"error","stem":"2.5：3을 간단한 자연수의 비로 나타낸 풀이를 보았어요. 잘못 푼 친구는 누구인가요?","options":[{"t":"유진 — 「전항에만 10을 곱해서 25：3이에요.」","correct":true,"mis_target":"M6-2-u4-X02"},{"t":"지호 — 「두 항에 10을 곱해 25：30, 5로 나누어 5：6이에요.」","mis":"M6-2-u4-X19"},{"t":"희우 — 「두 항에 2를 곱해 5：6이에요.」","mis":"M6-2-u4-X19"},{"t":"준기 — 「두 항에 10을 곱한 25：30도 비율은 같아요.」","mis":"M6-2-u4-X21"}],"explanation":["비의 성질은 두 항에 똑같이 곱해야 해요.","25：3은 전항에만 10을 곱해 비율이 달라졌어요.","바른 비는 5：6(또는 비율이 같은 25：30)이에요 — 유진이가 잘못 풀었어요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타낸 풀이를 보았어요. 잘못 푼 친구는 누구인가요?","options":[{"t":"다운 — 「분모끼리 쓰면 6：4니까 3：2예요.」","correct":true,"mis_target":"M6-2-u4-X07"},{"t":"민지 — 「두 분모의 공배수 12를 곱해 2：3이에요.」","mis":"M6-2-u4-X19"},{"t":"정후 — 「공배수 24를 곱하면 4：6, 2로 나누면 2：3이에요.」","mis":"M6-2-u4-X19"},{"t":"연아 — 「24를 곱한 4：6도 비율은 2：3과 같아요.」","mis":"M6-2-u4-X21"}],"explanation":["분수의 비는 두 분모의 공배수를 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3 — 2：3이에요.","분모끼리 쓴 6：4(= 3：2)는 비율이 거꾸로예요 — 다운이가 잘못 풀었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#4','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',3,'mc','auto','0.7：⟨2/5⟩를 두 가지 방법(후항을 소수로 바꾸기, 전항을 분수로 바꾸기)으로 간단한 자연수의 비로 나타냈어요. 결과를 바르게 말한 것은 어느 것인가요?',ARRAY['M6-2-u4-X21','M6-2-u4-X06']::text[],false,'{"seq":4,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"0.7：⟨2/5⟩를 두 가지 방법(후항을 소수로 바꾸기, 전항을 분수로 바꾸기)으로 간단한 자연수의 비로 나타냈어요. 결과를 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 방법 모두 7：4로 같다","correct":true},{"t":"소수로 바꾸면 7：4, 분수로 바꾸면 4：7로 다르다","mis":"M6-2-u4-X21"},{"t":"분수로 바꾸는 방법만 자연수의 비가 된다","mis":"M6-2-u4-X21"},{"t":"소수로 바꾸면 7：40이 된다","mis":"M6-2-u4-X06"}],"explanation":["후항을 소수로: 0.7：0.4에 10을 곱하면 7：4예요.","전항을 분수로: ⟨7/10⟩：⟨2/5⟩에 10을 곱하면 7：4예요.","어느 방법으로 나타내도 비율이 같은 비가 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#5','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',3,'sa','auto','⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 15：□예요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C4","difficulty":3,"kind":"sa","stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 15：□예요. □에 알맞은 수는 얼마인가요?","answer":["16"],"explanation":["⟨3/4⟩을 소수로 바꾸면 0.75예요.","0.75：0.8에 100을 곱하면 75：80, 5로 나누면 15：16이에요.","그래서 □는 16이에요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩：⟨3/11⟩을 간단한 자연수의 비로 나타내면 11：□예요. □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["두 분모 3과 11의 공배수 33을 곱해요.","⟨1/3⟩ × 33 = 11, ⟨3/11⟩ × 33 = 9예요.","그래서 □는 9예요."]},{"stem":"0.5：⟨15/8⟩를 간단한 자연수의 비로 나타내면 4：□예요. □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["0.5를 분수 ⟨1/2⟩로 바꾸어요.","⟨1/2⟩：⟨15/8⟩에 8을 곱하면 4：15예요.","그래서 □는 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#6','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',3,'mc','auto','해바라기씨 간식의 영양 성분은 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이에요. 탄수화물량과 단백질량, 단백질량과 지방량 가운데 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X19','M6-2-u4-X02']::text[],false,'{"seq":6,"concept":"M6-2-u4-C3","difficulty":3,"kind":"mc","stem":"해바라기씨 간식의 영양 성분은 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이에요. 탄수화물량과 단백질량, 단백질량과 지방량 가운데 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"190：21","mis":"M6-2-u4-X19"},{"t":"21：5","mis":"M6-2-u4-X02"}],"explanation":["단백질량과 지방량의 비는 2.1：5.6이에요(탄수화물 19 g은 쓰지 않아요).","두 항에 10을 곱하면 21：56이에요.","7로 나누면 3：8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#7','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C2',3,'match','auto','간단한 자연수의 비로 나타낸 것끼리 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C2","difficulty":3,"kind":"match","stem":"간단한 자연수의 비로 나타낸 것끼리 이으세요.","pairs":[{"l":"28：63","r":"4：9"},{"l":"0.8：0.4","r":"2：1"},{"l":"2.5：3","r":"5：6"}],"mis":"M6-2-u4-X05","explanation":["28：63의 두 항을 7로 나누면 4：9예요.","0.8：0.4에 10을 곱하면 8：4, 4로 나누면 2：1이에요.","2.5：3에 10을 곱하면 25：30, 5로 나누면 5：6이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 간단한 자연수의 비로 나타낸 것끼리 이으세요.","pairs":[{"l":"54：27","r":"2：1"},{"l":"3.5：4.9","r":"5：7"},{"l":"⟨1/3⟩：⟨3/11⟩","r":"11：9"}],"explanation":["54：27의 두 항을 27로 나누면 2：1이에요.","3.5：4.9에 10을 곱하면 35：49, 7로 나누면 5：7이에요.","⟨1/3⟩：⟨3/11⟩에 33을 곱하면 11：9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#8','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',4,'mc','auto','⟨2/3⟩：⟨3/7⟩을 자연수의 비로 나타낼 때 전항과 후항에 곱해도 되는 수가 아닌 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C4","difficulty":4,"kind":"mc","stem":"⟨2/3⟩：⟨3/7⟩을 자연수의 비로 나타낼 때 전항과 후항에 곱해도 되는 수가 아닌 것은 어느 것인가요?","options":[{"t":"7","correct":true},{"t":"21","mis":"M6-2-u4-X19"},{"t":"42","mis":"M6-2-u4-X19"},{"t":"63","mis":"M6-2-u4-X19"}],"explanation":["두 분모 3과 7의 공배수를 곱해야 두 항이 모두 자연수가 돼요.","21, 42, 63은 3과 7의 공배수예요.","7을 곱하면 ⟨2/3⟩ × 7 = ⟨14/3⟩로 자연수가 아니에요 — 공배수가 아니에요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩：⟨1/4⟩을 자연수의 비로 나타낼 때 전항과 후항에 곱해도 되는 수가 아닌 것은 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"12","mis":"M6-2-u4-X19"},{"t":"24","mis":"M6-2-u4-X19"},{"t":"36","mis":"M6-2-u4-X19"}],"explanation":["두 분모 6과 4의 공배수를 곱해야 두 항이 모두 자연수가 돼요.","12, 24, 36은 6과 4의 공배수예요.","6을 곱하면 ⟨1/4⟩ × 6 = ⟨3/2⟩으로 자연수가 아니에요 — 공배수가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#9','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',4,'essay','teacher','해바라기씨 간식의 영양 성분은 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이에요. 단백질량과 지방량의 비 2.1：5.6을 간단한 자연수의 비로 나타내고, 소수의 비를 간단한 자연수의 비로 나타내는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C3","difficulty":4,"kind":"essay","stem":"해바라기씨 간식의 영양 성분은 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이에요. 단백질량과 지방량의 비 2.1：5.6을 간단한 자연수의 비로 나타내고, 소수의 비를 간단한 자연수의 비로 나타내는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2.1：5.6의 전항과 후항에 10을 곱하면 21：56이고, 21과 56의 공약수 7로 나누면 3：8이다. 소수의 비는 전항과 후항에 10, 100, …을 곱해 자연수의 비로 나타낸 다음 두 항의 공약수로 나누어 간단한 자연수의 비로 나타낸다.","scoring_points":["3：8을 구했는가","10을 곱해 자연수의 비로 만들었음을 밝혔는가","공약수로 나누는 단계를 설명했는가"]},"explanation":["두 항에 10을 곱하면 21：56이에요.","공약수 7로 나누면 3：8이에요.","소수의 비 → 10·100 곱하기 → 공약수로 나누기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L03_challenge#10','math',6,2,'u4','L03','tb_g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',4,'essay','teacher','1.4：⟨1 1/5⟩을 두 가지 방법으로 간단한 자연수의 비로 나타내고, 두 결과를 비교해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":4,"kind":"essay","stem":"1.4：⟨1 1/5⟩을 두 가지 방법으로 간단한 자연수의 비로 나타내고, 두 결과를 비교해 보세요.","answer_guide":{"answer":"예: 방법 1 — 후항 ⟨1 1/5⟩을 소수 1.2로 바꾸어 10을 곱하면 14：12, 2로 나누면 7：6이다. 방법 2 — 전항 1.4를 분수 ⟨14/10⟩로 바꾸어 두 분모의 공배수 10을 곱하면 14：12, 2로 나누면 7：6이다. 두 방법의 결과가 같다.","scoring_points":["한쪽을 소수로 바꾼 방법을 썼는가","한쪽을 분수로 바꾼 방법을 썼는가","두 결과가 7：6으로 같음을 밝혔는가"]},"explanation":["후항을 소수로: 1.4：1.2 → 14：12 → 7：6이에요.","전항을 분수로: ⟨14/10⟩：⟨6/5⟩ → 14：12 → 7：6이에요.","어느 방법이든 결과가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#1','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'mc','auto','비례식 8：5 = 16：10에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":1,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 8：5 = 16：10에서 외항은 어느 것인가요?","options":[{"t":"8과 10","correct":true},{"t":"5와 16","mis":"M6-2-u4-X10"},{"t":"8과 5","mis":"M6-2-u4-X11"},{"t":"16과 10","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","8：5 = 16：10에서 바깥쪽은 8과 10, 안쪽은 5와 16이에요.","그래서 외항은 8과 10이에요."],"variant_rule":{"alt":[{"stem":"비례식 7：9 = 14：18에서 외항은 어느 것인가요?","options":[{"t":"7과 18","correct":true},{"t":"9와 14","mis":"M6-2-u4-X10"},{"t":"7과 9","mis":"M6-2-u4-X11"},{"t":"14와 18","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","7：9 = 14：18에서 바깥쪽은 7과 18, 안쪽은 9와 14예요.","그래서 외항은 7과 18이에요."]},{"stem":"비례식 48：32 = 3：2에서 외항은 어느 것인가요?","options":[{"t":"48과 2","correct":true},{"t":"32와 3","mis":"M6-2-u4-X10"},{"t":"48과 32","mis":"M6-2-u4-X11"},{"t":"3과 2","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","48：32 = 3：2에서 바깥쪽은 48과 2, 안쪽은 32와 3이에요.","그래서 외항은 48과 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#2','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'mc','auto','비례식 56：21 = 8：3에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":2,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 56：21 = 8：3에서 내항은 어느 것인가요?","options":[{"t":"21과 8","correct":true},{"t":"56과 3","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X11"},{"t":"8과 3","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 내항은 21과 8이에요."],"variant_rule":{"alt":[{"stem":"비례식 9：11 = 18：22에서 내항은 어느 것인가요?","options":[{"t":"11과 18","correct":true},{"t":"9와 22","mis":"M6-2-u4-X10"},{"t":"9와 11","mis":"M6-2-u4-X11"},{"t":"18과 22","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","9：11 = 18：22에서 바깥쪽은 9와 22, 안쪽은 11과 18이에요.","그래서 내항은 11과 18이에요."]},{"stem":"비례식 6：3 = 24：12에서 내항은 어느 것인가요?","options":[{"t":"3과 24","correct":true},{"t":"6과 12","mis":"M6-2-u4-X10"},{"t":"6과 3","mis":"M6-2-u4-X11"},{"t":"24와 12","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","6：3 = 24：12에서 바깥쪽은 6과 12, 안쪽은 3과 24예요.","그래서 내항은 3과 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#3','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'sa','auto','철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 비례식 8：5 = 16：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":1,"kind":"sa","stem":"철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 비례식 8：5 = 16：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["확대하기 전 가로：세로 = 8：5예요.","확대한 후 가로：세로 = 16：10이에요.","8：5 = 16：10 — □는 10이에요."],"variant_rule":{"alt":[{"stem":"7：9의 전항과 후항에 2를 곱해 비례식 7：9 = 14：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["18"],"explanation":["전항과 후항에 같은 수를 곱해도 비율은 같아요.","9 × 2 = 18이에요.","그래서 7：9 = 14：18이에요."]},{"stem":"48：32의 전항과 후항을 16으로 나누어 비례식 48：32 = 3：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["전항과 후항을 같은 수로 나누어도 비율은 같아요.","32 ÷ 16 = 2예요.","그래서 48：32 = 3：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#4','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'mc','auto','철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 확대한 후 사진의 가로와 세로의 비 16：10의 비율을 기약분수로 나타내면 얼마인가요?',ARRAY['M6-2-u4-X03']::text[],false,'{"seq":4,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 확대한 후 사진의 가로와 세로의 비 16：10의 비율을 기약분수로 나타내면 얼마인가요?","options":[{"t":"⟨8/5⟩","correct":true},{"t":"⟨5/8⟩","mis":"M6-2-u4-X03"},{"t":"⟨16/26⟩","mis":"M6-2-u4-X03"},{"t":"⟨10/16⟩","mis":"M6-2-u4-X03"}],"explanation":["16：10의 비율은 16 ÷ 10 = ⟨16/10⟩이에요.","기약분수로 나타내면 ⟨8/5⟩이에요.","확대하기 전 8：5의 비율도 ⟨8/5⟩ — 두 비의 비율이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#5','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','다음 가운데 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07','M6-2-u4-X09']::text[],true,'{"seq":5,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 가운데 비례식인 것은 어느 것인가요?","options":[{"t":"4：3 = ⟨1/9⟩：⟨1/12⟩","correct":true},{"t":"4：3 = 6：8","mis":"M6-2-u4-X03"},{"t":"4：3 = ⟨1/8⟩：⟨1/20⟩","mis":"M6-2-u4-X07"},{"t":"2：5 = 4：15","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","4：3의 비율은 ⟨4/3⟩, ⟨1/9⟩：⟨1/12⟩의 비율도 ⟨1/12⟩로 나눈 ⟨4/3⟩예요.","6：8은 ⟨3/4⟩, ⟨1/8⟩：⟨1/20⟩은 ⟨5/2⟩, 4：15는 ⟨4/15⟩라 비례식이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 1.4：3.5","correct":true},{"t":"2：5 = 6：8","mis":"M6-2-u4-X09"},{"t":"2：5 = ⟨1/8⟩：⟨1/20⟩","mis":"M6-2-u4-X03"},{"t":"2：5 = 6：9","mis":"M6-2-u4-X01"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5의 비율은 ⟨2/5⟩, 1.4：3.5의 비율도 ⟨2/5⟩예요.","6：8은 ⟨3/4⟩, ⟨1/8⟩：⟨1/20⟩은 ⟨5/2⟩, 6：9는 ⟨2/3⟩이라 비례식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#6','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'ox','auto','2：5와 4：15를 이용하여 비례식 2：5 = 4：15로 나타낼 수 있어요.',ARRAY['M6-2-u4-X09']::text[],true,'{"seq":6,"concept":"M6-2-u4-C5","difficulty":2,"kind":"ox","stem":"2：5와 4：15를 이용하여 비례식 2：5 = 4：15로 나타낼 수 있어요.","answer":"X","reason_options":[{"t":"2：5의 비율은 ⟨2/5⟩, 4：15의 비율은 ⟨4/15⟩로 달라서","correct":true},{"t":"두 비 모두 전항이 후항보다 작아서","mis":"M6-2-u4-X09"}],"mis":"M6-2-u4-X09","explanation":["비례식은 비율이 같은 두 비로만 만들어요.","2：5의 비율 ⟨2/5⟩ = ⟨6/15⟩, 4：15의 비율 ⟨4/15⟩예요.","비율이 달라 비례식으로 나타낼 수 없어요."],"variant_rule":{"alt":[{"stem":"⟨1/8⟩：⟨1/20⟩과 1.4：3.5로 비례식 ⟨1/8⟩：⟨1/20⟩ = 1.4：3.5를 나타낼 수 있어요.","answer":"X","reason_options":[{"t":"⟨1/8⟩：⟨1/20⟩의 비율은 ⟨5/2⟩, 1.4：3.5의 비율은 ⟨2/5⟩로 달라서","correct":true},{"t":"두 비가 모두 2와 5로 이루어진 비라서","mis":"M6-2-u4-X09"}],"explanation":["⟨1/8⟩：⟨1/20⟩에 40을 곱하면 5：2예요.","1.4：3.5에 10을 곱하면 14：35, 7로 나누면 2：5예요.","5：2와 2：5는 비율이 달라 비례식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#7','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','비례식 6：3 = 24：12에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":7,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 6：3 = 24：12에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"외항은 6과 12, 내항은 3과 24예요","correct":true},{"t":"외항은 3과 24, 내항은 6과 12예요","mis":"M6-2-u4-X10"},{"t":"외항은 6과 3, 내항은 24와 12예요","mis":"M6-2-u4-X11"},{"t":"외항은 6과 24, 내항은 3과 12예요","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽에 있는 6과 12가 외항이에요.","안쪽에 있는 3과 24가 내항이에요.","6：3과 24：12는 비율이 2로 같아 비례식이에요."],"variant_rule":{"alt":[{"stem":"비례식 9：11 = 18：22에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"외항은 9와 22, 내항은 11과 18이에요","correct":true},{"t":"외항은 11과 18, 내항은 9와 22예요","mis":"M6-2-u4-X10"},{"t":"외항은 9와 11, 내항은 18과 22예요","mis":"M6-2-u4-X11"},{"t":"외항은 9와 18, 내항은 11과 22예요","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽에 있는 9와 22가 외항이에요.","안쪽에 있는 11과 18이 내항이에요.","9：11과 18：22는 비율이 ⟨9/11⟩로 같아 비례식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#8','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'sa','auto','조건에 맞는 비례식 ㉠：㉡ = 9：㉢을 완성하려고 해요. 외항은 6과 12이고, 두 비의 비율은 ⟨3/4⟩으로 같아요. ㉡에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u4-C5","difficulty":2,"kind":"sa","stem":"조건에 맞는 비례식 ㉠：㉡ = 9：㉢을 완성하려고 해요. 외항은 6과 12이고, 두 비의 비율은 ⟨3/4⟩으로 같아요. ㉡에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["외항이 6과 12이니 ㉠은 6, ㉢은 12예요.","6：㉡의 비율이 ⟨3/4⟩이어야 해요.","6 ÷ ㉡ = ⟨3/4⟩이므로 ㉡은 8 — 6：8 = 9：12예요."],"variant_rule":{"alt":[{"stem":"조건에 맞는 비례식 ㉠：㉡ = 9：㉢을 완성하려고 해요. 외항은 6과 12이고, 두 비의 비율은 ⟨3/4⟩으로 같아요. 9：㉢의 비율이 ⟨3/4⟩일 때 ㉢에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["9：㉢의 비율은 9 ÷ ㉢이에요.","9 ÷ ㉢ = ⟨3/4⟩이 되려면 ㉢은 12예요.","외항이 6과 12라는 조건과도 맞아요 — 6：8 = 9：12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#9','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','7：9의 전항과 후항에 같은 수를 곱해 비율이 같은 비를 만들었어요. 바르게 나타낸 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X02','M6-2-u4-X03']::text[],true,'{"seq":9,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"7：9의 전항과 후항에 같은 수를 곱해 비율이 같은 비를 만들었어요. 바르게 나타낸 비례식은 어느 것인가요?","options":[{"t":"7：9 = 14：18","correct":true},{"t":"7：9 = 9：11","mis":"M6-2-u4-X01"},{"t":"7：9 = 14：9","mis":"M6-2-u4-X02"},{"t":"7：9 = 18：14","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항에 같은 수를 곱해도 비율이 같아요.","7：9의 두 항을 2 곱하면 14：18이에요.","비율이 같은 두 비를 등호로 이으면 7：9 = 14：18이에요."],"variant_rule":{"alt":[{"stem":"48：32의 전항과 후항을 같은 수를 나누어 비율이 같은 비를 만들었어요. 바르게 나타낸 비례식은 어느 것인가요?","options":[{"t":"48：32 = 3：2","correct":true},{"t":"48：32 = 50：34","mis":"M6-2-u4-X01"},{"t":"48：32 = 3：32","mis":"M6-2-u4-X02"},{"t":"48：32 = 2：3","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항에 같은 수를 나누어도 비율이 같아요.","48：32의 두 항을 16 으로 나누면 3：2예요.","비율이 같은 두 비를 등호로 이으면 48：32 = 3：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_basic#10','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',3,'mc','auto','5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 찾아 비례식으로 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X09','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 찾아 비례식으로 나타낸 것은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = ⟨1/5⟩：⟨1/6⟩","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"},{"t":"⟨1/5⟩：⟨1/6⟩ = 2.4：2.1","mis":"M6-2-u4-X20"}],"explanation":["비율은 5：6 → ⟨5/6⟩, 8：7 → ⟨8/7⟩, ⟨1/5⟩：⟨1/6⟩ → ⟨6/5⟩, 2.4：2.1 → ⟨8/7⟩이에요.","비율이 같은 두 비는 8：7과 2.4：2.1이에요.","그래서 비례식 8：7 = 2.4：2.1(또는 2.4：2.1 = 8：7)이에요."],"variant_rule":{"alt":[{"stem":"4：7, 14：21, 2.8：4.9 가운데 비율이 같은 두 비를 찾아 비례식으로 나타낸 것은 어느 것인가요?","options":[{"t":"4：7 = 2.8：4.9","correct":true},{"t":"4：7 = 14：21","mis":"M6-2-u4-X09"},{"t":"14：21 = 2.8：4.9","mis":"M6-2-u4-X20"},{"t":"4：7 = 21：14","mis":"M6-2-u4-X03"}],"explanation":["비율은 4：7 → ⟨4/7⟩, 14：21 → ⟨2/3⟩, 2.8：4.9 → ⟨4/7⟩예요.","비율이 같은 두 비는 4：7과 2.8：4.9예요.","그래서 비례식 4：7 = 2.8：4.9(또는 2.8：4.9 = 4：7)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#1','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',2,'mc','auto','비례식 8：7 = 2.4：2.1에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":1,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 8：7 = 2.4：2.1에서 외항은 어느 것인가요?","options":[{"t":"8과 2.1","correct":true},{"t":"7과 2.4","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X11"},{"t":"2.4와 2.1","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","8：7 = 2.4：2.1에서 바깥쪽은 8과 2.1, 안쪽은 7과 2.4예요.","그래서 외항은 8과 2.1이에요."],"variant_rule":{"alt":[{"stem":"비례식 8：7 = 2.4：2.1에서 내항은 어느 것인가요?","options":[{"t":"7과 2.4","correct":true},{"t":"8과 2.1","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X11"},{"t":"2.4와 2.1","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","8：7 = 2.4：2.1에서 바깥쪽은 8과 2.1, 안쪽은 7과 2.4예요.","그래서 내항은 7과 2.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#2','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',2,'ox','auto','4：3과 ⟨1/9⟩：⟨1/12⟩로 비례식을 나타낼 때 ⟨1/9⟩：⟨1/12⟩ = 4：3이라고 써도 돼요.',ARRAY['M6-2-u4-X22']::text[],true,'{"seq":2,"concept":"M6-2-u4-C5","difficulty":2,"kind":"ox","stem":"4：3과 ⟨1/9⟩：⟨1/12⟩로 비례식을 나타낼 때 ⟨1/9⟩：⟨1/12⟩ = 4：3이라고 써도 돼요.","answer":"O","reason_options":[{"t":"두 비의 비율이 ⟨4/3⟩로 같으면 어느 비를 앞에 써도 비례식이라서","correct":true},{"t":"비례식은 주어진 차례대로 4：3을 먼저 써야 해서","mis":"M6-2-u4-X22"}],"mis":"M6-2-u4-X22","explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","4：3 = ⟨1/9⟩：⟨1/12⟩도, ⟨1/9⟩：⟨1/12⟩ = 4：3도 비율이 같은 두 비를 이었어요.","그래서 두 식 모두 비례식이에요(지도서 276)."],"variant_rule":{"alt":[{"stem":"비례식 8：7 = 2.4：2.1을 2.4：2.1 = 8：7로 나타내면 외항은 2.4와 7이에요.","answer":"O","reason_options":[{"t":"2.4：2.1 = 8：7에서 바깥쪽 두 항이 2.4와 7이라서","correct":true},{"t":"비례식을 바꾸어 써도 외항은 언제나 8과 2.1이라서","mis":"M6-2-u4-X22"}],"explanation":["2.4：2.1 = 8：7도 비례식이에요.","이 식에서 바깥쪽 두 항은 2.4와 7이에요.","그래서 외항은 2.4와 7, 내항은 2.1과 8이에요(지도서 295 채점)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#3','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 확대하기 전과 확대한 후 사진의 가로와 세로의 비를 바르게 비례식으로 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X14']::text[],false,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 확대하기 전과 확대한 후 사진의 가로와 세로의 비를 바르게 비례식으로 나타낸 것은 어느 것인가요?","options":[{"t":"8：5 = 16：10","correct":true},{"t":"8：5 = 10：16","mis":"M6-2-u4-X03"},{"t":"8：5 = 16：13","mis":"M6-2-u4-X14"},{"t":"5：8 = 16：10","mis":"M6-2-u4-X03"}],"explanation":["확대하기 전 가로：세로 = 8：5, 확대한 후 가로：세로 = 16：10이에요.","8：5와 16：10은 비율이 ⟨8/5⟩로 같아요.","그래서 8：5 = 16：10 — 16：13은 8을 더한 덧셈 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#4','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'error','auto','비례식에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C5","difficulty":3,"kind":"error","stem":"비례식에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「2：5와 4：15를 이용하여 비례식 2：5 = 4：15로 나타낼 수 있어요.」","correct":true,"mis_target":"M6-2-u4-X09"},{"t":"유진 — 「비례식 6：3 = 24：12에서 내항은 3과 24이고, 외항은 6과 12예요.」","mis":"M6-2-u4-X19"},{"t":"희우 — 「8：5 = 16：10에서 바깥쪽 8과 10이 외항이에요.」","mis":"M6-2-u4-X19"},{"t":"준기 — 「56：21 = 8：3의 내항은 21과 8이에요.」","mis":"M6-2-u4-X19"}],"explanation":["2：5의 비율은 ⟨2/5⟩(= ⟨6/15⟩), 4：15의 비율은 ⟨4/15⟩예요.","비율이 달라 2：5 = 4：15는 비례식이 아니에요.","나머지 셋은 외항·내항을 바르게 찾았어요 — 지호가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다운 — 「7：9 = 14：18의 외항은 9와 14예요.」","correct":true,"mis_target":"M6-2-u4-X10"},{"t":"민지 — 「48：32 = 3：2의 외항은 48과 2예요.」","mis":"M6-2-u4-X19"},{"t":"정후 — 「4：3 = ⟨1/9⟩：⟨1/12⟩은 비례식이에요.」","mis":"M6-2-u4-X22"},{"t":"연아 — 「2：5 = 1.4：3.5의 내항은 5와 1.4예요.」","mis":"M6-2-u4-X19"}],"explanation":["7：9 = 14：18에서 바깥쪽은 7과 18이에요.","9와 14는 안쪽에 있는 내항이에요.","다운이는 외항과 내항을 바꾸어 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#5','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','6：8, ⟨1/8⟩：⟨1/20⟩, ⟨1/9⟩：⟨1/12⟩, 1.4：3.5 가운데 4：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07','M6-2-u4-X09']::text[],true,'{"seq":5,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"6：8, ⟨1/8⟩：⟨1/20⟩, ⟨1/9⟩：⟨1/12⟩, 1.4：3.5 가운데 4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"⟨1/9⟩：⟨1/12⟩","correct":true},{"t":"6：8","mis":"M6-2-u4-X03"},{"t":"⟨1/8⟩：⟨1/20⟩","mis":"M6-2-u4-X07"},{"t":"1.4：3.5","mis":"M6-2-u4-X09"}],"explanation":["4：3의 비율은 ⟨4/3⟩예요.","⟨1/9⟩：⟨1/12⟩에 36을 곱하면 4：3이에요.","6：8은 3：4로 거꾸로, ⟨1/8⟩：⟨1/20⟩은 5：2, 1.4：3.5는 2：5예요."],"variant_rule":{"alt":[{"stem":"6：8, ⟨1/8⟩：⟨1/20⟩, ⟨1/9⟩：⟨1/12⟩, 1.4：3.5 가운데 2：5와 비율이 같은 비는 어느 것인가요?","options":[{"t":"1.4：3.5","correct":true},{"t":"⟨1/8⟩：⟨1/20⟩","mis":"M6-2-u4-X03"},{"t":"6：8","mis":"M6-2-u4-X09"},{"t":"⟨1/9⟩：⟨1/12⟩","mis":"M6-2-u4-X07"}],"explanation":["2：5의 비율은 ⟨2/5⟩예요.","1.4：3.5에 10을 곱하면 14：35, 7로 나누면 2：5예요.","⟨1/8⟩：⟨1/20⟩은 5：2로 거꾸로예요 — 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#6','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','한 친구가 2：5 = 6：9라고 썼어요. 이 친구가 잘못 생각한 것은 무엇인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X20','M6-2-u4-X03']::text[],false,'{"seq":6,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"한 친구가 2：5 = 6：9라고 썼어요. 이 친구가 잘못 생각한 것은 무엇인가요?","options":[{"t":"두 항에 같은 수(4)를 더해도 비율이 같다고 생각했다","correct":true},{"t":"외항과 내항을 바꾸어 생각했다","mis":"M6-2-u4-X10"},{"t":"6：9를 3으로 나누면 2：5가 된다고 생각했다","mis":"M6-2-u4-X20"},{"t":"2：5의 비율을 ⟨5/2⟩로 생각했다","mis":"M6-2-u4-X03"}],"explanation":["2：5의 두 항에 4를 더하면 6：9예요.","6：9의 비율은 ⟨2/3⟩로 ⟨2/5⟩와 달라요.","비율은 덧셈이 아니라 곱셈으로 견준 크기예요(지도서 277 오류 지도)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#7','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','56：21 = 8：3이 비례식인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X10','M6-2-u4-X01']::text[],false,'{"seq":7,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"56：21 = 8：3이 비례식인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"56：21과 8：3의 비율이 ⟨8/3⟩로 같아서","correct":true},{"t":"두 비에 모두 두 자리 수가 있어서","mis":"M6-2-u4-X09"},{"t":"56과 3이 바깥쪽에 있어서","mis":"M6-2-u4-X10"},{"t":"56에서 48을 빼면 8이 되어서","mis":"M6-2-u4-X01"}],"explanation":["56：21의 두 항을 7로 나누면 8：3이에요.","두 비의 비율은 모두 ⟨8/3⟩이에요.","비율이 같은 두 비를 등호로 이었으니 비례식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#8','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'mc','auto','두 비의 비율이 ⟨3/4⟩이고 외항이 6과 12인 비례식 ㉠：㉡ = 9：㉢을 완성했어요. 완성한 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X03']::text[],false,'{"seq":8,"concept":"M6-2-u4-C5","difficulty":4,"kind":"mc","stem":"두 비의 비율이 ⟨3/4⟩이고 외항이 6과 12인 비례식 ㉠：㉡ = 9：㉢을 완성했어요. 완성한 비례식은 어느 것인가요?","options":[{"t":"6：8 = 9：12","correct":true},{"t":"6：12 = 9：8","mis":"M6-2-u4-X10"},{"t":"6：8 = 12：9","mis":"M6-2-u4-X10"},{"t":"8：6 = 9：12","mis":"M6-2-u4-X03"}],"explanation":["9：㉢의 비율이 ⟨3/4⟩이므로 ㉢은 12, 외항이 6과 12이니 ㉠은 6이에요.","6：㉡의 비율이 ⟨3/4⟩이므로 ㉡은 8이에요.","그래서 6：8 = 9：12예요(『수학익힘』 61쪽)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#9','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'essay','teacher','철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 나타내고, 외항과 내항을 찾아 써 보세요. 또 이 식이 비례식인 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C5","difficulty":4,"kind":"essay","stem":"철새 사진을 확대해 학급 신문에 실으려고 해요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 나타내고, 외항과 내항을 찾아 써 보세요. 또 이 식이 비례식인 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 비례식은 8：5 = 16：10이다. 외항은 8과 10, 내항은 5와 16이다. 8：5의 비율은 ⟨8/5⟩, 16：10의 비율도 ⟨16/10⟩ = ⟨8/5⟩로 같으므로 비례식이다.","scoring_points":["8：5 = 16：10을 썼는가","외항 8·10, 내항 5·16을 찾았는가","두 비의 비율이 같음을 까닭으로 들었는가"]},"explanation":["확대하기 전 8：5, 확대한 후 16：10이에요.","외항 8·10, 내항 5·16이에요.","비율이 ⟨8/5⟩로 같아 비례식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L04_challenge#10','math',6,2,'u4','L04','tb_g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'essay','teacher','7：9의 전항과 후항에 같은 수를 곱하고, 48：32의 전항과 후항을 같은 수로 나누어 비례식을 하나씩 만들어 보세요. 친구가 다른 비례식을 만들었다면 그 까닭도 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C5","difficulty":4,"kind":"essay","stem":"7：9의 전항과 후항에 같은 수를 곱하고, 48：32의 전항과 후항을 같은 수로 나누어 비례식을 하나씩 만들어 보세요. 친구가 다른 비례식을 만들었다면 그 까닭도 설명해 보세요.","answer_guide":{"answer":"예: 7：9 = 14：18(2를 곱함), 48：32 = 3：2(16으로 나눔). 친구는 7：9 = 21：27(3을 곱함)처럼 다른 수를 곱했을 수 있다. 0이 아닌 같은 수를 곱하거나 나누면 비율이 같은 비가 셀 수 없이 많아 비례식도 여러 가지이다.","scoring_points":["비율이 같은 비로 비례식 두 개를 바르게 만들었는가","곱하거나 나눈 수를 밝혔는가","비례식이 여러 가지일 수 있는 까닭을 썼는가"]},"explanation":["7：9의 두 항에 2를 곱하면 14：18이에요.","48：32의 두 항을 16으로 나누면 3：2예요.","같은 수를 다르게 고르면 다른 비례식이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#1','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','민지와 다운이가 태양 고도 측정기로 막대 길이와 그림자 길이를 쟀어요. 민지는 막대 5 cm에 그림자 7 cm, 다운이는 막대 10 cm에 그림자 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"민지와 다운이가 태양 고도 측정기로 막대 길이와 그림자 길이를 쟀어요. 민지는 막대 5 cm에 그림자 7 cm, 다운이는 막대 10 cm에 그림자 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 바깥쪽에 있는 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱 7 × 10 = 70과 같아요."],"variant_rule":{"alt":[{"stem":"민지와 다운이가 태양 고도 측정기로 막대 길이와 그림자 길이를 쟀어요. 민지는 막대 5 cm에 그림자 7 cm, 다운이는 막대 10 cm에 그림자 14 cm예요. 비례식 5：7 = 10：14에서 내항의 곱은 얼마인가요?","answer":["70"],"explanation":["내항은 안쪽에 있는 7과 10이에요.","내항의 곱은 7 × 10 = 70이에요.","외항의 곱 5 × 14 = 70과 같아요."]},{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9, 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36이에요 — 비례식에서 두 곱은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#2','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'mc','auto','비례식 500：40 = 150：12에서 외항의 곱은 얼마인가요?',ARRAY['M6-2-u4-X11','M6-2-u4-X10']::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":1,"kind":"mc","stem":"비례식 500：40 = 150：12에서 외항의 곱은 얼마인가요?","options":[{"t":"6000","correct":true},{"t":"75000","mis":"M6-2-u4-X11"},{"t":"480","mis":"M6-2-u4-X11"},{"t":"20000","mis":"M6-2-u4-X10"}],"explanation":["외항은 500, 12예요.","외항의 곱은 500 × 12 = 6000이에요.","내항의 곱도 6000이에요 — 비례식에서 두 곱은 같아요."],"variant_rule":{"alt":[{"stem":"비례식 500：40 = 150：12에서 내항의 곱은 얼마인가요?","options":[{"t":"6000","correct":true},{"t":"75000","mis":"M6-2-u4-X11"},{"t":"480","mis":"M6-2-u4-X11"},{"t":"20000","mis":"M6-2-u4-X10"}],"explanation":["내항은 40, 150이에요.","내항의 곱은 40 × 150 = 6000이에요.","외항의 곱도 6000이에요 — 비례식에서 두 곱은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#3','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 8 × □ = 72예요.","□ = 72 ÷ 8 = 9예요."],"variant_rule":{"alt":[{"stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."]},{"stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#4','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'mc','auto','비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":1,"kind":"mc","stem":"비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?","options":[{"t":"5：2 = 10：4","correct":true},{"t":"7：14 = 6：13","mis":"M6-2-u4-X09"},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"7：22 = 3：11","mis":"M6-2-u4-X09"}],"explanation":["5：2 = 10：4에서 외항의 곱 5 × 4 = 20, 내항의 곱 2 × 10 = 20으로 같아요.","7：14 = 6：13은 91과 84, 13：8 = 5：3은 39와 40, 7：22 = 3：11은 77과 66으로 달라요.","두 곱이 같은 식만 비례식이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"7：14 = 6：13","mis":"M6-2-u4-X09"},{"t":"7：22 = 3：11","mis":"M6-2-u4-X09"}],"explanation":["9：12 = 3：4에서 외항의 곱 9 × 4 = 36, 내항의 곱 12 × 3 = 36으로 같아요.","13：8 = 5：3은 39와 40, 7：14 = 6：13은 91과 84, 7：22 = 3：11은 77과 66으로 달라요.","두 곱이 같은 식만 비례식이에요."]},{"stem":"이번에는 다른 보기예요. 비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 12：9","correct":true},{"t":"7：22 = 3：11","mis":"M6-2-u4-X09"},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"7：14 = 6：13","mis":"M6-2-u4-X09"}],"explanation":["8：6 = 12：9에서 외항의 곱 8 × 9 = 72, 내항의 곱 6 × 12 = 72로 같아요.","7：22 = 3：11은 77과 66, 13：8 = 5：3은 39와 40, 7：14 = 6：13은 91과 84로 달라요.","두 곱이 같은 식만 비례식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#5','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'sa','auto','36：9 = □：2에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"36：9 = □：2에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 36 × 2 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."],"variant_rule":{"alt":[{"stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."]},{"stem":"3：□ = 12：56에서 □에 알맞은 수는 얼마인가요?","answer":["14"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 56 = 168이므로 12 × □ = 168이에요.","□ = 168 ÷ 12 = 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#6','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'sa','auto','14：8 = 21：□는 비례식이에요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"14：8 = 21：□는 비례식이에요. □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 21 = 168이므로 14 × □ = 168이에요.","□ = 168 ÷ 14 = 12예요."],"variant_rule":{"alt":[{"stem":"8：6 = 12：□는 비례식이에요. □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 8 × □ = 72예요.","□ = 72 ÷ 8 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#7','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','14：8 = 21：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X11']::text[],false,'{"seq":7,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"14：8 = 21：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"외항의 곱 14 × □와 내항의 곱 8 × 21은 같아요","correct":true},{"t":"14：8과 21：□의 비율은 서로 달라요","mis":"M6-2-u4-X09"},{"t":"□에 알맞은 수는 6이에요","mis":"M6-2-u4-X11"},{"t":"외항의 곱 14 × 8과 내항의 곱 21 × □는 같아요","mis":"M6-2-u4-X11"}],"explanation":["비례식이니 14：8과 21：□의 비율은 같아요.","외항의 곱 14 × □와 내항의 곱 8 × 21 = 168은 같아요.","14 × □ = 168, □ = 12예요 — 6이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#8','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'ox','auto','9：12 = 3：4는 비례식이에요.',ARRAY['M6-2-u4-X09']::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":2,"kind":"ox","stem":"9：12 = 3：4는 비례식이에요.","answer":"O","reason_options":[{"t":"외항의 곱 9 × 4 = 36과 내항의 곱 12 × 3 = 36이 같아서","correct":true},{"t":"두 비에 똑같이 4가 들어 있어서","mis":"M6-2-u4-X09"}],"mis":"M6-2-u4-X09","explanation":["외항은 9와 4, 내항은 12와 3이에요.","외항의 곱 36, 내항의 곱 36으로 같아요.","그래서 비례식이에요."],"variant_rule":{"alt":[{"stem":"13：8 = 5：3은 비례식이에요.","answer":"X","reason_options":[{"t":"외항의 곱 13 × 3 = 39와 내항의 곱 8 × 5 = 40이 달라서","correct":true},{"t":"두 비 모두 전항이 후항보다 커서","mis":"M6-2-u4-X09"}],"explanation":["외항은 13과 3, 내항은 8과 5예요.","외항의 곱 39, 내항의 곱 40으로 달라요.","그래서 비례식이 아니에요."]},{"stem":"7：14 = 6：13은 비례식이에요.","answer":"X","reason_options":[{"t":"외항의 곱 7 × 13 = 91과 내항의 곱 14 × 6 = 84가 달라서","correct":true},{"t":"7과 14, 6과 13처럼 앞뒤 수가 비슷하게 커져서","mis":"M6-2-u4-X14"}],"explanation":["외항은 7과 13, 내항은 14와 6이에요.","외항의 곱 91, 내항의 곱 84로 달라요.","그래서 비례식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#9','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','비례식의 성질을 이용하여 8：6 = 12：□의 □를 구하려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M6-2-u4-X11','M6-2-u4-X14']::text[],true,'{"seq":9,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"비례식의 성질을 이용하여 8：6 = 12：□의 □를 구하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"8 × □ = 6 × 12","correct":true},{"t":"8 × 12 = 6 × □","mis":"M6-2-u4-X11"},{"t":"8 × 6 = 12 × □","mis":"M6-2-u4-X11"},{"t":"8 + □ = 6 + 12","mis":"M6-2-u4-X14"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 8, □이고 내항은 6, 12예요.","그래서 8 × □ = 6 × 12예요."],"variant_rule":{"alt":[{"stem":"비례식의 성질을 이용하여 10：8 = 15：□의 □를 구하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"10 × □ = 8 × 15","correct":true},{"t":"10 × 15 = 8 × □","mis":"M6-2-u4-X11"},{"t":"10 × 8 = 15 × □","mis":"M6-2-u4-X11"},{"t":"10 + □ = 8 + 15","mis":"M6-2-u4-X14"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 10, □이고 내항은 8, 15예요.","그래서 10 × □ = 8 × 15예요."]},{"stem":"비례식의 성질을 이용하여 3：11 = □：22의 □를 구하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"3 × 22 = 11 × □","correct":true},{"t":"3 × □ = 11 × 22","mis":"M6-2-u4-X11"},{"t":"3 × 11 = □ × 22","mis":"M6-2-u4-X11"},{"t":"3 + 22 = 11 + □","mis":"M6-2-u4-X14"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 3, 22이고 내항은 11, □예요.","그래서 3 × 22 = 11 × □예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_basic#10','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',3,'mc','auto','21：28 = 3：7이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X11','M6-2-u4-X10']::text[],false,'{"seq":10,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"21：28 = 3：7이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?","options":[{"t":"외항의 곱 21 × 7 = 147과 내항의 곱 28 × 3 = 84가 달라서","correct":true},{"t":"21：28과 3：7의 수가 서로 달라서","mis":"M6-2-u4-X09"},{"t":"전항끼리의 곱 63과 후항끼리의 곱 196이 달라서","mis":"M6-2-u4-X11"},{"t":"21과 7이 바깥쪽에 있어서","mis":"M6-2-u4-X10"}],"explanation":["비례식의 성질은 외항의 곱과 내항의 곱이 같다는 것이에요.","21 × 7 = 147, 28 × 3 = 84로 두 곱이 달라요.","그래서 비례식이 아니에요 — 이 문제는 비례식의 성질로 까닭을 써야 해요(지도서 281)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#1','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'mc','auto','4：□ = 1：25에서 □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X11','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"4：□ = 1：25에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"100","correct":true},{"t":"0.16","mis":"M6-2-u4-X11"},{"t":"200","mis":"M6-2-u4-X20"},{"t":"50","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 25 = 100이므로 1 × □ = 100이에요.","□ = 100 ÷ 1 = 100이에요."],"variant_rule":{"alt":[{"stem":"6：40 = 21：□에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"140","correct":true},{"t":"840","mis":"M6-2-u4-X12"},{"t":"3.15","mis":"M6-2-u4-X11"},{"t":"280","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#2','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','500：40 = 150：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"500：40 = 150：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 40 × 150 = 6000이므로 500 × □ = 6000이에요.","□ = 6000 ÷ 500 = 12예요."],"variant_rule":{"alt":[{"stem":"9：11 = 18：□에서 □에 알맞은 수는 얼마인가요?","answer":["22"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 11 × 18 = 198이므로 9 × □ = 198이에요.","□ = 198 ÷ 9 = 22예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#3','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'match','auto','비례식이 되도록 □ 안에 알맞은 수를 찾아 이으세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C6","difficulty":3,"kind":"match","stem":"비례식이 되도록 □ 안에 알맞은 수를 찾아 이으세요.","pairs":[{"l":"10：8 = 15：□","r":"12"},{"l":"4：□ = 1：25","r":"100"},{"l":"3：11 = □：22","r":"6"}],"mis":"M6-2-u4-X11","explanation":["10 × □ = 8 × 15 = 120, □ = 12예요.","4 × 25 = □ × 1, □ = 100이에요.","3 × 22 = 11 × □, 66 = 11 × □, □ = 6이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식이 되도록 □ 안에 알맞은 수를 찾아 이으세요.","pairs":[{"l":"4：5 = 20：□","r":"25"},{"l":"36：9 = □：2","r":"8"},{"l":"3：□ = 12：56","r":"14"}],"explanation":["4 × □ = 5 × 20 = 100, □ = 25예요.","36 × 2 = 9 × □, 72 = 9 × □, □ = 8이에요.","3 × 56 = □ × 12, 168 = □ × 12, □ = 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#4','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','8：6 = 12：□를 비의 성질로 풀려고 해요. 8：6의 전항과 후항에 똑같이 곱해야 하는 수는 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"8：6 = 12：□를 비의 성질로 풀려고 해요. 8：6의 전항과 후항에 똑같이 곱해야 하는 수는 어느 것인가요?","options":[{"t":"⟨3/2⟩","correct":true},{"t":"4","mis":"M6-2-u4-X14"},{"t":"⟨2/3⟩","mis":"M6-2-u4-X03"},{"t":"2","mis":"M6-2-u4-X20"}],"explanation":["전항 8이 12가 되려면 8 × ⟨3/2⟩ = 12예요.","후항에도 똑같이 6 × ⟨3/2⟩ = 9를 해요.","비의 성질로 구해도 □ = 9 — 비례식의 성질로 구한 값과 같아요(지도서 280)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#5','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'error','auto','8：6 = 12：□의 □를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u4-X11','M6-2-u4-X19']::text[],true,'{"seq":5,"concept":"M6-2-u4-C6","difficulty":3,"kind":"error","stem":"8：6 = 12：□의 □를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"정수 — 「전항끼리 곱 8 × 12와 후항끼리 곱 6 × □가 같으니 □ = 16이에요.」","correct":true,"mis_target":"M6-2-u4-X11"},{"t":"해윤 — 「외항의 곱 8 × □와 내항의 곱 6 × 12가 같으니 □ = 9예요.」","mis":"M6-2-u4-X19"},{"t":"다현 — 「8：6의 두 항에 ⟨3/2⟩을 곱하면 12：9라 □ = 9예요.」","mis":"M6-2-u4-X19"},{"t":"윤수 — 「8 × □ = 72에서 □ = 72 ÷ 8 = 9예요.」","mis":"M6-2-u4-X19"}],"explanation":["비례식의 성질은 외항끼리, 내항끼리 곱한 값이 같다는 것이에요.","8 × □ = 6 × 12 = 72, □ = 9예요.","전항끼리·후항끼리 곱한 정수가 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"10：8 = 15：□의 □를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"태리 — 「곱한 값 120이 답이에요.」","correct":true,"mis_target":"M6-2-u4-X12"},{"t":"동하 — 「외항의 곱 10 × □와 내항의 곱 8 × 15가 같아요.」","mis":"M6-2-u4-X19"},{"t":"리엘 — 「10 × □ = 120이니 □ = 12예요.」","mis":"M6-2-u4-X19"},{"t":"순달 — 「10：8의 두 항에 ⟨3/2⟩을 곱하면 15：12예요.」","mis":"M6-2-u4-X19"}],"explanation":["10 × □ = 8 × 15 = 120이에요.","□ = 120 ÷ 10 = 12예요.","곱한 값 120을 그대로 답으로 쓴 태리가 잘못 구했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#6','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'ox','auto','7：22 = 3：11은 비례식이에요.',ARRAY['M6-2-u4-X09']::text[],true,'{"seq":6,"concept":"M6-2-u4-C6","difficulty":3,"kind":"ox","stem":"7：22 = 3：11은 비례식이에요.","answer":"X","reason_options":[{"t":"외항의 곱 7 × 11 = 77과 내항의 곱 22 × 3 = 66이 달라서","correct":true},{"t":"22는 11의 2배이니 비례식이라서","mis":"M6-2-u4-X09"}],"mis":"M6-2-u4-X09","explanation":["외항은 7과 11, 내항은 22와 3이에요.","외항의 곱 77, 내항의 곱 66으로 달라요.","그래서 비례식이 아니에요."],"variant_rule":{"alt":[{"stem":"500：40 = 150：12는 비례식이에요.","answer":"O","reason_options":[{"t":"외항의 곱 500 × 12와 내항의 곱 40 × 150이 6000으로 같아서","correct":true},{"t":"500과 150, 40과 12가 모두 10의 배수라서","mis":"M6-2-u4-X09"}],"explanation":["외항의 곱은 500 × 12 = 6000이에요.","내항의 곱은 40 × 150 = 6000이에요.","두 곱이 같아 비례식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#7','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'sa','auto','비례식 4：5 = 20：㉠, 36：9 = ㉡：2에서 ㉠과 ㉡에 알맞은 수의 차는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C6","difficulty":3,"kind":"sa","stem":"비례식 4：5 = 20：㉠, 36：9 = ㉡：2에서 ㉠과 ㉡에 알맞은 수의 차는 얼마인가요?","answer":["17"],"explanation":["4 × ㉠ = 5 × 20 = 100, ㉠ = 25예요.","36 × 2 = 9 × ㉡, ㉡ = 8이에요.","25 − 8 = 17이에요."],"variant_rule":{"alt":[{"stem":"비례식 3：11 = ㉠：22, 10：8 = 15：㉡에서 ㉠과 ㉡에 알맞은 수의 합은 얼마인가요?","answer":["18"],"explanation":["3 × 22 = 11 × ㉠, ㉠ = 6이에요.","10 × ㉡ = 8 × 15 = 120, ㉡ = 12예요.","6 + 12 = 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#8','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'mc','auto','「영차영차 길 만들기」에서 □ 안의 수가 같은 섬끼리 길로 이어요. 3：15 = □：30과 이어지는 섬은 어느 것인가요?',ARRAY['M6-2-u4-X20']::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":4,"kind":"mc","stem":"「영차영차 길 만들기」에서 □ 안의 수가 같은 섬끼리 길로 이어요. 3：15 = □：30과 이어지는 섬은 어느 것인가요?","options":[{"t":"□：⟨1/6⟩ = 18：⟨1/2⟩","correct":true},{"t":"⟨2/3⟩：2 = 5：□","mis":"M6-2-u4-X20"},{"t":"0.6：1.8 = □：9","mis":"M6-2-u4-X20"},{"t":"2：3 = □：6","mis":"M6-2-u4-X20"}],"explanation":["비례식의 성질(외항의 곱 = 내항의 곱)로 □를 구해요.","3：15 = □：30의 □는 6이에요.","□가 6인 섬은 □：⟨1/6⟩ = 18：⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"「영차영차 길 만들기」에서 □ 안의 수가 같은 섬끼리 길로 이어요. 27：□ = 1：⟨1/3⟩과 이어지는 섬은 어느 것인가요?","options":[{"t":"□：5 = ⟨2/5⟩：⟨2/9⟩","correct":true},{"t":"30：36 = □：18","mis":"M6-2-u4-X20"},{"t":"2.4：18 = 0.4：□","mis":"M6-2-u4-X20"},{"t":"8：□ = 2：1","mis":"M6-2-u4-X20"}],"explanation":["비례식의 성질(외항의 곱 = 내항의 곱)로 □를 구해요.","27：□ = 1：⟨1/3⟩의 □는 9예요.","□가 9인 섬은 □：5 = ⟨2/5⟩：⟨2/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#9','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'sa','auto','「영차영차 길 만들기」 섬의 비례식 ⟨2/3⟩：2 = 5：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u4-C6","difficulty":4,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 ⟨2/3⟩：2 = 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["외항의 곱 ⟨2/3⟩ × □와 내항의 곱 2 × 5 = 10은 같아요.","⟨2/3⟩ × □ = 10이에요.","□ = 10 ÷ ⟨2/3⟩ = 15예요."],"variant_rule":{"alt":[{"stem":"「영차영차 길 만들기」 섬의 비례식 27：□ = 1：⟨1/3⟩에서 □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["외항의 곱 27 × ⟨1/3⟩ = 9예요.","내항의 곱 □ × 1과 같아요.","그래서 □ = 9예요."]},{"stem":"「영차영차 길 만들기」 섬의 비례식 2.4：18 = 0.4：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["외항의 곱 2.4 × □와 내항의 곱 18 × 0.4 = 7.2는 같아요.","2.4 × □ = 7.2예요.","□ = 7.2 ÷ 2.4 = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L05_challenge#10','math',6,2,'u4','L05','tb_g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'essay','teacher','21：28 = 3：7이 비례식이 아닌 이유를 비례식의 성질을 이용하여 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C6","difficulty":4,"kind":"essay","stem":"21：28 = 3：7이 비례식이 아닌 이유를 비례식의 성질을 이용하여 써 보세요.","answer_guide":{"answer":"예: 21：28 = 3：7에서 외항의 곱은 21 × 7 = 147이고 내항의 곱은 28 × 3 = 84이다. 외항의 곱과 내항의 곱이 다르므로 비례식이 아니다.","scoring_points":["외항의 곱 147을 구했는가","내항의 곱 84를 구했는가","두 곱이 달라 비례식이 아니라고 썼는가(비율이 다르다고만 쓰면 오답 — 지도서 281)"]},"explanation":["외항의 곱 21 × 7 = 147이에요.","내항의 곱 28 × 3 = 84예요.","두 곱이 달라 비례식이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#1','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 ★ kg이라 할 때 알맞은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14']::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 ★ kg이라 할 때 알맞은 비례식은 어느 것인가요?","options":[{"t":"2：8000 = ★：40000","correct":true},{"t":"2：8000 = 40000：★","mis":"M6-2-u4-X13"},{"t":"8000：2 = ★：40000","mis":"M6-2-u4-X13"},{"t":"2：8000 = ★：32000","mis":"M6-2-u4-X14"}],"explanation":["쌀의 무게와 쌀값의 비는 2：8000이에요.","40000원으로 살 쌀 ★ kg과 값의 비는 ★：40000이에요.","두 비의 비율이 같으니 2：8000 = ★：40000이에요."],"variant_rule":{"alt":[{"stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 21 kWh의 전기 에너지로 이동할 수 있는 거리를 □ km라 할 때 알맞은 비례식은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：40 = 21：55","mis":"M6-2-u4-X14"}],"explanation":["전기 에너지와 거리의 비는 6：40이에요.","21 kWh와 □ km의 비는 21：□예요.","두 비의 비율이 같으니 6：40 = 21：□예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#2','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 비례식 2：8000 = ★：40000을 세웠어요. 40000원으로 살 수 있는 쌀은 몇 kg인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 비례식 2：8000 = ★：40000을 세웠어요. 40000원으로 살 수 있는 쌀은 몇 kg인가요?","answer":["10"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 2 × 40000 = 80000이므로 8000 × □ = 80000이에요.","□ = 80000 ÷ 8000 = 10(kg)이에요."],"variant_rule":{"alt":[{"stem":"경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 사진 속 형의 키와 첨성대의 높이의 비는 1：6이에요. 비례식 1：6 = 1.5：□를 세웠어요. 첨성대의 실제 높이는 몇 m인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 1.5 = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9(m)예요."]},{"stem":"페인트 4 L로 담장 48 m²을 칠할 수 있어요. 담장 60 m²을 칠할 때 필요한 페인트는 몇 L인가요?","answer":["5"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5(L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#3','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 사진 속 형의 키와 첨성대의 높이의 비 2.5：15를 간단한 자연수의 비로 나타내면 1：□예요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 사진 속 형의 키와 첨성대의 높이의 비 2.5：15를 간단한 자연수의 비로 나타내면 1：□예요. □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["2.5：15에 10을 곱하면 25：150이에요.","25로 나누면 1：6이에요.","그래서 □는 6이에요."],"variant_rule":{"alt":[{"stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 2：8000의 전항과 후항에 똑같이 □를 곱하면 ★：40000이 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["후항 8000이 40000이 되려면 8000 × 5 = 40000이에요.","전항에도 똑같이 5를 곱해요.","그래서 □는 5 — ★ = 2 × 5 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#4','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 이 전기차는 21 kWh의 전기 에너지로 몇 km를 이동할 수 있나요?',ARRAY['M6-2-u4-X12','M6-2-u4-X14','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 이 전기차는 21 kWh의 전기 에너지로 몇 km를 이동할 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"120 km","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140(km)예요."],"variant_rule":{"alt":[{"stem":"환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 해윤이가 우리나라 돈 38000원을 바꾸면 중국 돈 몇 위안을 받나요?","options":[{"t":"200위안","correct":true},{"t":"19000위안","mis":"M6-2-u4-X13"},{"t":"450위안","mis":"M6-2-u4-X13"},{"t":"11400000위안","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 300 × 38000 = 11400000이므로 57000 × □ = 11400000이에요.","□ = 11400000 ÷ 57000 = 200(위안)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#5','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'ox','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀 ★ kg을 구할 때 비례식 2：★ = 8000：40000을 세워도 돼요.',ARRAY['M6-2-u4-X22']::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":2,"kind":"ox","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀 ★ kg을 구할 때 비례식 2：★ = 8000：40000을 세워도 돼요.","answer":"O","reason_options":[{"t":"쌀의 무게끼리, 값끼리 비를 만들어도 두 비의 비율이 같아서","correct":true},{"t":"비례식은 2：8000 = ★：40000 하나로만 세워야 해서","mis":"M6-2-u4-X22"}],"mis":"M6-2-u4-X22","explanation":["2：★은 쌀의 무게끼리, 8000：40000은 값끼리의 비예요.","두 비의 비율이 같으니 비례식이에요.","2 × 40000 = ★ × 8000, ★ = 10 — 같은 답이에요(지도서 283)."],"variant_rule":{"alt":[{"stem":"경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이를 구할 때 비례식 1：1.5 = 6：□를 세워도 돼요.","answer":"O","reason_options":[{"t":"사진 속 키끼리와 실제 키끼리의 비율이 같아서","correct":true},{"t":"비례식은 1：6 = 1.5：□ 하나로만 세워야 해서","mis":"M6-2-u4-X22"}],"explanation":["1：1.5는 형의 사진 속 비와 실제 키(간단히 한 수)예요.","6：□는 첨성대의 사진 속 비와 실제 높이예요.","1 × □ = 1.5 × 6, □ = 9 — 같은 답이에요(지도서 284)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#6','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 친구는 비의 성질을 이용해 6：40의 전항과 후항에 똑같은 수를 곱해 21：□를 만들었어요. 곱한 수는 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 친구는 비의 성질을 이용해 6：40의 전항과 후항에 똑같은 수를 곱해 21：□를 만들었어요. 곱한 수는 어느 것인가요?","options":[{"t":"⟨7/2⟩","correct":true},{"t":"15","mis":"M6-2-u4-X14"},{"t":"⟨2/7⟩","mis":"M6-2-u4-X03"},{"t":"3","mis":"M6-2-u4-X20"}],"explanation":["전항 6을 21로 만들려면 6 × ⟨7/2⟩ = 21이에요.","후항에도 40 × ⟨7/2⟩ = 140을 해요.","그래서 □ = 140 — 비례식의 성질로 구한 값과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#7','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸렸어요. 들이가 50 L인 수조를 가득 채우는 데 걸리는 시간은 몇 초인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸렸어요. 들이가 50 L인 수조를 가득 채우는 데 걸리는 시간은 몇 초인가요?","answer":["80"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80(초)예요."],"variant_rule":{"alt":[{"stem":"떡볶이 2인분을 만드는 데 떡 180 g이 필요해요. 떡 450 g으로는 떡볶이를 몇 인분 만들 수 있나요?","answer":["5"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 2 × 450 = 900이므로 180 × □ = 900이에요.","□ = 900 ÷ 180 = 5(인분)이에요."]},{"stem":"가로와 세로의 비가 5：3인 직사각형을 그렸어요. 가로가 15 cm일 때 세로는 몇 cm인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 3 × 15 = 45이므로 5 × □ = 45예요.","□ = 45 ÷ 5 = 9(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#8','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','떡볶이 2인분을 만드는 데 떡 180 g이 필요해요. 떡볶이 5인분을 만들려면 떡이 몇 g 필요한가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X13']::text[],true,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"떡볶이 2인분을 만드는 데 떡 180 g이 필요해요. 떡볶이 5인분을 만들려면 떡이 몇 g 필요한가요?","options":[{"t":"450 g","correct":true},{"t":"183 g","mis":"M6-2-u4-X14"},{"t":"900 g","mis":"M6-2-u4-X12"},{"t":"72 g","mis":"M6-2-u4-X13"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 180 × 5 = 900이므로 2 × □ = 900이에요.","□ = 900 ÷ 2 = 450(g)이에요."],"variant_rule":{"alt":[{"stem":"환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 중국 돈 200위안을 받으려면 우리나라 돈 몇 원을 바꾸어야 하나요?","options":[{"t":"38000원","correct":true},{"t":"57200원","mis":"M6-2-u4-X14"},{"t":"85500원","mis":"M6-2-u4-X13"},{"t":"11400000원","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 57000 × 200 = 11400000이므로 300 × □ = 11400000이에요.","□ = 11400000 ÷ 300 = 38000(원)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#9','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','생활 속에서 비례식을 활용하여 문제를 풀 수 있는 상황으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X02','M6-2-u4-X09']::text[],false,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"생활 속에서 비례식을 활용하여 문제를 풀 수 있는 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건 판매 금액에 따라 물건의 양이 일정하게 많아질 때","correct":true},{"t":"두 양의 차가 늘 같게 유지될 때","mis":"M6-2-u4-X14"},{"t":"한 양만 늘고 다른 양은 그대로일 때","mis":"M6-2-u4-X02"},{"t":"두 양이 서로 상관없이 바뀔 때","mis":"M6-2-u4-X09"}],"explanation":["비례식은 두 양이 같은 비율로 함께 변할 때 쓸 수 있어요.","쌀값이 2배가 되면 살 수 있는 쌀도 2배 — 일정하게 많아져요.","사진을 확대할 때 가로에 따라 세로가 일정하게 늘어나는 것도 같아요(지도서 283)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_basic#10','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',3,'mc','auto','탈레스는 막대 하나를 세워 피라미드의 높이를 쟀어요. 막대 높이 1 m, 막대 그림자의 길이 1.2 m일 때 알맞은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14']::text[],false,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"탈레스는 막대 하나를 세워 피라미드의 높이를 쟀어요. 막대 높이 1 m, 막대 그림자의 길이 1.2 m일 때 알맞은 비례식은 어느 것인가요?","options":[{"t":"1：1.2 = (피라미드 높이)：(피라미드 그림자의 길이)","correct":true},{"t":"1：1.2 = (피라미드 그림자의 길이)：(피라미드 높이)","mis":"M6-2-u4-X13"},{"t":"1.2：1 = (피라미드 높이)：(피라미드 그림자의 길이)","mis":"M6-2-u4-X13"},{"t":"1 + 1.2 = (피라미드 높이) + (피라미드 그림자의 길이)","mis":"M6-2-u4-X14"}],"explanation":["막대 높이와 막대 그림자의 길이의 비는 1：1.2예요.","피라미드도 높이와 그림자 길이의 비율이 같아요.","높이끼리 앞, 그림자끼리 뒤에 맞추어 비례식을 세워요(읽기 자료)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#1','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'sa','auto','가로와 세로의 비가 5：3인 직사각형의 가로가 15 cm예요. 비례식 5：3 = 15：□를 풀면 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"가로와 세로의 비가 5：3인 직사각형의 가로가 15 cm예요. 비례식 5：3 = 15：□를 풀면 세로는 몇 cm인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 3 × 15 = 45이므로 5 × □ = 45예요.","□ = 45 ÷ 5 = 9(cm)예요."],"variant_rule":{"alt":[{"stem":"페인트 4 L로 담장 48 m²을 칠할 수 있어요. 비례식 4：48 = □：60을 풀면 담장 60 m²을 칠하는 데 페인트가 몇 L 필요한가요?","answer":["5"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5(L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#2','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'mc','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸렸어요. 들이가 50 L인 수조를 가득 채우는 데 걸리는 시간은 몇 분 몇 초인가요?',ARRAY['M6-2-u4-X19','M6-2-u4-X14','M6-2-u4-X11']::text[],false,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸렸어요. 들이가 50 L인 수조를 가득 채우는 데 걸리는 시간은 몇 분 몇 초인가요?","options":[{"t":"1분 20초","correct":true},{"t":"80분","mis":"M6-2-u4-X19"},{"t":"59초","mis":"M6-2-u4-X14"},{"t":"31초","mis":"M6-2-u4-X11"}],"explanation":["15：24 = 50：□에서 15 × □ = 24 × 50 = 1200이에요.","□ = 1200 ÷ 15 = 80(초)예요.","80초 = 60초 + 20초 = 1분 20초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#3','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'error','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u4-X11','M6-2-u4-X19','M6-2-u4-X22']::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":3,"kind":"error","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"지호 — 「2：8000 = ★：40000에서 2 × 8000 = ★ × 40000이니 ★은 0.4예요.」","correct":true,"mis_target":"M6-2-u4-X11"},{"t":"유진 — 「외항의 곱 2 × 40000과 내항의 곱 8000 × ★이 같아 ★ = 10이에요.」","mis":"M6-2-u4-X19"},{"t":"희우 — 「2：8000의 두 항에 5를 곱하면 10：40000이에요.」","mis":"M6-2-u4-X19"},{"t":"준기 — 「2：★ = 8000：40000으로 세워도 ★ = 10이에요.」","mis":"M6-2-u4-X22"}],"explanation":["비례식의 성질은 외항끼리, 내항끼리의 곱이 같다는 것이에요.","2 × 40000 = 8000 × ★, ★ = 10이에요.","전항끼리·후항끼리 곱한 지호가 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 21 kWh로 이동할 수 있는 거리를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"민지 — 「21은 6보다 15 크니 40 + 15 = 55(km)예요.」","correct":true,"mis_target":"M6-2-u4-X14"},{"t":"다운 — 「6 × □ = 40 × 21 = 840이니 □ = 140이에요.」","mis":"M6-2-u4-X19"},{"t":"정후 — 「6：40의 두 항에 ⟨7/2⟩을 곱하면 21：140이에요.」","mis":"M6-2-u4-X19"},{"t":"연아 — 「6：21 = 40：□로 세워도 □ = 140이에요.」","mis":"M6-2-u4-X22"}],"explanation":["전기 에너지와 거리는 같은 비율로 함께 늘어요.","6 × □ = 40 × 21, □ = 140이에요.","차이만큼 더한 민지가 잘못 구했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#4','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이 □ m를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],false,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이 □ m를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"1：6 = □：1.5","correct":true},{"t":"1：6 = 1.5：□","mis":"M6-2-u4-X19"},{"t":"1：1.5 = 6：□","mis":"M6-2-u4-X19"},{"t":"2.5：15 = 1.5：□","mis":"M6-2-u4-X19"}],"explanation":["1：6 = 1.5：□, 1：1.5 = 6：□, 2.5：15 = 1.5：□는 모두 □ = 9가 나와요.","1：6 = □：1.5는 형과 첨성대의 자리를 어긋나게 놓았어요.","대응(형끼리, 첨성대끼리)을 맞추어 비례식을 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#5','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 비례식 57000：300 = 38000：□를 풀면 해윤이가 받은 중국 돈은 몇 위안인가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X20','M6-2-u4-X12']::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 비례식 57000：300 = 38000：□를 풀면 해윤이가 받은 중국 돈은 몇 위안인가요?","options":[{"t":"200위안","correct":true},{"t":"19000위안","mis":"M6-2-u4-X13"},{"t":"285위안","mis":"M6-2-u4-X20"},{"t":"11400000위안","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 300 × 38000 = 11400000이므로 57000 × □ = 11400000이에요.","□ = 11400000 ÷ 57000 = 200(위안)이에요."],"variant_rule":{"alt":[{"stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 비례식 6：40 = 21：□를 풀면 21 kWh로 이동할 수 있는 거리는 몇 km인가요?","options":[{"t":"140 km","correct":true},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"⟨21/5⟩ km","mis":"M6-2-u4-X13"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140(km)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#6','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','페인트 4 L로 담장 48 m²을 칠할 수 있어요. 담장 60 m²을 칠할 때 필요한 페인트의 양을 □ L라 하고 세운 비례식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14']::text[],false,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"페인트 4 L로 담장 48 m²을 칠할 수 있어요. 담장 60 m²을 칠할 때 필요한 페인트의 양을 □ L라 하고 세운 비례식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：48 = □：16","mis":"M6-2-u4-X14"}],"explanation":["페인트의 양과 칠한 넓이의 비는 4：48이에요.","□ L와 60 m²의 비도 같은 비율이에요.","그래서 4：48 = □：60, □ = 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#7','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','탈레스가 막대 하나로 피라미드의 높이를 구하려고 해요. 막대 높이와 막대 그림자의 길이 말고 꼭 알아야 하는 것은 무엇인가요?',ARRAY['M6-2-u4-X19']::text[],false,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"탈레스가 막대 하나로 피라미드의 높이를 구하려고 해요. 막대 높이와 막대 그림자의 길이 말고 꼭 알아야 하는 것은 무엇인가요?","options":[{"t":"피라미드 그림자의 길이","correct":true},{"t":"피라미드의 무게","mis":"M6-2-u4-X19"},{"t":"막대의 굵기","mis":"M6-2-u4-X19"},{"t":"그날의 날짜","mis":"M6-2-u4-X19"}],"explanation":["비례식 1：1.2 = (피라미드 높이)：(피라미드 그림자의 길이)를 세워요.","네 항 가운데 세 항을 알아야 나머지 한 항을 구할 수 있어요.","그래서 피라미드 그림자의 길이를 재어야 해요(읽기 자료)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#8','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'mc','auto','경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이는 형의 실제 키보다 몇 m 더 높은가요?',ARRAY['M6-2-u4-X19','M6-2-u4-X14']::text[],false,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":4,"kind":"mc","stem":"경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이는 형의 실제 키보다 몇 m 더 높은가요?","options":[{"t":"7.5 m","correct":true},{"t":"9 m","mis":"M6-2-u4-X19"},{"t":"12.5 m","mis":"M6-2-u4-X14"},{"t":"6 m","mis":"M6-2-u4-X19"}],"explanation":["1：6 = 1.5：□에서 첨성대의 실제 높이는 9 m예요.","형의 실제 키는 1.5 m예요.","9 − 1.5 = 7.5(m) 더 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#9','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 ★ kg이라 하고 비례식을 세운 뒤, 비례식의 성질과 비의 성질 두 가지 방법으로 ★의 값을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 ★ kg이라 하고 비례식을 세운 뒤, 비례식의 성질과 비의 성질 두 가지 방법으로 ★의 값을 구해 보세요.","answer_guide":{"answer":"예: 비례식 2：8000 = ★：40000. 비례식의 성질 — 외항의 곱 2 × 40000 = 80000과 내항의 곱 8000 × ★이 같으므로 ★ = 10. 비의 성질 — 8000에 5를 곱하면 40000이므로 2에도 5를 곱해 ★ = 10. 40000원으로 쌀 10 kg을 살 수 있다.","scoring_points":["비례식 2：8000 = ★：40000을 세웠는가","외항의 곱 = 내항의 곱으로 ★ = 10을 구했는가","두 항에 5를 곱하는 비의 성질로도 구했는가"]},"explanation":["2：8000 = ★：40000이에요.","8000 × ★ = 80000, ★ = 10이에요.","두 항에 5를 곱해도 ★ = 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L06_challenge#10','math',6,2,'u4','L06','tb_g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 21 kWh의 전기 에너지로 이동할 수 있는 거리를 구하고, 친구가 6：40의 전항과 후항에 ⟨7/2⟩을 곱해 구한 방법과 내 방법을 비교해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 21 kWh의 전기 에너지로 이동할 수 있는 거리를 구하고, 친구가 6：40의 전항과 후항에 ⟨7/2⟩을 곱해 구한 방법과 내 방법을 비교해 보세요.","answer_guide":{"answer":"예: 6：40 = 21：□에서 6 × □ = 40 × 21 = 840이므로 □ = 140(km)이다. 친구는 6에 ⟨7/2⟩을 곱하면 21이 되므로 40에도 ⟨7/2⟩을 곱해 140을 구했다. 비례식의 성질과 비의 성질은 방법이 달라도 답이 같다.","scoring_points":["140 km를 구했는가","비례식의 성질로 푼 과정을 썼는가","⟨7/2⟩을 곱한 비의 성질 방법과 견주었는가"]},"explanation":["6 × □ = 840, □ = 140이에요.","6 × ⟨7/2⟩ = 21, 40 × ⟨7/2⟩ = 140이에요.","두 방법 모두 140 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#1','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'sa','auto','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이는 떡을 몇 개 먹으면 되나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이는 떡을 몇 개 먹으면 되나요?","answer":["6"],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."],"variant_rule":{"alt":[{"stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 동생은 떡을 몇 개 먹으면 되나요?","answer":["3"],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","뒤쪽 몫은 전체의 ⟨1/3⟩이에요.","9 × ⟨1/3⟩ = 3(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#2','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이가 먹는 떡의 수는 전체의 몇 분의 몇인가요?',ARRAY['M6-2-u4-X16','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이가 먹는 떡의 수는 전체의 몇 분의 몇인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"2","mis":"M6-2-u4-X16"},{"t":"⟨1/3⟩","mis":"M6-2-u4-X17"},{"t":"⟨1/2⟩","mis":"M6-2-u4-X20"}],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽 몫은 그 가운데 2칸이에요.","그래서 전체의 ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네 가족이 가지는 사과의 수는 전체의 몇 분의 몇인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M6-2-u4-X16"},{"t":"⟨4/7⟩","mis":"M6-2-u4-X17"},{"t":"⟨1/7⟩","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽 몫은 그 가운데 3칸이에요.","그래서 전체의 ⟨3/7⟩이에요."]},{"stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 연아네 가족이 가지는 사과의 수는 전체의 몇 분의 몇인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨4/3⟩","mis":"M6-2-u4-X16"},{"t":"⟨3/7⟩","mis":"M6-2-u4-X17"},{"t":"⟨1/7⟩","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽 몫은 그 가운데 4칸이에요.","그래서 전체의 ⟨4/7⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#3','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'sa','auto','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네 가족은 사과를 몇 개 가지게 되나요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네 가족은 사과를 몇 개 가지게 되나요?","answer":["12"],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽 몫은 전체의 ⟨3/7⟩이에요.","28 × ⟨3/7⟩ = 12(개)예요."],"variant_rule":{"alt":[{"stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 연아네 가족은 사과를 몇 개 가지게 되나요?","answer":["16"],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#4','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 떡 9개를 2：1로 나누는 방법을 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X16','M6-2-u4-X17']::text[],false,'{"seq":4,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 떡 9개를 2：1로 나누는 방법을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"9 × ⟨2/3⟩","correct":true},{"t":"9 ÷ 2","mis":"M6-2-u4-X15"},{"t":"9 × 2","mis":"M6-2-u4-X16"},{"t":"9 × ⟨1/3⟩","mis":"M6-2-u4-X17"}],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","리엘이의 몫은 전체의 ⟨2/3⟩예요.","그래서 9 × ⟨2/3⟩ = 6(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#5','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 쓰려고 해요. 학용품을 사는 데 쓸 용돈은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":5,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 쓰려고 해요. 학용품을 사는 데 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)이에요."],"variant_rule":{"alt":[{"stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 쓰려고 해요. 장난감을 사는 데 쓸 용돈은 얼마인가요?","options":[{"t":"4000원","correct":true},{"t":"6000원","mis":"M6-2-u4-X17"},{"t":"5000원","mis":"M6-2-u4-X15"},{"t":"2000원","mis":"M6-2-u4-X16"}],"explanation":["3：2는 한 묶음이 3 + 2 = 5칸이에요.","뒤쪽 몫은 전체의 ⟨2/5⟩예요.","10000 × ⟨2/5⟩ = 4000(원)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#6','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'sa','auto','정수는 1시간 동안 달리기와 줄넘기를 했어요. 달리기한 시간과 줄넘기한 시간의 비가 7：5일 때 달리기한 시간은 몇 분인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"정수는 1시간 동안 달리기와 줄넘기를 했어요. 달리기한 시간과 줄넘기한 시간의 비가 7：5일 때 달리기한 시간은 몇 분인가요?","answer":["35"],"explanation":["7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)이에요."],"variant_rule":{"alt":[{"stem":"정수는 1시간 동안 달리기와 줄넘기를 했어요. 달리기한 시간과 줄넘기한 시간의 비가 7：5일 때 줄넘기한 시간은 몇 분인가요?","answer":["25"],"explanation":["7：5는 한 묶음이 7 + 5 = 12칸이에요.","뒤쪽 몫은 전체의 ⟨5/12⟩예요.","60 × ⟨5/12⟩ = 25(분)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#7','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','찰흙 420 g을 3：4로 나누어 거북과 악어를 만들려고 해요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],true,'{"seq":7,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들려고 해요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240(g)이에요."],"variant_rule":{"alt":[{"stem":"밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 우유는 몇 mL인가요?","options":[{"t":"450 mL","correct":true},{"t":"750 mL","mis":"M6-2-u4-X17"},{"t":"400 mL","mis":"M6-2-u4-X15"},{"t":"150 mL","mis":"M6-2-u4-X16"}],"explanation":["3：5는 한 묶음이 3 + 5 = 8칸이에요.","앞쪽 몫은 전체의 ⟨3/8⟩이에요.","1200 × ⟨3/8⟩ = 450(mL)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#8','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'ox','auto','밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 우유는 1200 ÷ 3 = 400(mL)예요.',ARRAY['M6-2-u4-X15']::text[],true,'{"seq":8,"concept":"M6-2-u4-C8","difficulty":2,"kind":"ox","stem":"밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 우유는 1200 ÷ 3 = 400(mL)예요.","answer":"X","reason_options":[{"t":"한 묶음이 3 + 5 = 8칸이라 1200 × ⟨3/8⟩ = 450(mL)이어서","correct":true},{"t":"우유가 3이니 전체를 3으로 나누면 되어서","mis":"M6-2-u4-X15"}],"mis":"M6-2-u4-X15","explanation":["3：5는 한 묶음이 3 + 5 = 8칸이에요.","우유는 전체의 ⟨3/8⟩이에요.","1200 × ⟨3/8⟩ = 450(mL) — 1200 ÷ 3은 전체를 한 항으로 나눈 거예요."],"variant_rule":{"alt":[{"stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 찰흙은 420 × ⟨4/3⟩로 구해요.","answer":"X","reason_options":[{"t":"악어의 몫은 전체의 ⟨4/7⟩이라 420 × ⟨4/7⟩ = 240(g)이어서","correct":true},{"t":"악어 4와 거북 3의 비 ⟨4/3⟩를 곱하면 되어서","mis":"M6-2-u4-X16"}],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","악어는 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240(g)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#9','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'sa','auto','남학생 수가 여학생 수의 ⟨3/5⟩이고 학생이 모두 120명이에요. 남학생은 몇 명인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"남학생 수가 여학생 수의 ⟨3/5⟩이고 학생이 모두 120명이에요. 남학생은 몇 명인가요?","answer":["45"],"explanation":["남학생 수와 여학생 수의 비는 3：5예요.","한 묶음은 3 + 5 = 8칸이고 8칸이 120명이에요.","120 × ⟨3/8⟩ = 45(명)이에요."],"variant_rule":{"alt":[{"stem":"남학생 수가 여학생 수의 ⟨3/5⟩이고 학생이 모두 120명이에요. 여학생은 몇 명인가요?","answer":["75"],"explanation":["남학생 수와 여학생 수의 비는 3：5예요.","한 묶음은 3 + 5 = 8칸이고 8칸이 120명이에요.","120 × ⟨5/8⟩ = 75(명)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_basic#10','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',3,'sa','auto','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족이 가족 구성원 수와 상관없이 사과를 반씩 나누면, 정후네 가족은 가족 구성원 수의 비로 나눌 때보다 사과를 몇 개 더 가지게 되나요?','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C8","difficulty":3,"kind":"sa","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족이 가족 구성원 수와 상관없이 사과를 반씩 나누면, 정후네 가족은 가족 구성원 수의 비로 나눌 때보다 사과를 몇 개 더 가지게 되나요?","answer":["2"],"explanation":["반씩 나누면 28 ÷ 2 = 14(개)씩이에요.","가족 구성원 수의 비 3：4로 나누면 정후네는 28 × ⟨3/7⟩ = 12(개)예요.","14 − 12 = 2(개) 더 가져요 — 어느 쪽이 공정한지 까닭을 들어 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#1','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',2,'sa','auto','길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 직사각형의 가로는 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 직사각형의 가로는 몇 cm인가요?","answer":["18"],"explanation":["직사각형의 둘레가 64 cm이니 가로 + 세로 = 32(cm)예요.","32를 9：7로 비례배분해요.","가로는 32 × ⟨9/16⟩ = 18(cm)예요."],"variant_rule":{"alt":[{"stem":"길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 직사각형의 세로는 몇 cm인가요?","answer":["14"],"explanation":["직사각형의 둘레가 64 cm이니 가로 + 세로 = 32(cm)예요.","32를 9：7로 비례배분해요.","세로는 32 × ⟨7/16⟩ = 14(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#2','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',2,'mc','auto','길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 가로와 세로를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17','M6-2-u4-X20']::text[],false,'{"seq":2,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 가로와 세로를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가로가 4 cm 더 길다","correct":true},{"t":"가로가 8 cm 더 길다","mis":"M6-2-u4-X18"},{"t":"세로가 4 cm 더 길다","mis":"M6-2-u4-X17"},{"t":"가로가 2 cm 더 길다","mis":"M6-2-u4-X20"}],"explanation":["가로 + 세로 = 64 ÷ 2 = 32(cm)예요.","가로 32 × ⟨9/16⟩ = 18(cm), 세로 32 × ⟨7/16⟩ = 14(cm)예요.","18 − 14 = 4 — 가로가 4 cm 더 길어요(둘레 64를 바로 나누면 8로 틀려요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#3','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'sa','auto','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 붙임딱지를 리엘이에게 2개, 동생에게 1개씩 번갈아 붙이면 떡 9개를 모두 나눌 때까지 몇 번 붙이게 되나요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C8","difficulty":3,"kind":"sa","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 붙임딱지를 리엘이에게 2개, 동생에게 1개씩 번갈아 붙이면 떡 9개를 모두 나눌 때까지 몇 번 붙이게 되나요?","answer":["3"],"explanation":["한 번에 2 + 1 = 3개씩 붙여요.","9 ÷ 3 = 3(번)이에요.","리엘이 2 × 3 = 6(개), 동생 1 × 3 = 3(개)예요."],"variant_rule":{"alt":[{"stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네에 3개, 연아네에 4개씩 번갈아 나누면 사과 28개를 모두 나눌 때까지 몇 번 나누게 되나요?","answer":["4"],"explanation":["한 번에 3 + 4 = 7개씩 나누어요.","28 ÷ 7 = 4(번)이에요.","정후네 3 × 4 = 12(개), 연아네 4 × 4 = 16(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#4','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이 6개, 동생 3개로 나눈 것이 바른 비례배분인지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X15','M6-2-u4-X17']::text[],false,'{"seq":4,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이 6개, 동생 3개로 나눈 것이 바른 비례배분인지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 몫의 합이 9이고 6：3이 2：1과 비율이 같은지 본다","correct":true},{"t":"6과 3의 차가 2와 1의 차와 같은지 본다","mis":"M6-2-u4-X14"},{"t":"6이 9를 2로 나눈 몫인지 본다","mis":"M6-2-u4-X15"},{"t":"동생 몫이 리엘이 몫의 2배인지 본다","mis":"M6-2-u4-X17"}],"explanation":["비례배분은 전체를 남김없이 주어진 비로 나누는 거예요.","6 + 3 = 9로 전체와 같아요.","6：3의 두 항을 3으로 나누면 2：1 — 비율도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#5','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 우유는 몇 mL인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],true,'{"seq":5,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 우유는 몇 mL인가요?","options":[{"t":"450 mL","correct":true},{"t":"750 mL","mis":"M6-2-u4-X17"},{"t":"400 mL","mis":"M6-2-u4-X15"},{"t":"150 mL","mis":"M6-2-u4-X16"}],"explanation":["3：5는 한 묶음이 3 + 5 = 8칸이에요.","앞쪽 몫은 전체의 ⟨3/8⟩이에요.","1200 × ⟨3/8⟩ = 450(mL)예요."],"variant_rule":{"alt":[{"stem":"밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 홍차는 몇 mL인가요?","options":[{"t":"750 mL","correct":true},{"t":"450 mL","mis":"M6-2-u4-X17"},{"t":"240 mL","mis":"M6-2-u4-X15"},{"t":"150 mL","mis":"M6-2-u4-X16"}],"explanation":["3：5는 한 묶음이 3 + 5 = 8칸이에요.","뒤쪽 몫은 전체의 ⟨5/8⟩예요.","1200 × ⟨5/8⟩ = 750(mL)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#6','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','남학생 수가 여학생 수의 ⟨3/5⟩이고 학생이 모두 120명이에요. 남학생 수와 여학생 수의 비는 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X16','M6-2-u4-X17']::text[],false,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"남학생 수가 여학생 수의 ⟨3/5⟩이고 학생이 모두 120명이에요. 남학생 수와 여학생 수의 비는 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X16"},{"t":"5：8","mis":"M6-2-u4-X17"}],"explanation":["남학생 수가 여학생 수의 ⟨3/5⟩이에요.","여학생을 5칸으로 보면 남학생은 3칸이에요.","그래서 남학생：여학생 = 3：5 — 전체는 8칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#7','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'error','auto','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네 가족이 가지는 사과 수를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X19']::text[],true,'{"seq":7,"concept":"M6-2-u4-C8","difficulty":3,"kind":"error","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네 가족이 가지는 사과 수를 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"태리 — 「정후네가 3이니 28 ÷ 3을 해요.」","correct":true,"mis_target":"M6-2-u4-X15"},{"t":"동하 — 「28 × ⟨3/7⟩ = 12(개)예요.」","mis":"M6-2-u4-X19"},{"t":"리엘 — 「3개, 4개씩 번갈아 4번 나누면 12개예요.」","mis":"M6-2-u4-X19"},{"t":"순달 — 「연아네가 16개이니 28 − 16 = 12(개)예요.」","mis":"M6-2-u4-X19"}],"explanation":["3：4는 한 묶음이 7칸이에요.","정후네는 28 × ⟨3/7⟩ = 12(개)예요.","전체를 한 항(3)으로 나눈 태리가 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"용돈 10000원을 학용품과 장난감에 3：2로 나누어 쓸 때 학용품에 쓸 돈을 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"다현 — 「10000 × ⟨3/2⟩ = 15000(원)이에요.」","correct":true,"mis_target":"M6-2-u4-X16"},{"t":"윤수 — 「10000 × ⟨3/5⟩ = 6000(원)이에요.」","mis":"M6-2-u4-X19"},{"t":"해윤 — 「한 칸이 2000원이니 3칸은 6000원이에요.」","mis":"M6-2-u4-X19"},{"t":"정수 — 「장난감이 4000원이니 10000 − 4000 = 6000(원)이에요.」","mis":"M6-2-u4-X19"}],"explanation":["3：2는 한 묶음이 5칸이에요.","학용품은 10000 × ⟨3/5⟩ = 6000(원)이에요.","⟨3/2⟩을 곱한 다현이가 잘못 구했어요 — 분모는 3 + 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#8','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'mc','auto','정수는 1시간 동안 달리기와 줄넘기를 7：5로 했어요. 달리기한 시간은 줄넘기한 시간보다 몇 분 더 긴가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X17','M6-2-u4-X16']::text[],false,'{"seq":8,"concept":"M6-2-u4-C8","difficulty":4,"kind":"mc","stem":"정수는 1시간 동안 달리기와 줄넘기를 7：5로 했어요. 달리기한 시간은 줄넘기한 시간보다 몇 분 더 긴가요?","options":[{"t":"10분","correct":true},{"t":"2분","mis":"M6-2-u4-X14"},{"t":"35분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"}],"explanation":["1시간 = 60분, 한 묶음은 7 + 5 = 12칸이에요.","달리기 60 × ⟨7/12⟩ = 35(분), 줄넘기 60 × ⟨5/12⟩ = 25(분)이에요.","35 − 25 = 10(분) 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#9','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'essay','teacher','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족은 사과를 몇 개씩 가지게 되는지 구하고, 사과를 공정하게 나누었는지 자신의 생각과 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족은 사과를 몇 개씩 가지게 되는지 구하고, 사과를 공정하게 나누었는지 자신의 생각과 까닭을 써 보세요.","answer_guide":{"answer":"예: 3：4로 비례배분하면 정후네 28 × ⟨3/7⟩ = 12(개), 연아네 28 × ⟨4/7⟩ = 16(개)이다. 가족 구성원 수가 많은 가족이 더 많이 먹으므로 구성원 수의 비로 나누는 것이 공정하다고 생각한다(또는 함께 땄으니 반씩 나누자는 생각도 까닭이 있으면 인정).","scoring_points":["12개와 16개를 바르게 구했는가","공정함에 대한 자기 생각을 밝혔는가","까닭을 근거로 들었는가"]},"explanation":["28 × ⟨3/7⟩ = 12, 28 × ⟨4/7⟩ = 16이에요.","12 + 16 = 28 — 남김없이 나누었어요.","공정함은 까닭을 들어 토의해요(지도서 288)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L07_challenge#10','math',6,2,'u4','L07','tb_g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'essay','teacher','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 떡을 어떻게 나누면 되는지 묶음과 식 두 가지로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 떡을 어떻게 나누면 되는지 묶음과 식 두 가지로 설명해 보세요.","answer_guide":{"answer":"예: 떡 9개를 2 + 1 = 3개씩 묶으면 3묶음이고, 리엘이는 묶음마다 2개, 동생은 1개를 먹어 리엘이 6개, 동생 3개이다. 식으로는 리엘이 9 × ⟨2/3⟩ = 6(개), 동생 9 × ⟨1/3⟩ = 3(개)이다.","scoring_points":["묶음(3개씩 3묶음)으로 설명했는가","9 × ⟨2/3⟩, 9 × ⟨1/3⟩ 식을 썼는가","6개와 3개를 바르게 구했는가"]},"explanation":["3개씩 묶으면 3묶음이에요.","리엘이 2 × 3 = 6(개), 동생 1 × 3 = 3(개)예요.","식으로 9 × ⟨2/3⟩ = 6, 9 × ⟨1/3⟩ = 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#1','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','「영차영차 길 만들기」 섬의 비례식 3：15 = □：30에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 3：15 = □：30에서 □ 안에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 30 = 90이므로 15 × □ = 90이에요.","□ = 90 ÷ 15 = 6이에요."],"variant_rule":{"alt":[{"stem":"「영차영차 길 만들기」 섬의 비례식 2：3 = □：6에서 □ 안에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 2 × 6 = 12이므로 3 × □ = 12예요.","□ = 12 ÷ 3 = 4예요."]},{"stem":"「영차영차 길 만들기」 섬의 비례식 30：36 = □：18에서 □ 안에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 30 × 18 = 540이므로 36 × □ = 540이에요.","□ = 540 ÷ 36 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#2','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','「영차영차 길 만들기」 섬의 비례식 0.6：1.8 = □：9에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 0.6：1.8 = □：9에서 □ 안에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 0.6 × 9 = 5.4이므로 1.8 × □ = 5.4예요.","□ = 5.4 ÷ 1.8 = 3이에요."],"variant_rule":{"alt":[{"stem":"「영차영차 길 만들기」 섬의 비례식 8：□ = 2：1에서 □ 안에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 8 × 1 = 8이므로 2 × □ = 8이에요.","□ = 8 ÷ 2 = 4예요."]},{"stem":"「영차영차 길 만들기」 섬의 비례식 27：□ = 1：⟨1/3⟩에서 □ 안에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 27 × ⟨1/3⟩ = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#3','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구(사용자)가 얻은 수익은 모두 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16','M6-2-u4-X20']::text[],false,'{"seq":3,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구(사용자)가 얻은 수익은 모두 얼마인가요?","options":[{"t":"150000원","correct":true},{"t":"350000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X16"},{"t":"200000원","mis":"M6-2-u4-X20"}],"explanation":["7：3은 한 묶음이 7 + 3 = 10칸이에요.","뒤쪽 몫은 전체의 ⟨3/10⟩이에요.","500000 × ⟨3/10⟩ = 150000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#4','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 낸 사용료의 비 12000：8000을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 낸 사용료의 비 12000：8000을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"4：2","mis":"M6-2-u4-X20"},{"t":"3：3","mis":"M6-2-u4-X20"}],"explanation":["12000과 8000의 최대공약수는 4000이에요.","두 항을 4000으로 나누면 3：2예요.","태리：동하 = 3：2예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 그린 그림 수의 비 4：2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X20"},{"t":"2：2","mis":"M6-2-u4-X20"}],"explanation":["4와 2의 최대공약수는 2예요.","두 항을 2로 나누면 2：1이에요.","태리：동하 = 2：1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#5','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 낸 사용료의 비로 나누면 태리가 가지는 금액은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],true,'{"seq":5,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 낸 사용료의 비로 나누면 태리가 가지는 금액은 얼마인가요?","options":[{"t":"90000원","correct":true},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X15"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽 몫은 전체의 ⟨3/5⟩이에요.","150000 × ⟨3/5⟩ = 90000(원)이에요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 낸 사용료의 비로 나누면 동하가 가지는 금액은 얼마인가요?","options":[{"t":"60000원","correct":true},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"75000원","mis":"M6-2-u4-X15"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["3：2는 한 묶음이 3 + 2 = 5칸이에요.","뒤쪽 몫은 전체의 ⟨2/5⟩예요.","150000 × ⟨2/5⟩ = 60000(원)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#6','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 그린 그림 수의 비로 나누면 태리가 가지는 금액은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],true,'{"seq":6,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 그린 그림 수의 비로 나누면 태리가 가지는 금액은 얼마인가요?","options":[{"t":"100000원","correct":true},{"t":"50000원","mis":"M6-2-u4-X17"},{"t":"75000원","mis":"M6-2-u4-X15"},{"t":"300000원","mis":"M6-2-u4-X16"}],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽 몫은 전체의 ⟨2/3⟩예요.","150000 × ⟨2/3⟩ = 100000(원)이에요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 그린 그림 수의 비로 나누면 동하가 가지는 금액은 얼마인가요?","options":[{"t":"50000원","correct":true},{"t":"100000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X15"},{"t":"75000원","mis":"M6-2-u4-X16"}],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","뒤쪽 몫은 전체의 ⟨1/3⟩이에요.","150000 × ⟨1/3⟩ = 50000(원)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#7','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 가지는 금액을 구할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M6-2-u4-X18','M6-2-u4-X19']::text[],false,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 가지는 금액을 구할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"전체 수익을 7：3으로 나누어 두 친구가 얻은 수익을 구한다","correct":true},{"t":"500000원을 바로 3：2로 나눈다","mis":"M6-2-u4-X18"},{"t":"500000원을 바로 2：1로 나눈다","mis":"M6-2-u4-X18"},{"t":"20000원을 3：2로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["500000원은 회사와 사용자가 먼저 7：3으로 나누어요.","두 친구가 얻은 수익은 500000 × ⟨3/10⟩ = 150000(원)이에요.","그다음 150000원을 정한 기준의 비로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#8','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C6',2,'sa','auto','「영차영차 길 만들기」 섬의 비례식 2.4：18 = 0.4：□에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 2.4：18 = 0.4：□에서 □ 안에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 18 × 0.4 = 7.2이므로 2.4 × □ = 7.2예요.","□ = 7.2 ÷ 2.4 = 3이에요."],"variant_rule":{"alt":[{"stem":"「영차영차 길 만들기」 섬의 비례식 □：5 = ⟨2/5⟩：⟨2/9⟩에서 □ 안에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × ⟨2/5⟩ = 2이므로 ⟨2/9⟩ × □ = 2예요.","□ = 2 ÷ ⟨2/9⟩ = 9예요."]},{"stem":"「영차영차 길 만들기」 섬의 비례식 ⟨2/3⟩：2 = 5：□에서 □ 안에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 2 × 5 = 10이므로 ⟨2/3⟩ × □ = 10이에요.","□ = 10 ÷ ⟨2/3⟩ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#9','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 태리가 가지는 금액은 그린 그림 수의 비로 나눌 때가 낸 사용료의 비로 나눌 때보다 얼마 더 많은가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X19','M6-2-u4-X20']::text[],false,'{"seq":9,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 태리가 가지는 금액은 그린 그림 수의 비로 나눌 때가 낸 사용료의 비로 나눌 때보다 얼마 더 많은가요?","options":[{"t":"10000원","correct":true},{"t":"50000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X19"},{"t":"40000원","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비 3：2로 나누면 태리는 150000 × ⟨3/5⟩ = 90000(원)이에요.","그림 수의 비 2：1로 나누면 태리는 150000 × ⟨2/3⟩ = 100000(원)이에요.","100000 − 90000 = 10000(원) 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_basic#10','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',3,'ox','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 그린 그림 수의 비로 나누는 것만 공정하고, 낸 사용료의 비로 나누는 것은 틀린 방법이에요.',ARRAY['M6-2-u4-X23']::text[],true,'{"seq":10,"concept":"M6-2-u4-C9","difficulty":3,"kind":"ox","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 그린 그림 수의 비로 나누는 것만 공정하고, 낸 사용료의 비로 나누는 것은 틀린 방법이에요.","answer":"X","reason_options":[{"t":"어떤 기준으로 나눌지는 까닭을 들어 정할 수 있고, 기준에 따라 몫이 달라질 뿐이라서","correct":true},{"t":"공정한 기준은 하나뿐이라서","mis":"M6-2-u4-X23"}],"mis":"M6-2-u4-X23","explanation":["사용료의 비로 나누면 태리 90000원, 동하 60000원이에요.","그림 수의 비로 나누면 태리 100000원, 동하 50000원이에요.","두 방법 모두 비례배분이에요 — 어느 쪽이 공정한지는 까닭을 들어 이야기해요(지도서 293)."],"variant_rule":{"alt":[{"stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 가족 구성원 수와 상관없이 반씩 나누자는 생각은 무조건 틀렸어요.","answer":"X","reason_options":[{"t":"공정하게 나누는 방법은 까닭을 들어 여러 가지로 이야기할 수 있어서","correct":true},{"t":"공정한 기준은 가족 구성원 수 하나뿐이라서","mis":"M6-2-u4-X23"}],"explanation":["구성원 수의 비 3：4로 나누면 12개와 16개예요.","반씩 나누면 14개씩이에요.","어느 방법이 공정한지는 근거를 들어 토의해요(지도서 288)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#1','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 가지 방법 가운데 동하가 더 많은 금액을 가지는 방법과 그 금액을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19','M6-2-u4-X17']::text[],false,'{"seq":1,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 가지 방법 가운데 동하가 더 많은 금액을 가지는 방법과 그 금액을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"낸 사용료의 비로 나누기 — 60000원","correct":true},{"t":"그린 그림 수의 비로 나누기 — 50000원","mis":"M6-2-u4-X19"},{"t":"낸 사용료의 비로 나누기 — 90000원","mis":"M6-2-u4-X17"},{"t":"그린 그림 수의 비로 나누기 — 100000원","mis":"M6-2-u4-X17"}],"explanation":["사용료의 비 3：2로 나누면 동하는 150000 × ⟨2/5⟩ = 60000(원)이에요.","그림 수의 비 2：1로 나누면 동하는 150000 × ⟨1/3⟩ = 50000(원)이에요.","동하는 사용료의 비로 나눌 때 60000원으로 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#2','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','「영차영차 길 만들기」 섬의 비례식 □：⟨1/6⟩ = 18：⟨1/2⟩에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 □：⟨1/6⟩ = 18：⟨1/2⟩에서 □ 안에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 ⟨1/6⟩ × 18 = 3이므로 ⟨1/2⟩ × □ = 3이에요.","□ = 3 ÷ ⟨1/2⟩ = 6이에요."],"variant_rule":{"alt":[{"stem":"「영차영차 길 만들기」 섬의 비례식 27：□ = 1：⟨1/3⟩에서 □ 안에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 27 × ⟨1/3⟩ = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#3','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 회사가 가지는 수익은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16','M6-2-u4-X20']::text[],false,'{"seq":3,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 회사가 가지는 수익은 얼마인가요?","options":[{"t":"350000원","correct":true},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X16"},{"t":"400000원","mis":"M6-2-u4-X20"}],"explanation":["7：3은 한 묶음이 7 + 3 = 10칸이에요.","앞쪽 몫은 전체의 ⟨7/10⟩이에요.","500000 × ⟨7/10⟩ = 350000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#4','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','「영차영차 길 만들기」에서 □ 안의 수가 같은 섬끼리 길로 이어요. ⟨2/3⟩：2 = 5：□와 이어지는 섬은 어느 것인가요?',ARRAY['M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"「영차영차 길 만들기」에서 □ 안의 수가 같은 섬끼리 길로 이어요. ⟨2/3⟩：2 = 5：□와 이어지는 섬은 어느 것인가요?","options":[{"t":"30：36 = □：18","correct":true},{"t":"3：15 = □：30","mis":"M6-2-u4-X20"},{"t":"0.6：1.8 = □：9","mis":"M6-2-u4-X20"},{"t":"8：□ = 2：1","mis":"M6-2-u4-X20"}],"explanation":["비례식의 성질(외항의 곱 = 내항의 곱)로 □를 구해요.","⟨2/3⟩：2 = 5：□의 □는 15예요.","□가 15인 섬은 30：36 = □：18이에요."],"variant_rule":{"alt":[{"stem":"「영차영차 길 만들기」에서 □ 안의 수가 같은 섬끼리 길로 이어요. 0.6：1.8 = □：9와 이어지는 섬은 어느 것인가요?","options":[{"t":"2.4：18 = 0.4：□","correct":true},{"t":"2：3 = □：6","mis":"M6-2-u4-X20"},{"t":"27：□ = 1：⟨1/3⟩","mis":"M6-2-u4-X20"},{"t":"□：⟨1/6⟩ = 18：⟨1/2⟩","mis":"M6-2-u4-X20"}],"explanation":["비례식의 성질(외항의 곱 = 내항의 곱)로 □를 구해요.","0.6：1.8 = □：9의 □는 3이에요.","□가 3인 섬은 2.4：18 = 0.4：□예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#5','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 동하가 낸 사용료는 두 친구가 낸 사용료 전체의 몇 분의 몇인가요?',ARRAY['M6-2-u4-X16','M6-2-u4-X17']::text[],true,'{"seq":5,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 동하가 낸 사용료는 두 친구가 낸 사용료 전체의 몇 분의 몇인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M6-2-u4-X16"},{"t":"⟨3/5⟩","mis":"M6-2-u4-X17"},{"t":"⟨1/5⟩","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","뒤쪽 몫은 그 가운데 2칸이에요.","그래서 전체의 ⟨2/5⟩예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 태리가 그린 그림 수는 두 친구가 그린 그림 6장의 몇 분의 몇인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"2","mis":"M6-2-u4-X16"},{"t":"⟨1/3⟩","mis":"M6-2-u4-X17"},{"t":"⟨1/2⟩","mis":"M6-2-u4-X20"}],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽 몫은 그 가운데 2칸이에요.","그래서 전체의 ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#6','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 사용료의 비로 나누든 그림 수의 비로 나누든 달라지지 않는 것은 무엇인가요?',ARRAY['M6-2-u4-X23']::text[],false,'{"seq":6,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 사용료의 비로 나누든 그림 수의 비로 나누든 달라지지 않는 것은 무엇인가요?","options":[{"t":"두 친구가 가지는 금액의 합 150000원","correct":true},{"t":"태리가 가지는 금액","mis":"M6-2-u4-X23"},{"t":"동하가 가지는 금액","mis":"M6-2-u4-X23"},{"t":"두 친구가 가지는 금액의 차","mis":"M6-2-u4-X23"}],"explanation":["사용료의 비: 90000 + 60000 = 150000(원)이에요.","그림 수의 비: 100000 + 50000 = 150000(원)이에요.","나누는 기준이 달라도 나눌 전체(150000원)는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#7','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'error','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 태리가 가지는 금액을 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u4-X18','M6-2-u4-X19','M6-2-u4-X23']::text[],true,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":3,"kind":"error","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 태리가 가지는 금액을 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"지호 — 「500000원을 바로 사용료의 비 3：2로 나누면 태리는 300000원이에요.」","correct":true,"mis_target":"M6-2-u4-X18"},{"t":"유진 — 「먼저 500000 × ⟨3/10⟩ = 150000(원)을 구해요.」","mis":"M6-2-u4-X19"},{"t":"희우 — 「150000 × ⟨3/5⟩ = 90000(원)이에요.」","mis":"M6-2-u4-X19"},{"t":"준기 — 「그림 수의 비로 나누면 150000 × ⟨2/3⟩ = 100000(원)이에요.」","mis":"M6-2-u4-X23"}],"explanation":["먼저 사용자 몫 500000 × ⟨3/10⟩ = 150000(원)을 구해요.","그다음 150000원을 기준의 비로 나눠요.","첫 단계를 건너뛴 지호가 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액에 따라 나눌 때 다현이의 몫을 구한 친구들의 말이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"민지 — 「1500：600을 그대로 더하면 2100칸이라 셀 수 없어요.」","correct":true,"mis_target":"M6-2-u4-X05"},{"t":"다운 — 「1500：600을 간단히 하면 5：2예요.」","mis":"M6-2-u4-X19"},{"t":"정후 — 「35 × ⟨5/7⟩ = 25(장)이에요.」","mis":"M6-2-u4-X19"},{"t":"연아 — 「윤수는 35 × ⟨2/7⟩ = 10(장)이에요.」","mis":"M6-2-u4-X19"}],"explanation":["1500：600의 두 항을 300으로 나누면 5：2예요.","35 × ⟨5/7⟩ = 25(장), 35 × ⟨2/7⟩ = 10(장)이에요.","비를 간단히 하지 않고 포기한 민지가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#8','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 그린 그림 수의 비로 나눌 때 태리가 가지는 금액은 전체 수익 500000원의 몇 분의 몇인가요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],false,'{"seq":8,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 그린 그림 수의 비로 나눌 때 태리가 가지는 금액은 전체 수익 500000원의 몇 분의 몇인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M6-2-u4-X18"},{"t":"⟨3/10⟩","mis":"M6-2-u4-X18"},{"t":"⟨1/10⟩","mis":"M6-2-u4-X17"}],"explanation":["두 친구의 몫은 전체의 ⟨3/10⟩이에요.","태리는 그 가운데 ⟨2/3⟩ — 100000원이에요.","100000 ÷ 500000 = ⟨1/5⟩이에요(⟨3/10⟩ × ⟨2/3⟩ = ⟨1/5⟩)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#9','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 수익을 어떻게 나누는 것이 공정하다고 생각하나요? 그렇게 생각한 까닭과 그 방법으로 나눈 금액을 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 수익을 어떻게 나누는 것이 공정하다고 생각하나요? 그렇게 생각한 까닭과 그 방법으로 나눈 금액을 함께 써 보세요.","answer_guide":{"answer":"예: 작품을 만드는 데 쓴 돈만큼 나누는 것이 공정하다고 생각한다. 사용료의 비 12000：8000 = 3：2로 150000원을 나누면 태리 90000원, 동하 60000원이다. (그림 수의 비 2：1로 나누어 100000원·50000원이라고 써도 까닭이 있으면 인정)","scoring_points":["한 가지 기준을 골라 까닭을 썼는가","두 친구가 얻은 수익 150000원을 먼저 구했는가","고른 기준의 비로 금액을 바르게 나누었는가"]},"explanation":["먼저 500000 × ⟨3/10⟩ = 150000(원)이에요.","사용료의 비 3：2 → 90000원·60000원, 그림 수의 비 2：1 → 100000원·50000원이에요.","옳고 그름보다 까닭을 나누는 것이 중요해요(지도서 293)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_L08_challenge#10','math',6,2,'u4','L08','tb_g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 가지 방법(사용료의 비, 그림 수의 비)으로 수익을 나누어 보고, 문제를 어떻게 풀었는지 단계를 나누어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 가지 방법(사용료의 비, 그림 수의 비)으로 수익을 나누어 보고, 문제를 어떻게 풀었는지 단계를 나누어 설명해 보세요.","answer_guide":{"answer":"예: ① 500000원을 7：3으로 나누어 두 친구의 몫 150000원을 구한다. ② 사용료의 비 12000：8000 = 3：2로 나누면 태리 90000원, 동하 60000원이다. ③ 그림 수의 비 4：2 = 2：1로 나누면 태리 100000원, 동하 50000원이다. 두 방법 모두 150000원을 주어진 비에 따라 비례배분했다.","scoring_points":["150000원을 먼저 구했는가","두 방법의 금액을 바르게 구했는가","두 방법을 비교해 설명했는가"]},"explanation":["500000 × ⟨3/10⟩ = 150000(원)이에요.","3：2 → 90000원·60000원, 2：1 → 100000원·50000원이에요.","전체를 주어진 비로 나누는 비례배분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#1','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',1,'sa','auto','3：11의 전항과 후항에 □를 곱하여도 비율은 같아요. 3：11 → 9：33일 때 □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"3：11의 전항과 후항에 □를 곱하여도 비율은 같아요. 3：11 → 9：33일 때 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항을 견주면 3 × 3 = 9예요.","후항도 11 × 3 = 33 — □는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#2','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C4',1,'mc','auto','⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":2,"concept":"M6-2-u4-C4","difficulty":1,"kind":"mc","stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"16：16","mis":"M6-2-u4-X20"},{"t":"15：17","mis":"M6-2-u4-X20"}],"explanation":["⟨3/4⟩을 0.75로 바꾸어 두 항에 100을 곱하면 75：80이에요.","두 항을 5로 나누면 15：16이에요.","그래서 간단한 자연수의 비는 15：16이에요(지도서 295)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#3','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',1,'mc','auto','5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 찾아 비례식으로 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X09','M6-2-u4-X20']::text[],false,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 찾아 비례식으로 나타낸 것은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = ⟨1/5⟩：⟨1/6⟩","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"},{"t":"⟨1/5⟩：⟨1/6⟩ = 2.4：2.1","mis":"M6-2-u4-X20"}],"explanation":["비율은 ⟨5/6⟩, ⟨8/7⟩, ⟨6/5⟩, ⟨8/7⟩이에요.","비율이 같은 8：7과 2.4：2.1을 등호로 이어요.","8：7 = 2.4：2.1의 외항은 8과 2.1, 내항은 7과 2.4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#4','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',1,'sa','auto','36：9 = □：2에서 □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"36：9 = □：2에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 36 × 2 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#5','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',1,'sa','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸렸어요. 들이가 50 L인 수조를 가득 채우는 데 걸리는 시간은 몇 초인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸렸어요. 들이가 50 L인 수조를 가득 채우는 데 걸리는 시간은 몇 초인가요?","answer":["80"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80(초)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#6','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',1,'mc','auto','찰흙 420 g을 3：4로 나누어 각각 거북과 악어를 만들려고 해요. 악어를 만드는 데 필요한 찰흙의 양은 몇 g인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],false,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"찰흙 420 g을 3：4로 나누어 각각 거북과 악어를 만들려고 해요. 악어를 만드는 데 필요한 찰흙의 양은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240(g)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#7','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',1,'sa','auto','다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 도화지를 다현이와 윤수가 낸 금액에 따라 나누어 가진다면 다현이는 도화지를 몇 장 가져야 하나요?','{}'::text[],false,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":1,"kind":"sa","stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 도화지를 다현이와 윤수가 낸 금액에 따라 나누어 가진다면 다현이는 도화지를 몇 장 가져야 하나요?","answer":["25"],"explanation":["낸 금액의 비 1500：600을 간단한 자연수의 비로 나타내면 5：2예요.","35장을 5：2로 비례배분해요.","다현이는 35 × ⟨5/7⟩ = 25(장)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#8','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',1,'ox','auto','사과 9개로 사과주스 4병을 만들 수 있어요. 한 친구가 「9：4 = □：12에서 전항의 곱 9 × 4 = 36과 후항의 곱 □ × 12가 같으니 □ = 3이고, 사과주스 12병을 만드는 데 사과가 3개 필요해요.」라고 구했어요. 이 방법이 맞나요?',ARRAY['M6-2-u4-X11']::text[],false,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":1,"kind":"ox","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 한 친구가 「9：4 = □：12에서 전항의 곱 9 × 4 = 36과 후항의 곱 □ × 12가 같으니 □ = 3이고, 사과주스 12병을 만드는 데 사과가 3개 필요해요.」라고 구했어요. 이 방법이 맞나요?","answer":"X","reason_options":[{"t":"외항의 곱 9 × 12와 내항의 곱 4 × □가 같아 □ = 27이어야 해서","correct":true},{"t":"전항끼리 곱한 값과 후항끼리 곱한 값이 같아야 해서","mis":"M6-2-u4-X11"}],"mis":"M6-2-u4-X11","explanation":["비례식에서는 외항의 곱과 내항의 곱이 같아요.","9 × 12 = 4 × □, 108 = 4 × □예요.","□ = 27 — 사과가 27개 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#9','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',2,'mc','auto','45：18과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"45：18과 비율이 같은 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"42：15","mis":"M6-2-u4-X01"},{"t":"18：45","mis":"M6-2-u4-X03"},{"t":"45：9","mis":"M6-2-u4-X02"}],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 나누어도 비율은 같아요.","45：18의 두 항을 9로 나누면 5：2예요.","같은 수를 더하거나 빼거나 한 항만 바꾸면 비율이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#10','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C3',2,'mc','auto','2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":10,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"4：8","mis":"M6-2-u4-X20"},{"t":"3：9","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 21：56이에요.","7로 나누면 3：8이에요.","그래서 간단한 자연수의 비는 3：8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#11','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C4',2,'mc','auto','⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07']::text[],false,'{"seq":11,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"}],"explanation":["두 분모의 공배수 12를 곱하면 2：3이에요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 간단한 자연수의 비는 2：3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#12','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',2,'mc','auto','비례식 56：21 = 8：3에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],false,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X11"},{"t":"8과 3","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#13','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',2,'mc','auto','비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X20']::text[],false,'{"seq":13,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?","options":[{"t":"5：2 = 10：4","correct":true},{"t":"7：14 = 6：13","mis":"M6-2-u4-X09"},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"7：22 = 3：11","mis":"M6-2-u4-X09"}],"explanation":["5：2 = 10：4에서 외항의 곱 5 × 4 = 20, 내항의 곱 2 × 10 = 20으로 같아요.","나머지는 91과 84, 39와 40, 77과 66으로 달라요.","두 곱이 같은 식만 비례식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#14','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',2,'mc','auto','어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 이 전기차는 21 kWh의 전기 에너지로 몇 km를 이동할 수 있나요?',ARRAY['M6-2-u4-X12','M6-2-u4-X14','M6-2-u4-X20']::text[],false,'{"seq":14,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 이 전기차는 21 kWh의 전기 에너지로 몇 km를 이동할 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"120 km","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140(km)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#15','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',2,'sa','auto','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 동생은 떡을 몇 개 먹으면 되나요?','{}'::text[],false,'{"seq":15,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 동생은 떡을 몇 개 먹으면 되나요?","answer":["3"],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","뒤쪽 몫은 전체의 ⟨1/3⟩이에요.","9 × ⟨1/3⟩ = 3(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#16','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구(사용자)가 얻은 수익은 모두 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16','M6-2-u4-X20']::text[],false,'{"seq":16,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구(사용자)가 얻은 수익은 모두 얼마인가요?","options":[{"t":"150000원","correct":true},{"t":"350000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X16"},{"t":"200000원","mis":"M6-2-u4-X20"}],"explanation":["7：3은 한 묶음이 7 + 3 = 10칸이에요.","뒤쪽 몫은 전체의 ⟨3/10⟩이에요.","500000 × ⟨3/10⟩ = 150000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#17','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C2',3,'match','auto','간단한 자연수의 비로 나타낸 것끼리 이으세요.','{}'::text[],false,'{"seq":17,"concept":"M6-2-u4-C2","difficulty":3,"kind":"match","stem":"간단한 자연수의 비로 나타낸 것끼리 이으세요.","pairs":[{"l":"28：63","r":"4：9"},{"l":"0.8：0.4","r":"2：1"},{"l":"2.5：3","r":"5：6"}],"mis":"M6-2-u4-X05","explanation":["28：63 → 7로 나누어 4：9예요.","0.8：0.4 → 10을 곱하고 4로 나누어 2：1이에요.","2.5：3 → 10을 곱하고 5로 나누어 5：6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#18','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',3,'ox','auto','2：5와 4：15를 이용하여 비례식 2：5 = 4：15로 나타낼 수 있어요.',ARRAY['M6-2-u4-X09']::text[],false,'{"seq":18,"concept":"M6-2-u4-C5","difficulty":3,"kind":"ox","stem":"2：5와 4：15를 이용하여 비례식 2：5 = 4：15로 나타낼 수 있어요.","answer":"X","reason_options":[{"t":"2：5의 비율은 ⟨2/5⟩, 4：15의 비율은 ⟨4/15⟩로 달라서","correct":true},{"t":"두 비 모두 전항이 후항보다 작아서","mis":"M6-2-u4-X09"}],"mis":"M6-2-u4-X09","explanation":["비례식은 비율이 같은 두 비로만 만들어요.","⟨2/5⟩ = ⟨6/15⟩이고 ⟨4/15⟩와 달라요.","그래서 비례식으로 나타낼 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#19','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',3,'mc','auto','21：28 = 3：7이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X11','M6-2-u4-X10']::text[],false,'{"seq":19,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"21：28 = 3：7이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?","options":[{"t":"외항의 곱 21 × 7 = 147과 내항의 곱 28 × 3 = 84가 달라서","correct":true},{"t":"21：28과 3：7의 수가 서로 달라서","mis":"M6-2-u4-X09"},{"t":"전항끼리의 곱 63과 후항끼리의 곱 196이 달라서","mis":"M6-2-u4-X11"},{"t":"21과 7이 바깥쪽에 있어서","mis":"M6-2-u4-X10"}],"explanation":["비례식의 성질은 외항의 곱과 내항의 곱이 같다는 것이에요.","21 × 7 = 147, 28 × 3 = 84로 달라요.","그래서 비례식이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#20','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',3,'mc','auto','경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이 □ m를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],false,'{"seq":20,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이 □ m를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"1：6 = □：1.5","correct":true},{"t":"1：6 = 1.5：□","mis":"M6-2-u4-X19"},{"t":"1：1.5 = 6：□","mis":"M6-2-u4-X19"},{"t":"2.5：15 = 1.5：□","mis":"M6-2-u4-X19"}],"explanation":["1：6 = 1.5：□, 1：1.5 = 6：□, 2.5：15 = 1.5：□는 모두 □ = 9가 나와요.","1：6 = □：1.5는 대응을 어긋나게 놓았어요.","같은 종류끼리 같은 자리에 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#21','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',3,'sa','auto','길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 직사각형의 가로는 몇 cm인가요?','{}'::text[],false,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":3,"kind":"sa","stem":"길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 직사각형의 가로는 몇 cm인가요?","answer":["18"],"explanation":["가로 + 세로 = 64 ÷ 2 = 32(cm)예요.","32를 9：7로 비례배분해요.","가로는 32 × ⟨9/16⟩ = 18(cm)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#22','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',3,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 태리가 가지는 금액은 그린 그림 수의 비로 나눌 때가 낸 사용료의 비로 나눌 때보다 얼마 더 많은가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X19','M6-2-u4-X20']::text[],false,'{"seq":22,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 태리가 가지는 금액은 그린 그림 수의 비로 나눌 때가 낸 사용료의 비로 나눌 때보다 얼마 더 많은가요?","options":[{"t":"10000원","correct":true},{"t":"50000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X19"},{"t":"40000원","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 태리는 150000 × ⟨3/5⟩ = 90000(원)이에요.","그림 수의 비로 나누면 태리는 150000 × ⟨2/3⟩ = 100000(원)이에요.","100000 − 90000 = 10000(원) 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#23','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',4,'sa','auto','「영차영차 길 만들기」 섬의 비례식 ⟨2/3⟩：2 = 5：□에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":23,"concept":"M6-2-u4-C6","difficulty":4,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 ⟨2/3⟩：2 = 5：□에서 □ 안에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 2 × 5 = 10이므로 ⟨2/3⟩ × □ = 10이에요.","□ = 10 ÷ ⟨2/3⟩ = 15예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#24','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 수익을 어떻게 나누는 것이 공정하다고 생각하나요? 까닭과 그 방법으로 나눈 금액을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 수익을 어떻게 나누는 것이 공정하다고 생각하나요? 까닭과 그 방법으로 나눈 금액을 써 보세요.","answer_guide":{"answer":"예: 작품을 만드는 데 쓴 돈만큼 나누는 것이 공정하므로 사용료의 비 3：2로 150000원을 나누어 태리 90000원, 동하 60000원. (그림 수의 비 2：1 → 100000원·50000원도 까닭이 있으면 인정)","scoring_points":["기준을 고르고 까닭을 썼는가","150000원을 먼저 구했는가","고른 비로 바르게 나누었는가"]},"explanation":["500000 × ⟨3/10⟩ = 150000(원)이에요.","3：2 → 90000원·60000원, 2：1 → 100000원·50000원이에요.","까닭을 들어 말해요(지도서 293)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_a#25','math',6,2,'u4','','tb_g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',4,'essay','teacher','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만드는 데 필요한 사과 수를 비례식을 세워 구하고, 「전항의 곱 = 후항의 곱」으로 구한 친구의 방법이 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만드는 데 필요한 사과 수를 비례식을 세워 구하고, 「전항의 곱 = 후항의 곱」으로 구한 친구의 방법이 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 9：4 = □：12에서 외항의 곱 9 × 12 = 108과 내항의 곱 4 × □가 같으므로 □ = 27(개)이다. 친구는 전항끼리, 후항끼리 곱했는데 비례식의 성질은 외항의 곱과 내항의 곱이 같다는 것이므로 틀렸다.","scoring_points":["9：4 = □：12를 세웠는가","외항의 곱 = 내항의 곱으로 27을 구했는가","전항·후항끼리 곱한 것이 틀린 까닭을 썼는가"]},"explanation":["9：4 = □：12예요.","9 × 12 = 4 × □, □ = 27이에요.","외항끼리, 내항끼리 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#1','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',1,'sa','auto','35：14의 전항과 후항을 □로 나누어도 비율은 같아요. 35：14 → 5：2일 때 □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"35：14의 전항과 후항을 □로 나누어도 비율은 같아요. 35：14 → 5：2일 때 □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항을 견주면 35 ÷ 7 = 5예요.","후항도 14 ÷ 7 = 2 — □는 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#2','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C3',1,'mc','auto','3.5：4.9를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":2,"concept":"M6-2-u4-C3","difficulty":1,"kind":"mc","stem":"3.5：4.9를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：7","correct":true},{"t":"7：5","mis":"M6-2-u4-X03"},{"t":"6：7","mis":"M6-2-u4-X20"},{"t":"5：8","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 35：49예요.","7로 나누면 5：7이에요.","그래서 간단한 자연수의 비는 5：7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#3','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',1,'mc','auto','4：7, 14：21, 2.8：4.9 가운데 비율이 같은 두 비를 찾아 비례식으로 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X20','M6-2-u4-X03']::text[],false,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"4：7, 14：21, 2.8：4.9 가운데 비율이 같은 두 비를 찾아 비례식으로 나타낸 것은 어느 것인가요?","options":[{"t":"4：7 = 2.8：4.9","correct":true},{"t":"4：7 = 14：21","mis":"M6-2-u4-X09"},{"t":"14：21 = 2.8：4.9","mis":"M6-2-u4-X20"},{"t":"4：7 = 21：14","mis":"M6-2-u4-X03"}],"explanation":["비율은 ⟨4/7⟩, ⟨2/3⟩, ⟨4/7⟩예요.","비율이 같은 4：7과 2.8：4.9를 등호로 이어요.","4：7 = 2.8：4.9의 외항은 4와 4.9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#4','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',1,'sa','auto','4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#5','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',1,'sa','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀은 몇 kg인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀은 몇 kg인가요?","answer":["10"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 2 × 40000 = 80000이므로 8000 × □ = 80000이에요.","□ = 80000 ÷ 8000 = 10(kg)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#6','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',1,'mc','auto','찰흙 420 g을 3：4로 나누어 각각 거북과 악어를 만들려고 해요. 거북을 만드는 데 필요한 찰흙의 양은 몇 g인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],false,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"찰흙 420 g을 3：4로 나누어 각각 거북과 악어를 만들려고 해요. 거북을 만드는 데 필요한 찰흙의 양은 몇 g인가요?","options":[{"t":"180 g","correct":true},{"t":"240 g","mis":"M6-2-u4-X17"},{"t":"140 g","mis":"M6-2-u4-X15"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽 몫은 전체의 ⟨3/7⟩이에요.","420 × ⟨3/7⟩ = 180(g)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#7','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C9',1,'sa','auto','다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 도화지를 다현이와 윤수가 낸 금액에 따라 나누어 가진다면 윤수는 도화지를 몇 장 가져야 하나요?','{}'::text[],false,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":1,"kind":"sa","stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 도화지를 다현이와 윤수가 낸 금액에 따라 나누어 가진다면 윤수는 도화지를 몇 장 가져야 하나요?","answer":["10"],"explanation":["낸 금액의 비 1500：600을 간단한 자연수의 비로 나타내면 5：2예요.","35장을 5：2로 비례배분해요.","윤수는 35 × ⟨2/7⟩ = 10(장)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#8','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',1,'ox','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 한 친구가 「2：8000 = ★：40000에서 외항의 곱 2 × 40000과 내항의 곱 8000 × ★이 같으니 ★ = 10이에요.」라고 구했어요. 이 방법이 맞나요?',ARRAY['M6-2-u4-X11']::text[],false,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":1,"kind":"ox","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 한 친구가 「2：8000 = ★：40000에서 외항의 곱 2 × 40000과 내항의 곱 8000 × ★이 같으니 ★ = 10이에요.」라고 구했어요. 이 방법이 맞나요?","answer":"O","reason_options":[{"t":"외항의 곱 80000과 내항의 곱 8000 × ★이 같아 ★ = 10이라서","correct":true},{"t":"전항끼리 곱한 값과 후항끼리 곱한 값이 같아야 해서","mis":"M6-2-u4-X11"}],"mis":"M6-2-u4-X11","explanation":["외항은 2와 40000, 내항은 8000과 ★이에요.","2 × 40000 = 80000 = 8000 × ★이에요.","★ = 10 — 바르게 구했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#9','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',2,'mc','auto','6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 2를 더해 8：6을 구한다","correct":true},{"t":"전항과 후항에 2를 곱해 12：8을 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항을 2로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"비율이 ⟨3/2⟩인 비를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 0이 아닌 같은 수를 곱하거나 나누어 만들어요.","12：8과 3：2는 모두 비율이 ⟨3/2⟩이에요.","8：6은 비율이 ⟨4/3⟩ — 같은 수를 더하는 것은 비의 성질이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#10','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C3',2,'mc','auto','0.8：0.4를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":10,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.8：0.4를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X20"},{"t":"2：2","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 8：4예요.","4로 나누면 2：1이에요.","그래서 간단한 자연수의 비는 2：1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#11','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C4',2,'mc','auto','⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07']::text[],false,'{"seq":11,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"9：14","mis":"M6-2-u4-X03"},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"}],"explanation":["두 분모의 공배수 21을 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 간단한 자연수의 비는 14：9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#12','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',2,'mc','auto','비례식 7：9 = 14：18에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],false,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 7：9 = 14：18에서 내항은 어느 것인가요?","options":[{"t":"9와 14","correct":true},{"t":"7과 18","mis":"M6-2-u4-X10"},{"t":"7과 9","mis":"M6-2-u4-X11"},{"t":"14와 18","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","7：9 = 14：18에서 바깥쪽은 7과 18, 안쪽은 9와 14예요.","그래서 내항은 9와 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#13','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',2,'mc','auto','비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09']::text[],false,'{"seq":13,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"7：14 = 6：13","mis":"M6-2-u4-X09"},{"t":"7：22 = 3：11","mis":"M6-2-u4-X09"}],"explanation":["9：12 = 3：4에서 외항의 곱 9 × 4 = 36, 내항의 곱 12 × 3 = 36으로 같아요.","나머지는 39와 40, 91과 84, 77과 66으로 달라요.","두 곱이 같은 식만 비례식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#14','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',2,'mc','auto','환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 우리나라 돈 38000원을 바꾸면 중국 돈 몇 위안을 받나요?',ARRAY['M6-2-u4-X13','M6-2-u4-X12']::text[],false,'{"seq":14,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 우리나라 돈 38000원을 바꾸면 중국 돈 몇 위안을 받나요?","options":[{"t":"200위안","correct":true},{"t":"19000위안","mis":"M6-2-u4-X13"},{"t":"450위안","mis":"M6-2-u4-X13"},{"t":"11400000위안","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 300 × 38000 = 11400000이므로 57000 × □ = 11400000이에요.","□ = 11400000 ÷ 57000 = 200(위안)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#15','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',2,'sa','auto','정수는 1시간 동안 달리기와 줄넘기를 했어요. 달리기한 시간과 줄넘기한 시간의 비가 7：5일 때 달리기한 시간은 몇 분인가요?','{}'::text[],false,'{"seq":15,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"정수는 1시간 동안 달리기와 줄넘기를 했어요. 달리기한 시간과 줄넘기한 시간의 비가 7：5일 때 달리기한 시간은 몇 분인가요?","answer":["35"],"explanation":["7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#16','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 낸 사용료의 비로 나누면 태리가 가지는 금액은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],false,'{"seq":16,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 낸 사용료의 비로 나누면 태리가 가지는 금액은 얼마인가요?","options":[{"t":"90000원","correct":true},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X15"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽 몫은 전체의 ⟨3/5⟩이에요.","150000 × ⟨3/5⟩ = 90000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#17','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C2',3,'match','auto','간단한 자연수의 비로 나타낸 것끼리 이으세요.','{}'::text[],false,'{"seq":17,"concept":"M6-2-u4-C2","difficulty":3,"kind":"match","stem":"간단한 자연수의 비로 나타낸 것끼리 이으세요.","pairs":[{"l":"54：27","r":"2：1"},{"l":"3.5：4.9","r":"5：7"},{"l":"⟨1/3⟩：⟨3/11⟩","r":"11：9"}],"mis":"M6-2-u4-X05","explanation":["54：27 → 27로 나누어 2：1이에요.","3.5：4.9 → 10을 곱하고 7로 나누어 5：7이에요.","⟨1/3⟩：⟨3/11⟩ → 33을 곱해 11：9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#18','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',3,'ox','auto','4：3과 ⟨1/9⟩：⟨1/12⟩로 비례식을 나타낼 때 ⟨1/9⟩：⟨1/12⟩ = 4：3이라고 써도 돼요.',ARRAY['M6-2-u4-X22']::text[],false,'{"seq":18,"concept":"M6-2-u4-C5","difficulty":3,"kind":"ox","stem":"4：3과 ⟨1/9⟩：⟨1/12⟩로 비례식을 나타낼 때 ⟨1/9⟩：⟨1/12⟩ = 4：3이라고 써도 돼요.","answer":"O","reason_options":[{"t":"두 비의 비율이 ⟨4/3⟩로 같으면 어느 비를 앞에 써도 비례식이라서","correct":true},{"t":"비례식은 주어진 차례대로 4：3을 먼저 써야 해서","mis":"M6-2-u4-X22"}],"mis":"M6-2-u4-X22","explanation":["두 비의 비율은 모두 ⟨4/3⟩예요.","비율이 같은 두 비를 등호로 이으면 비례식이에요.","어느 비를 앞에 써도 돼요(지도서 276)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#19','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',3,'mc','auto','7：14 = 6：13이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X11','M6-2-u4-X10']::text[],false,'{"seq":19,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"7：14 = 6：13이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?","options":[{"t":"외항의 곱 7 × 13 = 91과 내항의 곱 14 × 6 = 84가 달라서","correct":true},{"t":"7과 14, 6과 13의 차가 서로 달라서","mis":"M6-2-u4-X14"},{"t":"전항끼리의 곱 42와 후항끼리의 곱 182가 달라서","mis":"M6-2-u4-X11"},{"t":"7과 13이 바깥쪽에 있어서","mis":"M6-2-u4-X10"}],"explanation":["비례식의 성질은 외항의 곱과 내항의 곱이 같다는 것이에요.","7 × 13 = 91, 14 × 6 = 84로 달라요.","그래서 비례식이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#20','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',3,'mc','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀 ★ kg을 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],false,'{"seq":20,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀 ★ kg을 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2：8000 = 40000：★","correct":true},{"t":"2：8000 = ★：40000","mis":"M6-2-u4-X19"},{"t":"2：★ = 8000：40000","mis":"M6-2-u4-X19"},{"t":"8000：2 = 40000：★","mis":"M6-2-u4-X19"}],"explanation":["2：8000 = ★：40000, 2：★ = 8000：40000, 8000：2 = 40000：★은 모두 ★ = 10이 나와요.","2：8000 = 40000：★은 무게와 값의 자리를 어긋나게 놓았어요.","같은 종류끼리 같은 자리에 놓아요(지도서 283)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#21','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',3,'sa','auto','길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 직사각형의 세로는 몇 cm인가요?','{}'::text[],false,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":3,"kind":"sa","stem":"길이가 64 cm인 철사를 남김없이 써서 가로와 세로의 비가 9：7인 직사각형을 만들었어요. 직사각형의 세로는 몇 cm인가요?","answer":["14"],"explanation":["가로 + 세로 = 64 ÷ 2 = 32(cm)예요.","32를 9：7로 비례배분해요.","세로는 32 × ⟨7/16⟩ = 14(cm)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#22','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C9',3,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 동하가 가지는 금액은 낸 사용료의 비로 나눌 때가 그린 그림 수의 비로 나눌 때보다 얼마 더 많은가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X19','M6-2-u4-X20']::text[],false,'{"seq":22,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 동하가 가지는 금액은 낸 사용료의 비로 나눌 때가 그린 그림 수의 비로 나눌 때보다 얼마 더 많은가요?","options":[{"t":"10000원","correct":true},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X19"},{"t":"20000원","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 동하는 150000 × ⟨2/5⟩ = 60000(원)이에요.","그림 수의 비로 나누면 동하는 150000 × ⟨1/3⟩ = 50000(원)이에요.","60000 − 50000 = 10000(원) 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#23','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',4,'sa','auto','「영차영차 길 만들기」 섬의 비례식 27：□ = 1：⟨1/3⟩에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":23,"concept":"M6-2-u4-C6","difficulty":4,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 27：□ = 1：⟨1/3⟩에서 □ 안에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 27 × ⟨1/3⟩ = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#24','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',4,'essay','teacher','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족이 사과를 어떻게 나누면 공정할지 자신의 생각을 쓰고, 그 방법으로 나눈 사과 수를 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족이 사과를 어떻게 나누면 공정할지 자신의 생각을 쓰고, 그 방법으로 나눈 사과 수를 구해 보세요.","answer_guide":{"answer":"예: 가족 구성원 수가 다르니 3：4로 나누어 정후네 12개, 연아네 16개가 공정하다. (함께 땄으니 14개씩 반씩 나누자는 생각도 까닭이 있으면 인정)","scoring_points":["나누는 방법과 까닭을 썼는가","고른 방법으로 사과 수를 바르게 구했는가","두 몫의 합이 28개인지 확인했는가"]},"explanation":["3：4로 나누면 12개, 16개예요.","반씩 나누면 14개씩이에요.","공정함은 까닭을 들어 토의해요(지도서 288)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_b#25','math',6,2,'u4','','tb_g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',4,'essay','teacher','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 채우는 데 24초가 걸렸어요. 50 L인 수조를 채우는 데 걸리는 시간을 비례식의 성질과 비의 성질 두 가지로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 채우는 데 24초가 걸렸어요. 50 L인 수조를 채우는 데 걸리는 시간을 비례식의 성질과 비의 성질 두 가지로 구해 보세요.","answer_guide":{"answer":"예: 15：24 = 50：□. 비례식의 성질 — 15 × □ = 24 × 50 = 1200, □ = 80. 비의 성질 — 15에 ⟨10/3⟩을 곱하면 50이므로 24에도 ⟨10/3⟩을 곱해 80. 80초가 걸린다.","scoring_points":["비례식을 바르게 세웠는가","비례식의 성질로 80을 구했는가","비의 성질로도 80을 구했는가"]},"explanation":["15：24 = 50：□예요.","15 × □ = 1200, □ = 80이에요.","두 항에 ⟨10/3⟩을 곱해도 80이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#1','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',1,'sa','auto','2：3의 전항과 후항에 똑같이 □를 곱하면 4：6이 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"2：3의 전항과 후항에 똑같이 □를 곱하면 4：6이 돼요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항을 견주면 2 × 2 = 4예요.","후항도 3 × 2 = 6 — □는 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#2','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C4',1,'mc','auto','⟨1/3⟩：⟨3/11⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07']::text[],false,'{"seq":2,"concept":"M6-2-u4-C4","difficulty":1,"kind":"mc","stem":"⟨1/3⟩：⟨3/11⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"11：9","correct":true},{"t":"9：11","mis":"M6-2-u4-X03"},{"t":"3：11","mis":"M6-2-u4-X07"},{"t":"1：3","mis":"M6-2-u4-X07"}],"explanation":["두 분모 3과 11의 공배수 33을 곱해요.","11：9예요.","그래서 간단한 자연수의 비는 11：9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#3','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',1,'mc','auto','6：8, ⟨1/8⟩：⟨1/20⟩, ⟨1/9⟩：⟨1/12⟩, 1.4：3.5 가운데 4：3과 비례식을 만들 수 있는 것을 골라 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07','M6-2-u4-X09']::text[],false,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"6：8, ⟨1/8⟩：⟨1/20⟩, ⟨1/9⟩：⟨1/12⟩, 1.4：3.5 가운데 4：3과 비례식을 만들 수 있는 것을 골라 나타낸 것은 어느 것인가요?","options":[{"t":"4：3 = ⟨1/9⟩：⟨1/12⟩","correct":true},{"t":"4：3 = 6：8","mis":"M6-2-u4-X03"},{"t":"4：3 = ⟨1/8⟩：⟨1/20⟩","mis":"M6-2-u4-X07"},{"t":"4：3 = 1.4：3.5","mis":"M6-2-u4-X09"}],"explanation":["4：3의 비율은 ⟨4/3⟩예요.","⟨1/9⟩：⟨1/12⟩에 36을 곱하면 4：3이에요.","그래서 4：3 = ⟨1/9⟩：⟨1/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#4','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',1,'sa','auto','3：□ = 12：56에서 □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"3：□ = 12：56에서 □에 알맞은 수는 얼마인가요?","answer":["14"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 56 = 168이므로 12 × □ = 168이에요.","□ = 168 ÷ 12 = 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#5','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',1,'sa','auto','경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이는 몇 m인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"경주 첨성대 옆에서 형과 찍은 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이는 몇 m인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 1.5 = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9(m)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#6','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',1,'mc','auto','밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 우유는 몇 mL인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],false,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"밀크티 1200 mL를 만들려고 우유와 홍차를 3：5로 섞어요. 필요한 우유는 몇 mL인가요?","options":[{"t":"450 mL","correct":true},{"t":"750 mL","mis":"M6-2-u4-X17"},{"t":"400 mL","mis":"M6-2-u4-X15"},{"t":"150 mL","mis":"M6-2-u4-X16"}],"explanation":["3：5는 한 묶음이 3 + 5 = 8칸이에요.","앞쪽 몫은 전체의 ⟨3/8⟩이에요.","1200 × ⟨3/8⟩ = 450(mL)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#7','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',1,'sa','auto','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네 가족은 사과를 몇 개 가지게 되나요?','{}'::text[],false,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":1,"kind":"sa","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 정후네 가족은 사과를 몇 개 가지게 되나요?","answer":["12"],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽 몫은 전체의 ⟨3/7⟩이에요.","28 × ⟨3/7⟩ = 12(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#8','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',1,'ox','auto','어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 한 친구가 「6：40 = 21：□에서 6 × □ = 40 × 21 = 840이니 □ = 140이에요.」라고 구했어요. 이 방법이 맞나요?',ARRAY['M6-2-u4-X14']::text[],false,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":1,"kind":"ox","stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 한 친구가 「6：40 = 21：□에서 6 × □ = 40 × 21 = 840이니 □ = 140이에요.」라고 구했어요. 이 방법이 맞나요?","answer":"O","reason_options":[{"t":"외항의 곱 6 × □와 내항의 곱 40 × 21이 같아 □ = 140이라서","correct":true},{"t":"21이 6보다 15 크니 40에 15를 더해야 해서","mis":"M6-2-u4-X14"}],"mis":"M6-2-u4-X14","explanation":["외항은 6과 □, 내항은 40과 21이에요.","6 × □ = 840, □ = 140이에요.","바르게 구했어요 — 140 km를 갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#9','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',2,'mc','auto','일반적으로 쓰는 화면의 가로와 세로의 비는 16：9예요. 가로와 세로의 비가 16：9와 비율이 같은 화면은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"일반적으로 쓰는 화면의 가로와 세로의 비는 16：9예요. 가로와 세로의 비가 16：9와 비율이 같은 화면은 어느 것인가요?","options":[{"t":"다 (가로 32 cm, 세로 18 cm)","correct":true},{"t":"가 (가로 4 cm, 세로 3 cm)","mis":"M6-2-u4-X09"},{"t":"나 (가로 20 cm, 세로 15 cm)","mis":"M6-2-u4-X01"},{"t":"가로와 세로의 비가 16：10인 화면","mis":"M6-2-u4-X02"}],"explanation":["가는 4：3, 나는 20：15, 다는 32：18이에요.","16：9의 전항과 후항에 2를 곱하면 32：18이에요.","그래서 다 화면이 16：9와 비율이 같아요 — 크기가 달라도 모양이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#10','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C3',2,'mc','auto','2.5：3을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02','M6-2-u4-X20']::text[],false,'{"seq":10,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"2.5：3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：6","correct":true},{"t":"6：5","mis":"M6-2-u4-X03"},{"t":"25：3","mis":"M6-2-u4-X02"},{"t":"6：6","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 25：30이에요.","5로 나누면 5：6이에요.","그래서 간단한 자연수의 비는 5：6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#11','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C4',2,'mc','auto','0.5：⟨15/8⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":11,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"0.5：⟨15/8⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：15","correct":true},{"t":"15：4","mis":"M6-2-u4-X03"},{"t":"5：15","mis":"M6-2-u4-X20"},{"t":"4：16","mis":"M6-2-u4-X20"}],"explanation":["0.5를 ⟨1/2⟩로 바꾸어요.","두 분모의 공배수 8을 곱하면 4：15예요.","그래서 간단한 자연수의 비는 4：15예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#12','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',2,'mc','auto','비례식 48：32 = 3：2에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],false,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 48：32 = 3：2에서 외항은 어느 것인가요?","options":[{"t":"48과 2","correct":true},{"t":"32와 3","mis":"M6-2-u4-X10"},{"t":"48과 32","mis":"M6-2-u4-X11"},{"t":"3과 2","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","48：32 = 3：2에서 바깥쪽은 48과 2, 안쪽은 32와 3이에요.","그래서 외항은 48과 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#13','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',2,'mc','auto','비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X20']::text[],false,'{"seq":13,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 12：9","correct":true},{"t":"7：22 = 3：11","mis":"M6-2-u4-X09"},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"7：14 = 6：13","mis":"M6-2-u4-X09"}],"explanation":["8：6 = 12：9에서 외항의 곱 8 × 9 = 72, 내항의 곱 6 × 12 = 72로 같아요.","나머지는 77과 66, 39와 40, 91과 84로 달라요.","두 곱이 같은 식만 비례식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#14','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',2,'mc','auto','떡볶이 2인분을 만드는 데 떡 180 g이 필요해요. 떡볶이 5인분을 만들려면 떡이 몇 g 필요한가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X13']::text[],false,'{"seq":14,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"떡볶이 2인분을 만드는 데 떡 180 g이 필요해요. 떡볶이 5인분을 만들려면 떡이 몇 g 필요한가요?","options":[{"t":"450 g","correct":true},{"t":"183 g","mis":"M6-2-u4-X14"},{"t":"900 g","mis":"M6-2-u4-X12"},{"t":"72 g","mis":"M6-2-u4-X13"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 180 × 5 = 900이므로 2 × □ = 900이에요.","□ = 900 ÷ 2 = 450(g)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#15','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',2,'sa','auto','남학생 수가 여학생 수의 ⟨3/5⟩이고 학생이 모두 120명이에요. 남학생은 몇 명인가요?','{}'::text[],false,'{"seq":15,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"남학생 수가 여학생 수의 ⟨3/5⟩이고 학생이 모두 120명이에요. 남학생은 몇 명인가요?","answer":["45"],"explanation":["남학생 수와 여학생 수의 비는 3：5예요.","한 묶음은 3 + 5 = 8칸이고 8칸이 120명이에요.","120 × ⟨3/8⟩ = 45(명)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#16','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 그린 그림 수의 비로 나누면 동하가 가지는 금액은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],false,'{"seq":16,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 얻은 수익 150000원을 그린 그림 수의 비로 나누면 동하가 가지는 금액은 얼마인가요?","options":[{"t":"50000원","correct":true},{"t":"100000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X15"},{"t":"75000원","mis":"M6-2-u4-X16"}],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","뒤쪽 몫은 전체의 ⟨1/3⟩이에요.","150000 × ⟨1/3⟩ = 50000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#17','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C2',3,'match','auto','간단한 자연수의 비로 나타낸 것끼리 이으세요.','{}'::text[],false,'{"seq":17,"concept":"M6-2-u4-C2","difficulty":3,"kind":"match","stem":"간단한 자연수의 비로 나타낸 것끼리 이으세요.","pairs":[{"l":"2.1：5.6","r":"3：8"},{"l":"⟨1/6⟩：⟨1/4⟩","r":"2：3"},{"l":"0.7：⟨2/5⟩","r":"7：4"}],"mis":"M6-2-u4-X05","explanation":["2.1：5.6 → 10을 곱하고 7로 나누어 3：8이에요.","⟨1/6⟩：⟨1/4⟩ → 12를 곱해 2：3이에요.","0.7：⟨2/5⟩ → 0.7：0.4에 10을 곱해 7：4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#18','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',3,'ox','auto','⟨1/8⟩：⟨1/20⟩과 1.4：3.5로 비례식 ⟨1/8⟩：⟨1/20⟩ = 1.4：3.5를 나타낼 수 있어요.',ARRAY['M6-2-u4-X09']::text[],false,'{"seq":18,"concept":"M6-2-u4-C5","difficulty":3,"kind":"ox","stem":"⟨1/8⟩：⟨1/20⟩과 1.4：3.5로 비례식 ⟨1/8⟩：⟨1/20⟩ = 1.4：3.5를 나타낼 수 있어요.","answer":"X","reason_options":[{"t":"⟨1/8⟩：⟨1/20⟩의 비율은 ⟨5/2⟩, 1.4：3.5의 비율은 ⟨2/5⟩로 달라서","correct":true},{"t":"두 비가 모두 2와 5로 이루어진 비라서","mis":"M6-2-u4-X09"}],"mis":"M6-2-u4-X09","explanation":["⟨1/8⟩：⟨1/20⟩은 5：2예요.","1.4：3.5는 2：5예요.","비율이 달라 비례식이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#19','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',3,'mc','auto','13：8 = 5：3이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X11','M6-2-u4-X10']::text[],false,'{"seq":19,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"13：8 = 5：3이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?","options":[{"t":"외항의 곱 13 × 3 = 39와 내항의 곱 8 × 5 = 40이 달라서","correct":true},{"t":"13과 8의 차와 5와 3의 차가 달라서","mis":"M6-2-u4-X14"},{"t":"전항끼리의 곱 65와 후항끼리의 곱 24가 달라서","mis":"M6-2-u4-X11"},{"t":"13과 3이 바깥쪽에 있어서","mis":"M6-2-u4-X10"}],"explanation":["비례식의 성질은 외항의 곱과 내항의 곱이 같다는 것이에요.","13 × 3 = 39, 8 × 5 = 40으로 달라요.","그래서 비례식이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#20','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',3,'mc','auto','어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 21 kWh로 이동할 수 있는 거리 □ km를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],false,'{"seq":20,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"어느 회사에서 6 kWh의 전기 에너지로 40 km를 이동할 수 있는 전기차를 개발했어요. 21 kWh로 이동할 수 있는 거리 □ km를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"6：40 = □：21","correct":true},{"t":"6：40 = 21：□","mis":"M6-2-u4-X19"},{"t":"6：21 = 40：□","mis":"M6-2-u4-X19"},{"t":"40：6 = □：21","mis":"M6-2-u4-X19"}],"explanation":["6：40 = 21：□, 6：21 = 40：□, 40：6 = □：21은 모두 □ = 140이 나와요.","6：40 = □：21은 에너지와 거리의 자리를 어긋나게 놓았어요.","같은 종류끼리 같은 자리에 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#21','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',3,'sa','auto','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족이 사과를 반씩 나누면, 정후네 가족은 가족 구성원 수의 비로 나눌 때보다 사과를 몇 개 더 가지게 되나요?','{}'::text[],false,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":3,"kind":"sa","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 두 가족이 사과를 반씩 나누면, 정후네 가족은 가족 구성원 수의 비로 나눌 때보다 사과를 몇 개 더 가지게 되나요?","answer":["2"],"explanation":["반씩 나누면 28 ÷ 2 = 14(개)예요.","3：4로 나누면 정후네는 28 × ⟨3/7⟩ = 12(개)예요.","14 − 12 = 2(개) 더 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#22','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',3,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 가지는 금액을 구할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M6-2-u4-X18','M6-2-u4-X19']::text[],false,'{"seq":22,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 두 친구가 가지는 금액을 구할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"전체 수익을 7：3으로 나누어 두 친구가 얻은 수익을 구한다","correct":true},{"t":"500000원을 바로 3：2로 나눈다","mis":"M6-2-u4-X18"},{"t":"500000원을 바로 2：1로 나눈다","mis":"M6-2-u4-X18"},{"t":"20000원을 3：2로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["500000원은 회사와 사용자가 먼저 7：3으로 나누어요.","두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)이에요.","그다음 150000원을 기준의 비로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#23','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',4,'sa','auto','「영차영차 길 만들기」 섬의 비례식 □：⟨1/6⟩ = 18：⟨1/2⟩에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":23,"concept":"M6-2-u4-C6","difficulty":4,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 □：⟨1/6⟩ = 18：⟨1/2⟩에서 □ 안에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 ⟨1/6⟩ × 18 = 3이므로 ⟨1/2⟩ × □ = 3이에요.","□ = 3 ÷ ⟨1/2⟩ = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#24','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',4,'essay','teacher','다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 도화지를 나누는 방법을 정하고 까닭과 함께 몇 장씩 가질지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 도화지를 나누는 방법을 정하고 까닭과 함께 몇 장씩 가질지 써 보세요.","answer_guide":{"answer":"예: 낸 금액에 따라 나누는 것이 공정하므로 1500：600 = 5：2로 나누어 다현 25장, 윤수 10장이다.","scoring_points":["나누는 기준과 까닭을 썼는가","1500：600을 5：2로 간단히 했는가","25장·10장을 바르게 구했는가"]},"explanation":["1500：600 = 5：2예요.","35 × ⟨5/7⟩ = 25, 35 × ⟨2/7⟩ = 10이에요.","까닭을 들어 기준을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_c#25','math',6,2,'u4','','tb_g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',4,'essay','teacher','경주 첨성대 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm이고 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이를 구하는 비례식을 두 가지 꼴로 세워 풀어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"경주 첨성대 사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm이고 형의 실제 키는 1.5 m예요. 첨성대의 실제 높이를 구하는 비례식을 두 가지 꼴로 세워 풀어 보세요.","answer_guide":{"answer":"예: 1：6 = 1.5：□에서 □ = 6 × 1.5 = 9. 1：1.5 = 6：□에서도 1 × □ = 1.5 × 6, □ = 9. 첨성대의 실제 높이는 9 m이다.","scoring_points":["두 가지 꼴의 비례식을 세웠는가","두 식 모두 9를 구했는가","대응을 맞추어 세웠는가"]},"explanation":["2.5：15 = 1：6이에요.","1：6 = 1.5：□ → □ = 9예요.","1：1.5 = 6：□ → □ = 9예요(지도서 284)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#1','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',1,'sa','auto','12：20의 전항과 후항을 똑같이 □로 나누면 3：5가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"12：20의 전항과 후항을 똑같이 □로 나누면 3：5가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항을 견주면 12 ÷ 4 = 3이에요.","후항도 20 ÷ 4 = 5 — □는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#2','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C2',1,'mc','auto','54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":2,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X20"},{"t":"2：2","mis":"M6-2-u4-X20"}],"explanation":["54와 27의 최대공약수는 27이에요.","두 항을 27로 나누면 2：1이에요.","그래서 간단한 자연수의 비는 2：1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#3','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',1,'mc','auto','6：8, ⟨1/8⟩：⟨1/20⟩, ⟨1/9⟩：⟨1/12⟩, 1.4：3.5 가운데 2：5와 비례식을 만들 수 있는 것을 골라 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X09','M6-2-u4-X07']::text[],false,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"6：8, ⟨1/8⟩：⟨1/20⟩, ⟨1/9⟩：⟨1/12⟩, 1.4：3.5 가운데 2：5와 비례식을 만들 수 있는 것을 골라 나타낸 것은 어느 것인가요?","options":[{"t":"2：5 = 1.4：3.5","correct":true},{"t":"2：5 = ⟨1/8⟩：⟨1/20⟩","mis":"M6-2-u4-X03"},{"t":"2：5 = 6：8","mis":"M6-2-u4-X09"},{"t":"2：5 = ⟨1/9⟩：⟨1/12⟩","mis":"M6-2-u4-X07"}],"explanation":["2：5의 비율은 ⟨2/5⟩예요.","1.4：3.5에 10을 곱하고 7로 나누면 2：5예요.","그래서 2：5 = 1.4：3.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#4','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',1,'sa','auto','8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 8 × □ = 72예요.","□ = 72 ÷ 8 = 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#5','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',1,'sa','auto','페인트 4 L로 담장 48 m²을 칠할 수 있어요. 담장 60 m²을 칠할 때 필요한 페인트는 몇 L인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"페인트 4 L로 담장 48 m²을 칠할 수 있어요. 담장 60 m²을 칠할 때 필요한 페인트는 몇 L인가요?","answer":["5"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5(L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#6','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',1,'mc','auto','용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 쓰려고 해요. 학용품을 사는 데 쓸 용돈은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],false,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 쓰려고 해요. 학용품을 사는 데 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#7','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',1,'sa','auto','리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이는 떡을 몇 개 먹으면 되나요?','{}'::text[],false,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":1,"kind":"sa","stem":"리엘이와 동생이 삼촌께서 보내 주신 꿀떡 9개를 2：1로 나누어 먹으려고 해요. 리엘이는 떡을 몇 개 먹으면 되나요?","answer":["6"],"explanation":["2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#8','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',1,'ox','auto','물이 일정하게 나오는 수도로 15 L를 채우는 데 24초가 걸려요. 한 친구가 「15：24 = 50：□에서 15 × 50 = 24 × □이니 □ = 31.25예요.」라고 구했어요. 이 방법이 맞나요?',ARRAY['M6-2-u4-X11']::text[],false,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":1,"kind":"ox","stem":"물이 일정하게 나오는 수도로 15 L를 채우는 데 24초가 걸려요. 한 친구가 「15：24 = 50：□에서 15 × 50 = 24 × □이니 □ = 31.25예요.」라고 구했어요. 이 방법이 맞나요?","answer":"X","reason_options":[{"t":"외항의 곱 15 × □와 내항의 곱 24 × 50이 같아 □ = 80이어야 해서","correct":true},{"t":"전항끼리 곱한 값과 후항끼리 곱한 값이 같아야 해서","mis":"M6-2-u4-X11"}],"mis":"M6-2-u4-X11","explanation":["외항은 15와 □, 내항은 24와 50이에요.","15 × □ = 24 × 50 = 1200이에요.","□ = 80 — 80초가 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#9','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',2,'mc','auto','교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 3개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X02','M6-2-u4-X03']::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"교통안전 도우미분들께 드릴 색종이 꽃다발 1개를 만들려면 초록 색종이 2장과 빨간 색종이 3장이 필요해요. 꽃다발 3개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"6：9","correct":true},{"t":"5：6","mis":"M6-2-u4-X01"},{"t":"6：3","mis":"M6-2-u4-X02"},{"t":"9：6","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 3개면 초록 색종이도 빨간 색종이도 3배가 돼요.","초록 6장, 빨강 9장 — 6：9예요.","비율은 그대로 ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#10','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C3',2,'mc','auto','0.8：1.6을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":10,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.8：1.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：2","correct":true},{"t":"2：1","mis":"M6-2-u4-X03"},{"t":"2：2","mis":"M6-2-u4-X20"},{"t":"1：3","mis":"M6-2-u4-X20"}],"explanation":["두 항에 10을 곱하면 8：16이에요.","8로 나누면 1：2예요.","그래서 간단한 자연수의 비는 1：2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#11','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C4',2,'mc','auto','1.4：⟨1 1/5⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],false,'{"seq":11,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"1.4：⟨1 1/5⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"8：6","mis":"M6-2-u4-X20"},{"t":"7：7","mis":"M6-2-u4-X20"}],"explanation":["⟨1 1/5⟩을 1.2로 바꾸면 1.4：1.2예요.","10을 곱하면 14：12, 2로 나누면 7：6이에요.","그래서 간단한 자연수의 비는 7：6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#12','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',2,'mc','auto','비례식 9：11 = 18：22에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],false,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 9：11 = 18：22에서 내항은 어느 것인가요?","options":[{"t":"11과 18","correct":true},{"t":"9와 22","mis":"M6-2-u4-X10"},{"t":"9와 11","mis":"M6-2-u4-X11"},{"t":"18과 22","mis":"M6-2-u4-X11"}],"explanation":["비례식에서 바깥쪽에 있는 두 항을 외항, 안쪽에 있는 두 항을 내항이라고 해요.","9：11 = 18：22에서 바깥쪽은 9와 22, 안쪽은 11과 18이에요.","그래서 내항은 11과 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#13','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',2,'mc','auto','비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X20']::text[],false,'{"seq":13,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"비례식의 성질을 이용하여 비례식을 찾으려고 해요. 비례식인 것은 어느 것인가요?","options":[{"t":"500：40 = 150：12","correct":true},{"t":"7：22 = 3：11","mis":"M6-2-u4-X09"},{"t":"7：14 = 6：13","mis":"M6-2-u4-X09"},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"}],"explanation":["500：40 = 150：12에서 외항의 곱 500 × 12 = 6000, 내항의 곱 40 × 150 = 6000으로 같아요.","나머지는 77과 66, 91과 84, 39와 40으로 달라요.","두 곱이 같은 식만 비례식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#14','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',2,'mc','auto','환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 중국 돈 200위안을 받으려면 우리나라 돈 몇 원을 바꾸어야 하나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X13','M6-2-u4-X12']::text[],false,'{"seq":14,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 중국 돈 200위안을 받으려면 우리나라 돈 몇 원을 바꾸어야 하나요?","options":[{"t":"38000원","correct":true},{"t":"57200원","mis":"M6-2-u4-X14"},{"t":"85500원","mis":"M6-2-u4-X13"},{"t":"11400000원","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 57000 × 200 = 11400000이므로 300 × □ = 11400000이에요.","□ = 11400000 ÷ 300 = 38000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#15','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',2,'sa','auto','정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 연아네 가족은 사과를 몇 개 가지게 되나요?','{}'::text[],false,'{"seq":15,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"정후네 가족 3명과 연아네 가족 4명이 농장에서 사과 28개를 땄어요. 사과를 가족 구성원 수의 비로 비례배분하려고 해요. 연아네 가족은 사과를 몇 개 가지게 되나요?","answer":["16"],"explanation":["3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#16','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 회사가 가지는 수익은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16','M6-2-u4-X20']::text[],false,'{"seq":16,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 회사가 가지는 수익은 얼마인가요?","options":[{"t":"350000원","correct":true},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X16"},{"t":"400000원","mis":"M6-2-u4-X20"}],"explanation":["7：3은 한 묶음이 7 + 3 = 10칸이에요.","앞쪽 몫은 전체의 ⟨7/10⟩이에요.","500000 × ⟨7/10⟩ = 350000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#17','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C2',3,'match','auto','간단한 자연수의 비로 나타낸 것끼리 이으세요.','{}'::text[],false,'{"seq":17,"concept":"M6-2-u4-C2","difficulty":3,"kind":"match","stem":"간단한 자연수의 비로 나타낸 것끼리 이으세요.","pairs":[{"l":"45：18","r":"5：2"},{"l":"⟨2/3⟩：⟨3/7⟩","r":"14：9"},{"l":"⟨3/4⟩：0.8","r":"15：16"}],"mis":"M6-2-u4-X05","explanation":["45：18 → 9로 나누어 5：2예요.","⟨2/3⟩：⟨3/7⟩ → 21을 곱해 14：9예요.","⟨3/4⟩：0.8 → 0.75：0.8에 100을 곱하고 5로 나누어 15：16이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#18','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',3,'ox','auto','비례식 8：7 = 2.4：2.1을 2.4：2.1 = 8：7로 나타내면 외항은 2.4와 7이에요.',ARRAY['M6-2-u4-X22']::text[],false,'{"seq":18,"concept":"M6-2-u4-C5","difficulty":3,"kind":"ox","stem":"비례식 8：7 = 2.4：2.1을 2.4：2.1 = 8：7로 나타내면 외항은 2.4와 7이에요.","answer":"O","reason_options":[{"t":"2.4：2.1 = 8：7에서 바깥쪽 두 항이 2.4와 7이라서","correct":true},{"t":"비례식을 바꾸어 써도 외항은 언제나 8과 2.1이라서","mis":"M6-2-u4-X22"}],"mis":"M6-2-u4-X22","explanation":["2.4：2.1 = 8：7도 비례식이에요.","이 식의 바깥쪽 두 항은 2.4와 7이에요.","그래서 외항은 2.4와 7이에요(지도서 295 채점)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#19','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',3,'mc','auto','7：22 = 3：11이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X11','M6-2-u4-X10']::text[],false,'{"seq":19,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"7：22 = 3：11이 비례식이 아닌 까닭을 비례식의 성질을 이용하여 바르게 쓴 것은 어느 것인가요?","options":[{"t":"외항의 곱 7 × 11 = 77과 내항의 곱 22 × 3 = 66이 달라서","correct":true},{"t":"22는 11의 2배인데 7은 3의 2배가 아니라서만","mis":"M6-2-u4-X09"},{"t":"전항끼리의 곱 21과 후항끼리의 곱 242가 달라서","mis":"M6-2-u4-X11"},{"t":"7과 11이 바깥쪽에 있어서","mis":"M6-2-u4-X10"}],"explanation":["비례식의 성질은 외항의 곱과 내항의 곱이 같다는 것이에요.","7 × 11 = 77, 22 × 3 = 66으로 달라요.","그래서 비례식이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#20','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',3,'mc','auto','페인트 4 L로 담장 48 m²을 칠할 수 있어요. 담장 60 m²을 칠할 페인트 □ L를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],false,'{"seq":20,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"페인트 4 L로 담장 48 m²을 칠할 수 있어요. 담장 60 m²을 칠할 페인트 □ L를 구하는 비례식으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"4：48 = 60：□","correct":true},{"t":"4：48 = □：60","mis":"M6-2-u4-X19"},{"t":"4：□ = 48：60","mis":"M6-2-u4-X19"},{"t":"48：4 = 60：□","mis":"M6-2-u4-X19"}],"explanation":["4：48 = □：60, 4：□ = 48：60, 48：4 = 60：□은 모두 □ = 5가 나와요.","4：48 = 60：□은 페인트와 넓이의 자리를 어긋나게 놓았어요.","같은 종류끼리 같은 자리에 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#21','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',3,'sa','auto','정수는 1시간 동안 달리기와 줄넘기를 7：5로 했어요. 달리기한 시간은 줄넘기한 시간보다 몇 분 더 긴가요?','{}'::text[],false,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":3,"kind":"sa","stem":"정수는 1시간 동안 달리기와 줄넘기를 7：5로 했어요. 달리기한 시간은 줄넘기한 시간보다 몇 분 더 긴가요?","answer":["10"],"explanation":["60분을 7：5로 비례배분해요.","달리기 60 × ⟨7/12⟩ = 35(분), 줄넘기 60 × ⟨5/12⟩ = 25(분)이에요.","35 − 25 = 10(분) 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#22','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',3,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 사용료의 비로 나누든 그림 수의 비로 나누든 달라지지 않는 것은 무엇인가요?',ARRAY['M6-2-u4-X23']::text[],false,'{"seq":22,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림 6장을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원은 회사와 사용자가 7：3으로 나누어 가져요. 사용료 20000원 가운데 태리가 12000원, 동하가 8000원을 냈고, 그림 6장 가운데 태리가 4장, 동하가 2장을 그렸어요. 사용료의 비로 나누든 그림 수의 비로 나누든 달라지지 않는 것은 무엇인가요?","options":[{"t":"두 친구가 가지는 금액의 합 150000원","correct":true},{"t":"태리가 가지는 금액","mis":"M6-2-u4-X23"},{"t":"동하가 가지는 금액","mis":"M6-2-u4-X23"},{"t":"두 친구가 가지는 금액의 차","mis":"M6-2-u4-X23"}],"explanation":["90000 + 60000 = 150000(원)이에요.","100000 + 50000 = 150000(원)이에요.","나눌 전체는 기준이 달라도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#23','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',4,'sa','auto','「영차영차 길 만들기」 섬의 비례식 □：5 = ⟨2/5⟩：⟨2/9⟩에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":23,"concept":"M6-2-u4-C6","difficulty":4,"kind":"sa","stem":"「영차영차 길 만들기」 섬의 비례식 □：5 = ⟨2/5⟩：⟨2/9⟩에서 □ 안에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × ⟨2/5⟩ = 2이므로 ⟨2/9⟩ × □ = 2예요.","□ = 2 ÷ ⟨2/9⟩ = 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#24','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',4,'essay','teacher','용돈 10000원을 학용품과 장난감에 나누어 쓰려고 해요. 3：2로 나누었을 때 각각 얼마인지 구하고, 왜 그 비로 나누려 했을지 내 생각을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"용돈 10000원을 학용품과 장난감에 나누어 쓰려고 해요. 3：2로 나누었을 때 각각 얼마인지 구하고, 왜 그 비로 나누려 했을지 내 생각을 써 보세요.","answer_guide":{"answer":"예: 10000 × ⟨3/5⟩ = 6000(원), 10000 × ⟨2/5⟩ = 4000(원). 학용품이 공부에 더 필요하니 학용품에 더 많이 쓰려고 3：2로 나눈 것 같다.","scoring_points":["6000원·4000원을 구했는가","비례배분 식을 썼는가","비를 정한 까닭을 생각해 썼는가"]},"explanation":["3：2는 한 묶음이 5칸이에요.","10000 × ⟨3/5⟩ = 6000, 10000 × ⟨2/5⟩ = 4000이에요.","비를 정하는 까닭도 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u4_review_d#25','math',6,2,'u4','','tb_g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',4,'essay','teacher','환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 해윤이가 38000원을 바꾸면 몇 위안을 받는지 비례식을 세워 구하고 푼 과정을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"환전소에서 우리나라 돈 57000원을 중국 돈 300위안으로 바꿀 수 있어요. 해윤이가 38000원을 바꾸면 몇 위안을 받는지 비례식을 세워 구하고 푼 과정을 설명해 보세요.","answer_guide":{"answer":"예: 57000：300 = 38000：□. 외항의 곱 57000 × □와 내항의 곱 300 × 38000 = 11400000이 같으므로 □ = 11400000 ÷ 57000 = 200. 200위안을 받는다.","scoring_points":["비례식을 바르게 세웠는가","두 곱이 같음을 써서 풀었는가","200위안을 구했는가"]},"explanation":["57000：300 = 38000：□예요.","57000 × □ = 11400000이에요.","□ = 200 — 200위안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
